--
-- Name: batch_update_user_streaks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.batch_update_user_streaks() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today DATE;
  v_updated_active INTEGER := 0;
  v_updated_inactive INTEGER := 0;
BEGIN
  v_today := (NOW() AT TIME ZONE 'Europe/Madrid')::DATE;

  -- ===========================================
  -- PASO 1: Actualizar usuarios CON actividad reciente
  -- Técnica: gaps and islands para calcular rachas
  -- ===========================================

  WITH
  -- 1. Obtener días únicos de actividad por usuario (últimos 60 días)
  activity_days AS (
    SELECT DISTINCT
      t.user_id,
      (tq.created_at AT TIME ZONE 'Europe/Madrid')::DATE as day
    FROM test_questions tq
    JOIN tests t ON tq.test_id = t.id
    WHERE tq.created_at >= v_today - 60
  ),

  -- 2. Asignar número de grupo usando gaps and islands
  -- La diferencia (day - row_number) es constante para días consecutivos
  numbered AS (
    SELECT
      user_id,
      day,
      day - (ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY day))::int AS grp
    FROM activity_days
  ),

  -- 3. Calcular rachas (tamaño de cada grupo consecutivo)
  streaks AS (
    SELECT
      user_id,
      MIN(day) as streak_start,
      MAX(day) as streak_end,
      COUNT(*) as streak_length
    FROM numbered
    GROUP BY user_id, grp
  ),

  -- 4. Seleccionar solo la racha más reciente si incluye hoy o ayer
  current_streaks AS (
    SELECT
      user_id,
      streak_end as last_activity,
      CASE
        WHEN streak_end >= v_today - 1 THEN streak_length::INTEGER
        ELSE 0
      END as current_streak
    FROM streaks
    WHERE streak_end = (
      SELECT MAX(s2.streak_end)
      FROM streaks s2
      WHERE s2.user_id = streaks.user_id
    )
  )

  -- 5. Actualizar user_streaks
  UPDATE user_streaks us
  SET
    current_streak = cs.current_streak,
    longest_streak = GREATEST(us.longest_streak, cs.current_streak),
    last_activity_date = cs.last_activity,
    streak_updated_at = NOW()
  FROM current_streaks cs
  WHERE us.user_id = cs.user_id
    AND us.streak_updated_at::DATE < v_today;

  GET DIAGNOSTICS v_updated_active = ROW_COUNT;

  -- ===========================================
  -- PASO 2: Resetear usuarios sin actividad reciente
  -- ===========================================

  UPDATE user_streaks
  SET
    current_streak = 0,
    streak_updated_at = NOW()
  WHERE current_streak > 0
    AND streak_updated_at::DATE < v_today
    AND (last_activity_date IS NULL OR last_activity_date < v_today - 1);

  GET DIAGNOSTICS v_updated_inactive = ROW_COUNT;

  RAISE NOTICE 'batch_update_user_streaks: % activos, % reseteados',
    v_updated_active, v_updated_inactive;
END;
$$;


--
-- Name: FUNCTION batch_update_user_streaks(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.batch_update_user_streaks() IS 'v2.0 - Optimizada con técnica gaps and islands.
Antes: FOR LOOP con N queries (timeout con 800+ usuarios)
Ahora: 2 queries agregadas (<5 segundos)
Ejecutada diariamente por pg_cron.';


--
-- Name: boletin_doc_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.boletin_doc_key(p_url text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  k text;
BEGIN
  IF p_url IS NULL OR btrim(p_url) = '' THEN RETURN NULL; END IF;
  DECLARE mm text[];
  BEGIN
    -- BOE-A/B/S-AAAA-N (disposiciones/anuncios/sumarios)
    k := (regexp_match(p_url, 'BOE-[ABS]-[0-9]{4}-[0-9]+', 'i'))[1];
    IF k IS NOT NULL THEN RETURN upper(k); END IF;
    -- BOCM-AAAAMMDD-N
    k := (regexp_match(p_url, 'BOCM-[0-9]{8}-[0-9]+', 'i'))[1];
    IF k IS NOT NULL THEN RETURN upper(k); END IF;
    -- DOGV (Valencia): dogv.gva.es/datos/AAAA/MM/DD/pdf/AAAA_NNNN → DOGV-AAAA-NNNN (variantes _es/_va convergen)
    mm := regexp_match(p_url, 'dogv\.gva\.es/datos/[0-9]{4}/[0-9]{2}/[0-9]{2}/pdf/([0-9]{4})_([0-9]+)', 'i');
    IF mm IS NOT NULL THEN RETURN 'DOGV-' || mm[1] || '-' || mm[2]; END IF;
    -- BOCYL (Castilla y León): código propio BOCYL-D-DDMMAAAA-NNN-NN
    k := (regexp_match(p_url, 'BOCYL-[A-Z]-[0-9]{8}-[0-9]+-[0-9]+', 'i'))[1];
    IF k IS NOT NULL THEN RETURN upper(k); END IF;
    -- DOGC (Cataluña): portaldogc.gencat.cat ... documentId=N
    k := (regexp_match(p_url, 'portaldogc\.gencat\.cat.*documentId=([0-9]+)', 'i'))[1];
    IF k IS NOT NULL THEN RETURN 'DOGC-' || k; END IF;
    -- BOC (Canarias): gobiernodecanarias.org/boc/AAAA/NNN/NNNN → BOC-AAAA-NNN-NNNN (.html/.pdf convergen)
    mm := regexp_match(p_url, 'gobiernodecanarias\.org/boc/([0-9]{4})/([0-9]+)/([0-9]+)', 'i');
    IF mm IS NOT NULL THEN RETURN 'BOC-' || mm[1] || '-' || mm[2] || '-' || mm[3]; END IF;
    -- BOC variante SEDE: sede.gobiernodecanarias.org/boc/boc-a-AAAA-NNN-NNNN.pdf → mismo doc_key
    mm := regexp_match(p_url, 'gobiernodecanarias\.org/boc/boc-[a-z]-([0-9]{4})-([0-9]+)-([0-9]+)', 'i');
    IF mm IS NOT NULL THEN RETURN 'BOC-' || mm[1] || '-' || mm[2] || '-' || mm[3]; END IF;
    -- BOJA (Andalucía): juntadeandalucia.es/boja/AAAA/NNN/NN → BOJA-AAAA-NNN-NN
    mm := regexp_match(p_url, 'juntadeandalucia\.es/boja/([0-9]{4})/([0-9]+)/([0-9]+)', 'i');
    IF mm IS NOT NULL THEN RETURN 'BOJA-' || mm[1] || '-' || mm[2] || '-' || mm[3]; END IF;
    -- BOJA variante PDF del eBOJA: .../eboja/AAAA/NNN/BOJAAA-NNN-NNNNN-... → mismo doc_key que la web
    mm := regexp_match(p_url, 'juntadeandalucia\.es/eboja/[0-9]{4}/[0-9]+/BOJA([0-9]{2})-([0-9]+)-([0-9]+)', 'i');
    IF mm IS NOT NULL THEN
      RETURN 'BOJA-20' || mm[1] || '-' || (mm[2])::int || '-' || (mm[3])::int;
    END IF;
    -- DOG (Galicia): xunta.gal/dog/Publicados/AAAA/AAAAMMDD/AnuncioXXXX(_es|_gl).html → DOG-XXXX
    k := (regexp_match(p_url, 'xunta\.gal/dog/Publicados/[0-9]{4}/[0-9]{8}/Anuncio([A-Z0-9-]+?)(?:_[a-z]{2})?\.html', 'i'))[1];
    IF k IS NOT NULL THEN RETURN 'DOG-' || upper(k); END IF;
    -- MIA (portal documental Aragón): por CSV; SPA (?csv=) y API (carp-core-mia .../rest/documentos/CSV/pdf) convergen
    k := (regexp_match(p_url, '(?:mia\.aragon\.es/documentos\?csv=|carp-core-mia\.aragon\.es/rest/documentos/)([A-Z0-9]{10,})', 'i'))[1];
    IF k IS NOT NULL THEN RETURN 'MIA-' || upper(k); END IF;
    -- BOPA (Asturias): …/bopa/disposiciones?…dispositionReference=AAAA-NNNNN → BOPA-AAAA-NNNNN
    k := (regexp_match(p_url, 'miprincipado\.asturias\.es/bopa/.*dispositionReference=([0-9]{4}-[0-9]+)', 'i'))[1];
    IF k IS NOT NULL THEN RETURN 'BOPA-' || k; END IF;
    -- BON (Navarra): bon.navarra.es/{es|eu}/anuncio/-/texto/AAAA/NNN/N → BON-AAAA-NNN-N
    mm := regexp_match(p_url, 'bon\.navarra\.es/[a-z]{2}/anuncio/-/texto/([0-9]{4})/([0-9]+)/([0-9]+)', 'i');
    IF mm IS NOT NULL THEN RETURN 'BON-' || mm[1] || '-' || mm[2] || '-' || mm[3]; END IF;
    -- BOME (Melilla): bome/BOME-B-AAAA-NNNN/articulo/NNN → BOME-A-AAAA-NNN (el ARTÍCULO, no el boletín)
    mm := regexp_match(p_url, 'bomemelilla\.es/bome/BOME-[A-Z]-([0-9]{4})-[0-9]+/articulo/([0-9]+)', 'i');
    IF mm IS NOT NULL THEN RETURN 'BOME-A-' || mm[1] || '-' || mm[2]; END IF;
    -- DOCM (Castilla-La Mancha): …?ruta=AAAA/MM/DD/pdf/AAAA_NNNN.pdf → DOCM-AAAA-NNNN
    mm := regexp_match(p_url, 'docm\.jccm\.es/.*ruta=[0-9]{4}/[0-9]{2}/[0-9]{2}/pdf/([0-9]{4})_([0-9]+)', 'i');
    IF mm IS NOT NULL THEN RETURN 'DOCM-' || mm[1] || '-' || mm[2]; END IF;
  END;
  -- reserva: url sin fragmento ni barra final
  RETURN regexp_replace(regexp_replace(btrim(p_url), '#.*$', ''), '/+$', '');
END;
$_$;


--
-- Name: FUNCTION boletin_doc_key(p_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.boletin_doc_key(p_url text) IS 'Espejo SQL de lib/convocatoria/canonicalizeBoletinUrl.cjs para el backend. doc_key canónico (BOE/BOCM/DOGV/BOCYL/DOGC/BOC/BOJA/DOG/MIA/BOPA/BON/BOME/DOCM exactos; resto url normalizada). Usar: ensure_convocatoria_documento(conv, boletin_doc_key(url), url, ...).';


--
-- Name: boletin_doc_key_reconocido(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.boletin_doc_key_reconocido(p_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT p_url IS NOT NULL
     AND btrim(p_url) <> ''
     AND boletin_doc_key(p_url) IS DISTINCT FROM
         regexp_replace(regexp_replace(btrim(p_url), '#.*$', ''), '/+$', '');
$_$;


--
-- Name: FUNCTION boletin_doc_key_reconocido(p_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.boletin_doc_key_reconocido(p_url text) IS 'true si boletin_doc_key() identificó el documento de un boletín conocido (no cayó a la URL de reserva). Úsala en vez de copiar la lista de prefijos: así añadir un boletín no obliga a tocar los llamadores. [T-221]';


--
-- Name: calculate_article_hotness_by_oposicion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_article_hotness_by_oposicion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  target_article_id UUID;
  target_oposicion_value TEXT;
  target_level_value TEXT;
  official_count INTEGER;
  unique_exams INTEGER;
  hotness NUMERIC;
  priority TEXT;
BEGIN
  -- Obtener datos de la pregunta con nombres únicos
  target_article_id := NEW.primary_article_id;
  target_oposicion_value := LOWER(TRIM(NEW.exam_position));
  target_level_value := NEW.official_difficulty_level;
  
  -- Solo procesar si es pregunta oficial
  IF NEW.is_official_exam = TRUE THEN
    
    -- Calcular estadísticas SOLO para esta oposición específica
    SELECT 
      COUNT(*) as total_oficial,
      COUNT(DISTINCT exam_source) as examenes_unicos
    INTO official_count, unique_exams
    FROM questions 
    WHERE primary_article_id = target_article_id 
      AND is_official_exam = TRUE
      AND LOWER(TRIM(exam_position)) = target_oposicion_value;
    
    -- Calcular hotness (0-100)
    hotness := LEAST(100, 
      (official_count * 12) + 
      (unique_exams * 8) + 
      (CASE WHEN official_count >= 2 THEN 15 ELSE official_count * 7 END)
    );
    
    -- Determinar prioridad
    priority := CASE 
      WHEN hotness >= 85 THEN 'critical'
      WHEN hotness >= 65 THEN 'high'
      WHEN hotness >= 40 THEN 'medium'
      ELSE 'low'
    END;
    
    -- Insertar/actualizar en hot_articles con nombres únicos
    INSERT INTO hot_articles (
      article_id, law_id, target_oposicion, oposicion_level,
      total_official_appearances, unique_exams_count, hotness_score,
      priority_level, article_number, law_name, article_title,
      last_calculation_date
    )
    SELECT 
      target_article_id, a.law_id, target_oposicion_value, target_level_value,
      official_count, unique_exams, hotness, priority,
      a.article_number, l.short_name, a.title, NOW()
    FROM articles a
    JOIN laws l ON a.law_id = l.id
    WHERE a.id = target_article_id
    
    ON CONFLICT (article_id, target_oposicion) DO UPDATE SET
      total_official_appearances = EXCLUDED.total_official_appearances,
      unique_exams_count = EXCLUDED.unique_exams_count,
      hotness_score = EXCLUDED.hotness_score,
      priority_level = EXCLUDED.priority_level,
      last_calculation_date = NOW(),
      updated_at = NOW();
    
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: calculate_global_law_question_difficulty(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_global_law_question_difficulty(question_uuid uuid) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    first_attempts_accuracy NUMERIC;
    first_attempts_count INTEGER;
    avg_time_taken NUMERIC;
    difficulty_score NUMERIC;
  BEGIN
    -- Solo contar primeras respuestas para evitar contaminación
    SELECT
      AVG(CASE WHEN is_correct THEN 1.0 ELSE 0.0 END),
      COUNT(*),
      AVG(time_taken_seconds)
    INTO first_attempts_accuracy, first_attempts_count, avg_time_taken
    FROM law_question_first_attempts
    WHERE question_id = question_uuid;

    -- Necesita al menos 5 primeras respuestas para ser confiable
    IF first_attempts_count < 5 THEN
      RETURN NULL; -- Mantener dificultad original hasta tener datos suficientes
    END IF;

    -- Algoritmo de dificultad basado en accuracy y tiempo
    -- Peso: 70% accuracy + 30% tiempo

    -- Normalizar tiempo (30 segundos = óptimo)
    DECLARE
      time_factor NUMERIC := GREATEST(0.1, LEAST(2.0, 30.0 / NULLIF(avg_time_taken, 0)));
      accuracy_score NUMERIC := first_attempts_accuracy;
      combined_score NUMERIC;
    BEGIN
      -- Combinar accuracy y tiempo
      combined_score := (accuracy_score * 0.7) + (time_factor * 0.3);

      -- Convertir a escala de dificultad (0-5)
      -- Score alto = dificultad baja
      difficulty_score := GREATEST(0.1, LEAST(5.0, 5.0 - (combined_score * 4.0)));

      RETURN ROUND(difficulty_score, 2);
    END;
  END;
  $$;


--
-- Name: calculate_global_psychometric_difficulty(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_global_psychometric_difficulty(question_uuid uuid) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    first_attempts_accuracy NUMERIC;
    first_attempts_count INTEGER;
    avg_time_taken NUMERIC;
    difficulty_score NUMERIC;
  BEGIN
    -- Solo contar primeras respuestas para evitar contaminación
    SELECT
      AVG(CASE WHEN is_correct THEN 1.0 ELSE 0.0 END),
      COUNT(*),
      AVG(time_taken_seconds)
    INTO first_attempts_accuracy, first_attempts_count, avg_time_taken
    FROM psychometric_first_attempts
    WHERE question_id = question_uuid;

    -- Necesita al menos 10 primeras respuestas para ser confiable
    IF first_attempts_count < 10 THEN
      RETURN NULL; -- Mantener dificultad original hasta tener datos suficientes
    END IF;

    -- Algoritmo de dificultad: 0-100 (más alto = más difícil)
    -- Factores: precisión (70%) + tiempo promedio (30%)
    difficulty_score := 0;

    -- Factor 1: Precisión (0-70 puntos)
    difficulty_score := difficulty_score + ((1.0 - first_attempts_accuracy) * 70);

    -- Factor 2: Tiempo promedio (0-30 puntos)
    -- Si toma más del doble del tiempo estimado, es más difícil
    IF avg_time_taken IS NOT NULL THEN
      DECLARE
        estimated_time NUMERIC;
      BEGIN
        SELECT estimated_time_seconds INTO estimated_time
        FROM psychometric_questions
        WHERE id = question_uuid;

        IF estimated_time IS NOT NULL AND estimated_time > 0 THEN
          -- Si toma el doble de tiempo = +15 puntos, si es 3x = +30 puntos
          difficulty_score := difficulty_score + LEAST(30, ((avg_time_taken / estimated_time) - 1.0) * 15);
        END IF;
      END;
    END IF;

    -- Normalizar entre 0-100
    RETURN ROUND(GREATEST(0, LEAST(100, difficulty_score)), 1);
  END;
  $$;


--
-- Name: FUNCTION calculate_global_psychometric_difficulty(question_uuid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_global_psychometric_difficulty(question_uuid uuid) IS 'Calcula dificultad global basada SOLO en primeras 
  respuestas para evitar aprendizaje repetido';


--
-- Name: calculate_knowledge_retention_score(integer, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_knowledge_retention_score(time_spent_sec integer, is_correct boolean, difficulty_level text DEFAULT 'medium'::text) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  base_score numeric := 0;
  time_penalty numeric := 0;
  difficulty_multiplier numeric := 1;
  optimal_time integer;
BEGIN
  -- Base score por acierto
  IF is_correct THEN
    base_score := 100;
  ELSE
    base_score := 0;
  END IF;
  
  -- Tiempo óptimo según dificultad
  CASE difficulty_level
    WHEN 'easy' THEN optimal_time := 20;
    WHEN 'medium' THEN optimal_time := 35;
    WHEN 'hard' THEN optimal_time := 50;
    WHEN 'extreme' THEN optimal_time := 75;
    ELSE optimal_time := 35;
  END CASE;
  
  -- Penalización por tiempo excesivo (más suave)
  IF time_spent_sec > optimal_time THEN
    time_penalty := LEAST(30, (time_spent_sec - optimal_time) * 0.3);
  END IF;
  
  -- Bonus por rapidez (si es correcto)
  IF is_correct AND time_spent_sec < optimal_time * 0.7 THEN
    base_score := base_score + 10;
  END IF;
  
  -- Multiplicador por dificultad (bonus por preguntas difíciles)
  CASE difficulty_level
    WHEN 'easy' THEN difficulty_multiplier := 0.8;
    WHEN 'medium' THEN difficulty_multiplier := 1.0;
    WHEN 'hard' THEN difficulty_multiplier := 1.3;
    WHEN 'extreme' THEN difficulty_multiplier := 1.5;
    ELSE difficulty_multiplier := 1.0;
  END CASE;
  
  RETURN GREATEST(0, LEAST(150, (base_score - time_penalty) * difficulty_multiplier));
END;
$$;


--
-- Name: calculate_personal_difficulty(numeric, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_personal_difficulty(p_success_rate numeric, p_total_attempts bigint) RETURNS public.difficulty_level
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Necesita al menos 3 intentos para ser confiable
    IF p_total_attempts < 3 THEN
        RETURN 'medium'::difficulty_level;
    END IF;
    
    -- Algoritmo de clasificación con casting explícito
    IF p_success_rate::DECIMAL >= 0.85 THEN
        RETURN 'easy'::difficulty_level;
    ELSIF p_success_rate::DECIMAL >= 0.65 THEN
        RETURN 'medium'::difficulty_level;
    ELSIF p_success_rate::DECIMAL >= 0.35 THEN
        RETURN 'hard'::difficulty_level;
    ELSE
        RETURN 'extreme'::difficulty_level;
    END IF;
END;
$$;


--
-- Name: FUNCTION calculate_personal_difficulty(p_success_rate numeric, p_total_attempts bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_personal_difficulty(p_success_rate numeric, p_total_attempts bigint) IS 'Algoritmo para calcular dificultad personal basada en tasa de éxito - versión corregida con tipos explícitos';


--
-- Name: calculate_personal_law_question_difficulty(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_personal_law_question_difficulty(user_uuid uuid, question_uuid uuid) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    user_accuracy NUMERIC;
    user_attempts INTEGER;
    avg_user_time NUMERIC;
    personal_difficulty NUMERIC;
  BEGIN
    -- Obtener datos del usuario para esta pregunta específica
    SELECT
      AVG(CASE WHEN tq.is_correct THEN 1.0 ELSE 0.0 END),
      COUNT(*),
      AVG(tq.time_spent_seconds)
    INTO user_accuracy, user_attempts, avg_user_time
    FROM test_questions tq
    JOIN tests t ON t.id = tq.test_id
    WHERE tq.question_id = question_uuid
      AND t.user_id = user_uuid
      AND t.is_completed = true;

    -- Necesita al menos 1 intento
    IF user_attempts < 1 THEN
      RETURN NULL;
    END IF;

    -- Algoritmo similar al global pero con datos personales
    DECLARE
      time_factor NUMERIC := GREATEST(0.1, LEAST(2.0, 30.0 / NULLIF(avg_user_time, 0)));
      combined_score NUMERIC;
    BEGIN
      combined_score := (user_accuracy * 0.7) + (time_factor * 0.3);
      personal_difficulty := GREATEST(0.1, LEAST(5.0, 5.0 - (combined_score * 4.0)));

      RETURN ROUND(personal_difficulty, 2);
    END;
  END;
  $$;


--
-- Name: calculate_personal_psychometric_difficulty(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_personal_psychometric_difficulty(p_user_id uuid, p_question_id uuid) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    user_accuracy NUMERIC;
    user_attempts INTEGER;
    recent_accuracy NUMERIC;
    difficulty_score NUMERIC;
  BEGIN
    -- Obtener estadísticas del usuario para esta pregunta
    SELECT
      AVG(CASE WHEN is_correct THEN 1.0 ELSE 0.0 END),
      COUNT(*)
    INTO user_accuracy, user_attempts
    FROM psychometric_test_answers pta
    JOIN psychometric_test_sessions pts ON pta.session_id = pts.id
    WHERE pts.user_id = p_user_id
    AND pta.question_id = p_question_id;

    -- Si no hay intentos, retornar NULL
    IF user_attempts = 0 THEN
      RETURN NULL;
    END IF;

    -- Si solo tiene 1 intento, usar esa precisión
    IF user_attempts = 1 THEN
      RETURN CASE WHEN user_accuracy = 1.0 THEN 25.0 ELSE 75.0 END;
    END IF;

    -- Para múltiples intentos, calcular dificultad personal
    -- Más intentos fallidos = más difícil para este usuario
    difficulty_score := (1.0 - user_accuracy) * 80; -- Factor base

    -- Penalización por múltiples intentos fallidos
    IF user_attempts > 2 AND user_accuracy < 0.7 THEN
      difficulty_score := difficulty_score + (user_attempts * 5);
    END IF;

    -- Verificar tendencia reciente (últimos 3 intentos)
    SELECT AVG(CASE WHEN is_correct THEN 1.0 ELSE 0.0 END)
    INTO recent_accuracy
    FROM (
      SELECT is_correct
      FROM psychometric_test_answers pta
      JOIN psychometric_test_sessions pts ON pta.session_id = pts.id
      WHERE pts.user_id = p_user_id
      AND pta.question_id = p_question_id
      ORDER BY pta.answered_at DESC
      LIMIT 3
    ) recent;

    -- Si está mejorando, reducir dificultad personal
    IF recent_accuracy > user_accuracy THEN
      difficulty_score := difficulty_score * 0.8;
    END IF;

    -- Normalizar entre 0-100
    RETURN ROUND(GREATEST(0, LEAST(100, difficulty_score)), 1);
  END;
  $$;


--
-- Name: FUNCTION calculate_personal_psychometric_difficulty(p_user_id uuid, p_question_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_personal_psychometric_difficulty(p_user_id uuid, p_question_id uuid) IS 'Calcula dificultad personal considerando TODAS las 
  respuestas del usuario';


--
-- Name: calculate_question_global_difficulty(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_question_global_difficulty(p_question_id uuid) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_first_attempts_accuracy NUMERIC;
  v_first_attempts_count INTEGER;
  v_avg_time_taken NUMERIC;
  v_avg_confidence NUMERIC;
  v_difficulty_score NUMERIC;
BEGIN
  SELECT
    AVG(CASE WHEN is_correct THEN 1.0 ELSE 0.0 END) * 100,
    COUNT(*),
    AVG(time_spent_seconds),
    AVG(
      CASE confidence_level
        WHEN 'very_sure' THEN 4.0
        WHEN 'sure' THEN 3.0
        WHEN 'unsure' THEN 2.0
        WHEN 'guessing' THEN 1.0
        ELSE 2.5
      END
    )
  INTO v_first_attempts_accuracy, v_first_attempts_count, v_avg_time_taken,
       v_avg_confidence
  FROM question_first_attempts
  WHERE question_id = p_question_id;

  -- Umbral ≥1 (antes ≥3). Ver doc en compute_global_difficulty_from_sums.
  IF v_first_attempts_count < 1 OR v_first_attempts_count IS NULL THEN
    RETURN NULL;
  END IF;

  v_difficulty_score := 0;
  v_difficulty_score := v_difficulty_score + ((100 - v_first_attempts_accuracy) * 0.5);

  IF v_avg_time_taken IS NOT NULL THEN
    v_difficulty_score := v_difficulty_score +
      CASE
        WHEN v_avg_time_taken > 120 THEN 25
        WHEN v_avg_time_taken > 90 THEN 15
        WHEN v_avg_time_taken > 60 THEN 8
        ELSE 0
      END;
  END IF;

  IF v_avg_confidence IS NOT NULL THEN
    v_difficulty_score := v_difficulty_score +
      CASE
        WHEN v_avg_confidence < 2.0 THEN 25
        WHEN v_avg_confidence < 2.5 THEN 15
        WHEN v_avg_confidence < 3.0 THEN 8
        ELSE 0
      END;
  END IF;

  RETURN ROUND(GREATEST(0, LEAST(100, v_difficulty_score)), 1);
END;
$$;


--
-- Name: calculate_question_hash(text, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_question_hash(p_question_text text, p_option_a text, p_option_b text, p_option_c text, p_option_d text, p_correct_option integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN MD5(
    LOWER(TRIM(p_question_text)) ||
    LOWER(TRIM(p_option_a)) ||
    LOWER(TRIM(p_option_b)) ||
    LOWER(TRIM(p_option_c)) ||
    LOWER(TRIM(p_option_d))
  );
END;
$$;


--
-- Name: calculate_trace_duration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_trace_duration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.ended_at IS NOT NULL AND NEW.started_at IS NOT NULL THEN
    NEW.duration_ms := EXTRACT(EPOCH FROM (NEW.ended_at - NEW.started_at)) * 1000;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: calculate_trend(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_trend(p_user_id uuid, p_question_id uuid) RETURNS character varying
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    recent_success DECIMAL;
    historical_success DECIMAL;
BEGIN
    -- Éxito en últimos 5 intentos vs anteriores
    SELECT 
        COALESCE(AVG(CASE WHEN is_correct THEN 1.0 ELSE 0.0 END), 0)
    INTO recent_success
    FROM test_questions tq
    JOIN tests t ON t.id = tq.test_id
    WHERE t.user_id = p_user_id 
    AND tq.question_id = p_question_id
    AND t.completed_at >= NOW() - INTERVAL '30 days'
    ORDER BY t.completed_at DESC
    LIMIT 5;
    
    -- Si no hay suficientes datos
    IF recent_success IS NULL THEN
        RETURN 'stable';
    END IF;
    
    -- Éxito histórico (excluyendo últimos 5)
    SELECT 
        COALESCE(AVG(CASE WHEN is_correct THEN 1.0 ELSE 0.0 END), recent_success)
    INTO historical_success
    FROM test_questions tq
    JOIN tests t ON t.id = tq.test_id
    WHERE t.user_id = p_user_id 
    AND tq.question_id = p_question_id
    AND t.completed_at < (
        SELECT t2.completed_at 
        FROM tests t2 
        JOIN test_questions tq2 ON t2.id = tq2.test_id
        WHERE t2.user_id = p_user_id AND tq2.question_id = p_question_id
        ORDER BY t2.completed_at DESC 
        LIMIT 1 OFFSET 5
    );
    
    -- Comparar tendencias
    IF recent_success > historical_success + 0.2 THEN
        RETURN 'improving';
    ELSIF recent_success < historical_success - 0.2 THEN
        RETURN 'declining';
    ELSE
        RETURN 'stable';
    END IF;
END;
$$;


--
-- Name: FUNCTION calculate_trend(p_user_id uuid, p_question_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calculate_trend(p_user_id uuid, p_question_id uuid) IS 'Calcula tendencia de mejora/empeoramiento en pregunta específica';


--
-- Name: calculate_user_streak(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_user_streak(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
    v_today DATE;
    v_activity_dates DATE[];
    v_check_date DATE;
    v_streak INTEGER := 0;
    v_has_today BOOLEAN;
    v_has_yesterday BOOLEAN;
  BEGIN
    v_today := (NOW() AT TIME ZONE 'Europe/Madrid')::DATE;

    -- UNA sola query: obtener todas las fechas con actividad (últimos 365 días)
    SELECT ARRAY_AGG(DISTINCT activity_date ORDER BY activity_date DESC)
    INTO v_activity_dates
    FROM (
      SELECT (tq.created_at AT TIME ZONE 'Europe/Madrid')::DATE as activity_date
      FROM test_questions tq
      JOIN tests t ON tq.test_id = t.id
      WHERE t.user_id = p_user_id
        AND tq.created_at >= (v_today - INTERVAL '365 days')
    ) dates;

    -- Sin actividad = racha 0
    IF v_activity_dates IS NULL OR array_length(v_activity_dates, 1) IS NULL THEN
      RETURN 0;
    END IF;

    -- Verificar actividad hoy o ayer
    v_has_today := v_today = ANY(v_activity_dates);
    v_has_yesterday := (v_today - 1) = ANY(v_activity_dates);

    IF v_has_today THEN
      v_check_date := v_today;
    ELSIF v_has_yesterday THEN
      v_check_date := v_today - 1;
    ELSE
      RETURN 0;  -- Sin actividad hoy ni ayer
    END IF;

    -- Contar días consecutivos hacia atrás
    WHILE v_check_date = ANY(v_activity_dates) LOOP
      v_streak := v_streak + 1;
      v_check_date := v_check_date - 1;

      IF v_streak > 365 THEN
        EXIT;
      END IF;
    END LOOP;

    RETURN v_streak;
  END;
  $$;


--
-- Name: check_hot_article_for_current_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_hot_article_for_current_user(article_id_param uuid, user_id_param uuid) RETURNS TABLE(is_hot boolean, hotness_score numeric, priority_level text, hot_message text, user_oposicion text, also_appears_in_other_oposiciones boolean, other_oposiciones_info jsonb, curiosity_message text, complete_message text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  user_target_oposicion TEXT;
  hot_article_record RECORD;
  other_oposiciones_count INTEGER;
  other_oposiciones_data JSONB;
  message_text TEXT;
  curiosity_text TEXT;
BEGIN
  -- Obtener target_oposicion del usuario
  SELECT up.target_oposicion INTO user_target_oposicion
  FROM user_profiles up
  WHERE up.id = user_id_param;
  
  IF user_target_oposicion IS NULL THEN
    RETURN QUERY SELECT false, 0::numeric, 'none'::text, null::text, null::text, false, '{}'::jsonb, null::text, null::text;
    RETURN;
  END IF;
  
  -- 🔧 BUSCAR HOT ARTICLE CON NORMALIZACIÓN FLEXIBLE
  SELECT ha.* INTO hot_article_record
  FROM hot_articles ha
  WHERE ha.article_id = article_id_param
    AND (
      ha.target_oposicion = user_target_oposicion OR
      -- Normalizar comparando sin espacios y guiones
      REPLACE(REPLACE(LOWER(ha.target_oposicion), ' ', '_'), '-', '_') = 
      REPLACE(REPLACE(LOWER(user_target_oposicion), ' ', '_'), '-', '_') OR
      -- Variantes específicas conocidas
      (user_target_oposicion = 'auxiliar_administrativo_estado' AND ha.target_oposicion IN ('auxiliar administrativo del estado', 'auxiliar administrativo'))
    )
  ORDER BY ha.hotness_score DESC
  LIMIT 1;
  
  -- Si no encontramos hot article para esta oposición, retornar false
  IF hot_article_record IS NULL THEN
    RETURN QUERY SELECT false, 0::numeric, 'none'::text, null::text, user_target_oposicion, false, '{}'::jsonb, null::text, null::text;
    RETURN;
  END IF;
  
  -- Construir mensaje principal según prioridad
  CASE hot_article_record.priority_level
    WHEN 'critical' THEN
      message_text := format('🔥🔥🔥 ARTÍCULO SÚPER CRÍTICO: Apareció en %s exámenes oficiales reales. ¡Memorízalo perfecto!', 
                           hot_article_record.total_official_appearances);
    WHEN 'high' THEN
      message_text := format('🔥🔥 ARTÍCULO MUY IMPORTANTE: Apareció en %s exámenes oficiales. Estudia bien este tema.', 
                           hot_article_record.total_official_appearances);
    WHEN 'medium' THEN
      message_text := format('🔥 ARTÍCULO IMPORTANTE: Apareció en %s exámenes oficiales. Vale la pena conocerlo bien.', 
                           hot_article_record.total_official_appearances);
    ELSE
      message_text := format('📚 Artículo de interés: Apareció en %s exámenes oficiales.', 
                           hot_article_record.total_official_appearances);
  END CASE;
  
  -- Buscar en otras oposiciones
  SELECT COUNT(*), COALESCE(json_agg(json_build_object(
    'oposicion', ha2.target_oposicion,
    'apariciones', ha2.total_official_appearances,
    'prioridad', ha2.priority_level
  )), '[]'::json)::jsonb
  INTO other_oposiciones_count, other_oposiciones_data
  FROM hot_articles ha2
  WHERE ha2.article_id = article_id_param 
    AND ha2.target_oposicion != hot_article_record.target_oposicion;
  
  -- Mensaje de curiosidad
  IF other_oposiciones_count > 0 THEN
    curiosity_text := format('💡 CURIOSIDAD: Este artículo también es importante en %s oposiciones más: %s', 
                            other_oposiciones_count,
                            (SELECT string_agg(ha3.target_oposicion, ', ') FROM hot_articles ha3
                             WHERE ha3.article_id = article_id_param AND ha3.target_oposicion != hot_article_record.target_oposicion));
  END IF;
  
  -- Retornar resultado
  RETURN QUERY SELECT 
    true,
    hot_article_record.hotness_score,
    hot_article_record.priority_level,
    message_text,
    user_target_oposicion,
    (other_oposiciones_count > 0),
    other_oposiciones_data,
    curiosity_text,
    COALESCE(message_text || E'\n' || curiosity_text, message_text);
    
END;
$$;


--
-- Name: check_if_article_is_hot_for_user_oposicion(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_if_article_is_hot_for_user_oposicion(article_id_param uuid, user_oposicion text) RETURNS TABLE(is_hot boolean, hotness_score numeric, priority_level text, total_appearances integer, hot_message text, also_appears_in_other_oposiciones boolean, other_oposiciones_info jsonb, curiosity_message text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  hot_data RECORD;
  message TEXT;
  other_oposiciones JSONB;
  curiosity_text TEXT;
  has_other_oposiciones BOOLEAN := FALSE;
BEGIN
  -- Normalizar entrada
  user_oposicion := LOWER(TRIM(user_oposicion));
  
  -- Buscar si es hot para esta oposición específica
  SELECT 
    ha.hotness_score,
    ha.priority_level,
    ha.total_official_appearances
  INTO hot_data
  FROM hot_articles ha
  WHERE ha.article_id = article_id_param
    AND ha.target_oposicion = user_oposicion;
  
  -- Si es hot (> 40), generar mensaje y buscar otras oposiciones
  IF FOUND AND hot_data.hotness_score > 40 THEN
    
    -- Generar mensaje principal
    message := CASE 
      WHEN hot_data.priority_level = 'critical' THEN
        '🔥 ¡ARTÍCULO CRÍTICO en ' || UPPER(user_oposicion) || '! Ha aparecido ' || 
        hot_data.total_appearances || ' veces en exámenes oficiales de esta oposición.'
      WHEN hot_data.priority_level = 'high' THEN
        '⚡ Artículo de ALTA FRECUENCIA en ' || UPPER(user_oposicion) || ' (' || 
        hot_data.total_appearances || ' apariciones oficiales).'
      ELSE
        '📌 Este artículo ha aparecido ' || hot_data.total_appearances || 
        ' veces en exámenes oficiales de ' || UPPER(user_oposicion) || '.'
    END;
    
    -- Buscar en otras oposiciones
    SELECT 
      COALESCE(
        jsonb_object_agg(
          ha_other.target_oposicion,
          jsonb_build_object(
            'appearances', ha_other.total_official_appearances,
            'priority_level', ha_other.priority_level
          )
        ),
        '{}'::JSONB
      ),
      COUNT(*) > 0
    INTO other_oposiciones, has_other_oposiciones
    FROM hot_articles ha_other
    WHERE ha_other.article_id = article_id_param
      AND ha_other.target_oposicion != user_oposicion
      AND ha_other.hotness_score > 20;
    
    -- Generar mensaje de curiosidad
    IF has_other_oposiciones THEN
      SELECT 
        '💡 Curiosidad: También aparece en ' ||
        string_agg(
          CASE 
            WHEN (value->>'priority_level') = 'critical' THEN
              '🔥 ' || UPPER(key) || ' (' || (value->>'appearances') || ' veces, CRÍTICO)'
            WHEN (value->>'priority_level') = 'high' THEN
              '⚡ ' || UPPER(key) || ' (' || (value->>'appearances') || ' veces, ALTO)'
            ELSE
              '📌 ' || UPPER(key) || ' (' || (value->>'appearances') || ' veces)'
          END,
          ', '
        ) || '.'
      INTO curiosity_text
      FROM jsonb_each(other_oposiciones);
    ELSE
      curiosity_text := '📍 Este artículo parece ser específico de ' || UPPER(user_oposicion) || '.';
    END IF;
    
    RETURN QUERY SELECT 
      TRUE,
      hot_data.hotness_score,
      hot_data.priority_level,
      hot_data.total_appearances,
      message,
      has_other_oposiciones,
      other_oposiciones,
      curiosity_text;
  ELSE
    RETURN QUERY SELECT 
      FALSE,
      0::NUMERIC,
      'none'::TEXT,
      0,
      NULL::TEXT,
      FALSE,
      '{}'::JSONB,
      NULL::TEXT;
  END IF;
END;
$$;


--
-- Name: check_questions_availability(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_questions_availability(p_tema_number integer, p_difficulty_filter text DEFAULT 'all'::text) RETURNS TABLE(difficulty_requested text, questions_available integer, can_generate_test boolean, sample_articles text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p_difficulty_filter,
    COUNT(q.id)::INTEGER,
    (COUNT(q.id) > 0),
    ARRAY_AGG(DISTINCT CONCAT('Art. ', a.article_number))
  FROM questions q
  JOIN articles a ON q.primary_article_id = a.id
  JOIN laws l ON a.law_id = l.id
  JOIN topic_scope ts ON l.id = ts.law_id
  JOIN topics t ON ts.topic_id = t.id
  WHERE t.topic_number = p_tema_number
    AND t.position_type = 'auxiliar_administrativo'
    AND a.article_number = ANY(ts.article_numbers)
    AND q.is_active = true
    AND (
      CASE 
        WHEN p_difficulty_filter = 'all' THEN true
        WHEN p_difficulty_filter = 'easy' THEN q.difficulty = 'easy'
        WHEN p_difficulty_filter = 'medium' THEN q.difficulty = 'medium'
        WHEN p_difficulty_filter = 'hard' THEN q.difficulty = 'hard'
        WHEN p_difficulty_filter = 'extreme' THEN q.difficulty = 'extreme'
        ELSE true
      END
    );
END;
$$;


--
-- Name: check_stats_drift(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_stats_drift(p_sample_size integer DEFAULT 30) RETURNS TABLE(checked integer, drifts_found integer, errors integer, duration_ms integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_start TIMESTAMPTZ := clock_timestamp();
  v_user RECORD;
  v_checked INT := 0;
  v_drifts INT := 0;
  v_errors INT := 0;
  v_stored_int INT;
  v_fresh_int INT;
  v_stored_big BIGINT;
  v_fresh_big BIGINT;
  v_dim RECORD;
  v_t_cutoff TIMESTAMPTZ;
  v_backfill_t0 TIMESTAMPTZ;
BEGIN
  -- Detectar si hay backfill activo (presencia de marcador en la
  -- tabla auxiliar). Si lo hay, usar su t0 como cutoff superior — las
  -- tablas materializadas solo reflejan datos < t0 hasta que termine
  -- el backfill; comparar con todo test_questions daría falsos
  -- positivos durante el progreso.
  BEGIN
    SELECT (p.stats->>'t0')::TIMESTAMPTZ INTO v_backfill_t0
    FROM backfill_materialized_stats_progress p
    WHERE p.user_id = '00000000-0000-0000-0000-000000000000'::uuid
      AND p.stats->>'role' = 'backfill_start_marker';
  EXCEPTION WHEN OTHERS THEN
    v_backfill_t0 := NULL;  -- tabla no existe → no hay backfill, OK
  END;

  -- Si el backfill terminó (todos los users tienen fila en progress),
  -- ignoramos t0 y usamos NOW(). Detección: si quedan pendientes,
  -- estamos en backfill.
  IF v_backfill_t0 IS NOT NULL THEN
    DECLARE
      v_pending INT;
    BEGIN
      SELECT COUNT(*)::INT INTO v_pending
      FROM tests t
      WHERE t.user_id IS NOT NULL
        AND t.created_at < v_backfill_t0
        AND NOT EXISTS (
          SELECT 1 FROM backfill_materialized_stats_progress p
          WHERE p.user_id = t.user_id
        );
      IF v_pending = 0 THEN
        v_backfill_t0 := NULL;  -- backfill completo, libera el cutoff
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_backfill_t0 := NULL;
    END;
  END IF;

  v_t_cutoff := COALESCE(v_backfill_t0, NOW());

  FOR v_user IN
    SELECT s.user_id
    FROM user_stats_summary s
    WHERE s.total_questions > 0
      AND s.updated_at > NOW() - INTERVAL '30 days'
    ORDER BY random()
    LIMIT p_sample_size
  LOOP
    BEGIN
      -- ──────────────────────────────────────────────────────────
      -- 1) user_stats_summary.total_questions
      -- ──────────────────────────────────────────────────────────
      SELECT s.total_questions INTO v_stored_int
      FROM user_stats_summary s WHERE s.user_id = v_user.user_id;
      SELECT COUNT(*)::int INTO v_fresh_int
      FROM test_questions tq JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = v_user.user_id AND tq.created_at < v_t_cutoff;
      IF COALESCE(v_stored_int, 0) <> COALESCE(v_fresh_int, 0) THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value)
        VALUES ('user_stats_summary', v_user.user_id, 'total_questions', v_stored_int, v_fresh_int);
        v_drifts := v_drifts + 1;
      END IF;

      -- ──────────────────────────────────────────────────────────
      -- 2) user_stats_summary.correct_answers
      -- ──────────────────────────────────────────────────────────
      SELECT s.correct_answers INTO v_stored_int
      FROM user_stats_summary s WHERE s.user_id = v_user.user_id;
      SELECT COALESCE(SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END), 0)::int INTO v_fresh_int
      FROM test_questions tq JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = v_user.user_id AND tq.created_at < v_t_cutoff;
      IF COALESCE(v_stored_int, 0) <> COALESCE(v_fresh_int, 0) THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value)
        VALUES ('user_stats_summary', v_user.user_id, 'correct_answers', v_stored_int, v_fresh_int);
        v_drifts := v_drifts + 1;
      END IF;

      -- ──────────────────────────────────────────────────────────
      -- 3) user_stats_summary.total_tests (NUEVO)
      -- ──────────────────────────────────────────────────────────
      SELECT s.total_tests INTO v_stored_int
      FROM user_stats_summary s WHERE s.user_id = v_user.user_id;
      SELECT COUNT(*)::int INTO v_fresh_int
      FROM tests t
      WHERE t.user_id = v_user.user_id AND t.is_completed = true
        AND t.created_at < v_t_cutoff;
      IF COALESCE(v_stored_int, 0) <> COALESCE(v_fresh_int, 0) THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value)
        VALUES ('user_stats_summary', v_user.user_id, 'total_tests', v_stored_int, v_fresh_int);
        v_drifts := v_drifts + 1;
      END IF;

      -- ──────────────────────────────────────────────────────────
      -- 4) user_stats_summary.total_time_seconds (NUEVO)
      -- ──────────────────────────────────────────────────────────
      SELECT s.total_time_seconds INTO v_stored_big
      FROM user_stats_summary s WHERE s.user_id = v_user.user_id;
      SELECT COALESCE(SUM(tq.time_spent_seconds), 0)::bigint INTO v_fresh_big
      FROM test_questions tq JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = v_user.user_id AND tq.created_at < v_t_cutoff;
      IF COALESCE(v_stored_big, 0) <> COALESCE(v_fresh_big, 0) THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value)
        VALUES ('user_stats_summary', v_user.user_id, 'total_time_seconds', v_stored_big, v_fresh_big);
        v_drifts := v_drifts + 1;
      END IF;

      -- ──────────────────────────────────────────────────────────
      -- 5) user_question_history_v2 row count
      -- ──────────────────────────────────────────────────────────
      SELECT COUNT(*)::int INTO v_stored_int
      FROM user_question_history_v2 WHERE user_id = v_user.user_id;
      SELECT COUNT(DISTINCT tq.question_id)::int INTO v_fresh_int
      FROM test_questions tq JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = v_user.user_id AND tq.question_id IS NOT NULL;
      IF COALESCE(v_stored_int, 0) <> COALESCE(v_fresh_int, 0) THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value, notes)
        VALUES ('user_question_history_v2', v_user.user_id, 'row_count',
                v_stored_int, v_fresh_int,
                'count(uqh_v2 rows) vs count(distinct question_id en test_questions)');
        v_drifts := v_drifts + 1;
      END IF;

      -- ──────────────────────────────────────────────────────────
      -- 6) user_difficulty_stats sum (NUEVO)
      -- Verifica la SUMA total por user; si individual difficulty
      -- diverge, también lo hará la suma. Detección más barata que
      -- recorrer cada difficulty separado.
      -- ──────────────────────────────────────────────────────────
      SELECT COALESCE(SUM(total_questions), 0)::int INTO v_stored_int
      FROM user_difficulty_stats WHERE user_id = v_user.user_id;
      SELECT COUNT(*)::int INTO v_fresh_int
      FROM test_questions tq JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = v_user.user_id
        AND tq.difficulty IN ('easy','medium','hard','extreme')
        AND tq.created_at < v_t_cutoff;
      IF v_stored_int <> v_fresh_int THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value)
        VALUES ('user_difficulty_stats', v_user.user_id, 'sum_total_questions', v_stored_int, v_fresh_int);
        v_drifts := v_drifts + 1;
      END IF;

      -- ──────────────────────────────────────────────────────────
      -- 7) user_hourly_stats sum (NUEVO)
      -- ──────────────────────────────────────────────────────────
      SELECT COALESCE(SUM(total_questions), 0)::int INTO v_stored_int
      FROM user_hourly_stats WHERE user_id = v_user.user_id;
      SELECT COUNT(*)::int INTO v_fresh_int
      FROM test_questions tq JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = v_user.user_id AND tq.created_at < v_t_cutoff;
      IF v_stored_int <> v_fresh_int THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value)
        VALUES ('user_hourly_stats', v_user.user_id, 'sum_total_questions', v_stored_int, v_fresh_int);
        v_drifts := v_drifts + 1;
      END IF;

      -- ──────────────────────────────────────────────────────────
      -- 8) user_article_stats sum (NUEVO) — solo article_number IS NOT NULL
      -- ──────────────────────────────────────────────────────────
      SELECT COALESCE(SUM(total_questions), 0)::int INTO v_stored_int
      FROM user_article_stats WHERE user_id = v_user.user_id;
      SELECT COUNT(*)::int INTO v_fresh_int
      FROM test_questions tq JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = v_user.user_id
        AND tq.article_number IS NOT NULL
        AND tq.created_at < v_t_cutoff;
      IF v_stored_int <> v_fresh_int THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value)
        VALUES ('user_article_stats', v_user.user_id, 'sum_total_questions', v_stored_int, v_fresh_int);
        v_drifts := v_drifts + 1;
      END IF;

      -- ──────────────────────────────────────────────────────────
      -- 9) user_daily_stats sum (NUEVO)
      -- ──────────────────────────────────────────────────────────
      SELECT COALESCE(SUM(total_questions), 0)::int INTO v_stored_int
      FROM user_daily_stats WHERE user_id = v_user.user_id;
      SELECT COUNT(*)::int INTO v_fresh_int
      FROM test_questions tq JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = v_user.user_id AND tq.created_at < v_t_cutoff;
      IF v_stored_int <> v_fresh_int THEN
        INSERT INTO stats_drift_log (target_table, user_id, field_name, stored_value, fresh_value)
        VALUES ('user_daily_stats', v_user.user_id, 'sum_total_questions', v_stored_int, v_fresh_int);
        v_drifts := v_drifts + 1;
      END IF;

      v_checked := v_checked + 1;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO stats_drift_log (target_table, user_id, field_name, notes)
      VALUES ('__exception__', v_user.user_id, 'check_failed', SQLERRM);
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- Marker de "el cron corrió"
  INSERT INTO stats_drift_log
    (target_table, user_id, field_name, stored_value, fresh_value, notes)
  VALUES
    ('__cron_run__', '00000000-0000-0000-0000-000000000000'::uuid,
     'scan_complete', v_checked, v_drifts,
     'sample_size=' || p_sample_size ||
     ' duration_ms=' || EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::int ||
     ' errors=' || v_errors ||
     ' t_cutoff=' || v_t_cutoff::text ||
     ' (backfill_active=' || (CASE WHEN v_backfill_t0 IS NOT NULL THEN 'yes' ELSE 'no' END) || ')');

  RETURN QUERY SELECT
    v_checked,
    v_drifts,
    v_errors,
    EXTRACT(MILLISECONDS FROM clock_timestamp() - v_start)::int;
END;
$$;


--
-- Name: FUNCTION check_stats_drift(p_sample_size integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_stats_drift(p_sample_size integer) IS 'Versión 2026-05-23: extendida con las 4 tablas materializadas del fix /api/stats + 2 columnas nuevas en user_stats_summary. Respeta backfill activo usando t0 del marcador.';


--
-- Name: check_user_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_user_access(user_id uuid) RETURNS TABLE(can_access boolean, user_type text, message text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    user_plan TEXT;
    user_source TEXT;
    payment_required BOOLEAN;
BEGIN
    SELECT 
        up.plan_type,
        up.registration_source,
        up.requires_payment
    INTO 
        user_plan,
        user_source,
        payment_required
    FROM user_profiles up
    WHERE up.id = user_id;
    
    -- Usuario no encontrado
    IF user_plan IS NULL THEN
        RETURN QUERY SELECT FALSE, 'not_found', 'Usuario no encontrado';
        RETURN;
    END IF;
    
    -- Usuarios legacy: siempre acceso gratis
    IF user_plan = 'legacy_free' THEN
        RETURN QUERY SELECT TRUE, 'legacy_free', 'Usuario legacy - acceso gratuito';
        RETURN;
    END IF;
    
    -- Usuarios premium activos
    IF user_plan IN ('premium', 'trial', 'premium_semester') THEN
        RETURN QUERY SELECT TRUE, 'premium', 'Usuario premium - acceso completo';
        RETURN;
    END IF;
    
    -- Usuarios orgánicos: acceso gratis
    IF user_source = 'organic' AND NOT payment_required THEN
        RETURN QUERY SELECT TRUE, 'organic_free', 'Usuario orgánico - acceso gratuito';
        RETURN;
    END IF;
    
    -- Usuarios Google Ads: requieren pago
    IF user_source = 'google_ads' OR payment_required THEN
        RETURN QUERY SELECT FALSE, 'payment_required', 'Requiere suscripción premium';
        RETURN;
    END IF;
    
    -- Default: acceso gratis
    RETURN QUERY SELECT TRUE, 'default_free', 'Acceso por defecto';
END;
$$;


--
-- Name: cleanup_expired_unsubscribe_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_unsubscribe_tokens() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM email_unsubscribe_tokens
  WHERE expires_at < NOW();
  
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


