--
-- Name: compute_convocatoria_hash(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_convocatoria_hash(p_convocatoria_id uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT md5(
    coalesce((SELECT exam_date::text FROM public.convocatorias WHERE id = p_convocatoria_id), '') || '|' ||
    coalesce((SELECT exam_date_approximate::text FROM public.convocatorias WHERE id = p_convocatoria_id), '') || '|' ||
    coalesce((SELECT plazas_libres::text FROM public.convocatorias WHERE id = p_convocatoria_id), '') || '|' ||
    coalesce((SELECT plazas_promocion_interna::text FROM public.convocatorias WHERE id = p_convocatoria_id), '') || '|' ||
    coalesce((SELECT plazas_discapacidad::text FROM public.convocatorias WHERE id = p_convocatoria_id), '') || '|' ||
    coalesce((SELECT estado_proceso FROM public.convocatorias WHERE id = p_convocatoria_id), '') || '|' ||
    coalesce((SELECT inscription_start::text FROM public.convocatorias WHERE id = p_convocatoria_id), '') || '|' ||
    coalesce((SELECT inscription_deadline::text FROM public.convocatorias WHERE id = p_convocatoria_id), '')
  );
$$;


--
-- Name: compute_global_difficulty_from_sums(integer, integer, bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_global_difficulty_from_sums(p_sample_size integer, p_correct_sum integer, p_time_sum bigint, p_confidence_sum numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_accuracy       numeric;
  v_avg_time       numeric;
  v_avg_confidence numeric;
  v_score          numeric := 0;
BEGIN
  -- Umbral mínimo: ≥1 first_attempt. Antes era ≥3, separamos la confianza
  -- estadística del sistema adaptativo (que sigue exigiendo ≥3/≥5 en sus
  -- propias funciones — ver get_effective_psychometric_difficulty y
  -- get_effective_law_question_difficulty).
  IF p_sample_size IS NULL OR p_sample_size < 1 THEN
    RETURN NULL;
  END IF;

  v_accuracy := (p_correct_sum::numeric / p_sample_size) * 100;
  v_avg_time := p_time_sum::numeric / p_sample_size;
  v_avg_confidence := p_confidence_sum / p_sample_size;

  -- Factor 1: tasa de error (0-50 pts).
  v_score := v_score + ((100 - v_accuracy) * 0.5);

  -- Factor 2: tiempo medio (0-25 pts).
  v_score := v_score +
    CASE
      WHEN v_avg_time > 120 THEN 25
      WHEN v_avg_time > 90  THEN 15
      WHEN v_avg_time > 60  THEN 8
      ELSE 0
    END;

  -- Factor 3: confianza media (0-25 pts).
  v_score := v_score +
    CASE
      WHEN v_avg_confidence < 2.0 THEN 25
      WHEN v_avg_confidence < 2.5 THEN 15
      WHEN v_avg_confidence < 3.0 THEN 8
      ELSE 0
    END;

  RETURN ROUND(GREATEST(0, LEAST(100, v_score)), 1);
END;
$$;


--
-- Name: FUNCTION compute_global_difficulty_from_sums(p_sample_size integer, p_correct_sum integer, p_time_sum bigint, p_confidence_sum numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.compute_global_difficulty_from_sums(p_sample_size integer, p_correct_sum integer, p_time_sum bigint, p_confidence_sum numeric) IS 'Versión pura (sin SELECT) del cálculo de global_difficulty. Misma fórmula que calculate_question_global_difficulty pero operando sobre los sums materializados en questions. Sub-ms.';


--
-- Name: compute_law_content_hash(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_law_content_hash(p_law_id uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT md5(
    coalesce((SELECT boe_url FROM laws WHERE id = p_law_id), '')
    || '||' ||
    coalesce((
      SELECT string_agg(a.article_number, ',' ORDER BY a.article_number)
      FROM articles a
      WHERE a.law_id = p_law_id AND coalesce(a.is_active, true)
    ), '')
  );
$$;


--
-- Name: compute_shuffle_safety_hash(text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_shuffle_safety_hash(p_explanation text, p_a text, p_b text, p_c text, p_d text, p_e text, p_mode text, p_explanation_data text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT md5(
    coalesce(p_explanation,'') || '␟' ||
    coalesce(p_a,'') || '␟' || coalesce(p_b,'') || '␟' || coalesce(p_c,'') || '␟' ||
    coalesce(p_d,'') || '␟' || coalesce(p_e,'') || '␟' || coalesce(p_mode,'') ||
    -- Solo suma al hash si hay estructura: sin esto, todas las filas existentes cambiarían de
    -- hash y el trigger las degradaría a 'stale'.
    CASE WHEN p_explanation_data IS NULL THEN '' ELSE '␟' || p_explanation_data END
  );
$$;


--
-- Name: compute_topic_scope_hash(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_topic_scope_hash(p_topic_id uuid) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT md5(
    coalesce((SELECT epigrafe FROM topics WHERE id = p_topic_id), '')
    || '||' ||
    coalesce((
      SELECT string_agg(row_repr, '|' ORDER BY row_repr)
      FROM (
        SELECT
          ts.law_id::text || ':' ||
          coalesce((
            SELECT string_agg(a, ',' ORDER BY a)
            FROM unnest(ts.article_numbers) AS a
          ), '') || ':' ||
          coalesce(ts.include_full_title::text, '') || ':' ||
          coalesce(ts.include_full_chapter::text, '') AS row_repr
        FROM topic_scope ts
        WHERE ts.topic_id = p_topic_id
      ) s
    ), '')
  );
$$;


--
-- Name: confidence_text_to_score(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confidence_text_to_score(p_text text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE p_text
    WHEN 'very_sure' THEN 4.0
    WHEN 'sure'      THEN 3.0
    WHEN 'unsure'    THEN 2.0
    WHEN 'guessing'  THEN 1.0
    ELSE 2.5  -- NULL u otros valores
  END;
$$;


--
-- Name: contains_banned_competitor(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contains_banned_competitor(p_text text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT COALESCE(p_text, '') ~* '(oposita\s*[-_./@*]?\s*test|opositest|oposistatest|tutestdigital|tu\s*test\s*digital|tutest\s*online|aula\s*[-_./@*]?\s*plus|aulaplus)';
$$;


--
-- Name: FUNCTION contains_banned_competitor(p_text text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.contains_banned_competitor(p_text text) IS 'TRUE si el texto menciona una plataforma competidora (opositatest/tutestdigital/aulaplus y variantes). Fuente única de la lista negra; usada por el gate de transition_question_state y por el canario de calidad.';


--
-- Name: convocatoria_plazas_total(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convocatoria_plazas_total(p_convocatoria_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT coalesce(c.plazas_libres, 0) + coalesce(c.plazas_promocion_interna, 0)
       -- El cupo solo suma si es un turno aparte. Si está reservado DENTRO del libre/promoción,
       -- sumarlo cuenta las mismas plazas dos veces (Madrid: 219 en vez de 212).
       + CASE WHEN c.plazas_discapacidad_incluidas IS TRUE THEN 0
              ELSE coalesce(c.plazas_discapacidad, 0) END
       + coalesce((SELECT sum((t->>'plazas')::int)
                     FROM jsonb_array_elements(coalesce(c.plazas_otros_turnos, '[]'::jsonb)) t), 0)
    FROM public.convocatorias c
   WHERE c.id = p_convocatoria_id;
$$;


--
-- Name: FUNCTION convocatoria_plazas_total(p_convocatoria_id uuid); Type: COMMENT; Schema: public; Owner: -
--

