--
-- Name: create_or_select_custom_oposicion(uuid, text, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_select_custom_oposicion(p_user_id uuid, p_nombre text, p_categoria text DEFAULT NULL::text, p_administracion text DEFAULT NULL::text, p_descripcion text DEFAULT NULL::text, p_is_public boolean DEFAULT true, p_created_by_username text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
      v_existing_id UUID;
      v_new_id UUID;
      v_current_count INTEGER;
  BEGIN
      SELECT id, times_selected INTO v_existing_id, v_current_count
      FROM custom_oposiciones
      WHERE LOWER(TRIM(nombre)) = LOWER(TRIM(p_nombre))
      AND is_public = true
      AND is_active = true
      LIMIT 1;

      IF v_existing_id IS NOT NULL THEN
          UPDATE custom_oposiciones
          SET times_selected = times_selected + 1,
              updated_at = now()
          WHERE id = v_existing_id;

          RETURN jsonb_build_object(
              'success', true,
              'action', 'selected_existing',
              'oposicion_id', v_existing_id,
              'times_selected', v_current_count + 1,
              'message', 'Oposicion seleccionada'
          );
      ELSE
          INSERT INTO custom_oposiciones (
              user_id,
              nombre,
              categoria,
              administracion,
              descripcion,
              is_public,
              created_by_username,
              times_selected
          ) VALUES (
              p_user_id,
              TRIM(p_nombre),
              p_categoria,
              p_administracion,
              p_descripcion,
              p_is_public,
              p_created_by_username,
              1
          )
          RETURNING id INTO v_new_id;

          RETURN jsonb_build_object(
              'success', true,
              'action', 'created_new',
              'oposicion_id', v_new_id,
              'times_selected', 1,
              'message', 'Oposicion creada exitosamente'
          );
      END IF;

  EXCEPTION
      WHEN unique_violation THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Ya tienes una oposicion con ese nombre'
          );
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', SQLERRM
          );
  END;
  $$;


