  $$;


--
-- Name: cron_run_end(uuid, text, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_run_end(p_run_id uuid, p_status text, p_processed integer DEFAULT NULL::integer, p_error_message text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.cron_runs
  SET ended_at = now(),
      duration_ms = EXTRACT(EPOCH FROM (now() - started_at))::int * 1000,
      status = p_status,
      processed = COALESCE(p_processed, processed),
      error_message = p_error_message,
      metadata = COALESCE(p_metadata, metadata)
  WHERE id = p_run_id;
END;
$$;


--
-- Name: cron_run_start(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cron_run_start(p_cron_name text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  INSERT INTO public.cron_runs (cron_name, metadata)
  VALUES (p_cron_name, p_metadata)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: delete_user_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_account(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_archived  jsonb;
  v_payments  jsonb;
  v_tbl       text;
BEGIN
  -- 0.bis. MARCA DE BORRADO, local a esta transacción (desaparece con ella, commit o rollback).
  --        La lee `tg_test_questions_emit_outbox` para NO fabricar una fila de outbox por cada
  --        `test_question` que se borra aquí: son eventos que el paso 4 borraría acto seguido, sin
  --        que ningún consumidor llegara a verlos (solo se lee lo commiteado). Medido el 28/07 sobre
  --        el usuario más activo: 38,4 s de los 111,7 s del borrado, tirados. [T-215]
  PERFORM set_config('app.deleting_user', p_user_id::text, true);

  -- 0. Guard: el perfil debe existir (idempotencia + sanity).
  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'user_profiles % not found', p_user_id USING ERRCODE = 'no_data_found';
  END IF;

  -- 1. ARCHIVADO LEGAL (Art. 17.3.b RGPD + Art. 30 CdC), idempotente.
  --    Solo se archiva si aún no hay archivo: así un reintento NUNCA sobrescribe
  --    el archived_data con un set vacío (los pagos ya borrados).
  SELECT archived_data INTO v_archived
  FROM public.deleted_users_log
  WHERE original_user_id = p_user_id;

  IF v_archived IS NULL OR NOT (v_archived ? 'tables') THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(ps.*)), '[]'::jsonb) INTO v_payments
    FROM public.payment_settlements ps
    WHERE ps.user_id = p_user_id;

    v_archived := jsonb_build_object(
      'archived_at', now(),
      'tables', jsonb_build_object('payment_settlements', v_payments)
    );

    UPDATE public.deleted_users_log
    SET archived_data = v_archived
    WHERE original_user_id = p_user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'deleted_users_log row for % is missing — insert it (with deletion_reason) before calling delete_user_account', p_user_id
        USING ERRCODE = 'foreign_key_violation';
    END IF;
  END IF;

  -- 2. Tablas SENSIBLES A TRIGGERS materializadores, en orden:
  --    test_questions/tests primero (disparan los UPSERT a las 5 stats), luego
  --    las stats (limpian el repueblo). Mientras user_profiles exista el guard
  --    de los triggers permite el repueblo; por eso se limpian DESPUÉS aquí, y
  --    no quedan test_questions que vuelvan a dispararlos más adelante.
  DELETE FROM public.test_questions       WHERE user_id = p_user_id;
  DELETE FROM public.tests                WHERE user_id = p_user_id;
  DELETE FROM public.user_stats_summary   WHERE user_id = p_user_id;
  DELETE FROM public.user_article_stats   WHERE user_id = p_user_id;
  DELETE FROM public.user_daily_stats     WHERE user_id = p_user_id;
  DELETE FROM public.user_difficulty_stats WHERE user_id = p_user_id;
  DELETE FROM public.user_hourly_stats    WHERE user_id = p_user_id;

  -- 3. payment_settlements: ya archivado en (1) → borrar.
  DELETE FROM public.payment_settlements  WHERE user_id = p_user_id;

  -- 4. BARRIDO DINÁMICO: toda tabla BASE de public con columna user_id que no se
  --    haya tratado ya. Cubre outbox, *_pre_outbox, observable_events, rollout
  --    logs, etc. — y cualquier tabla FUTURA — sin mantener listas a mano.
  FOR v_tbl IN
    SELECT c.table_name
    FROM information_schema.columns c
    JOIN information_schema.tables t
      ON t.table_schema = c.table_schema
     AND t.table_name   = c.table_name
     AND t.table_type   = 'BASE TABLE'
    WHERE c.table_schema = 'public'
      AND c.column_name  = 'user_id'
      AND c.table_name NOT IN (
        'test_questions','tests','user_stats_summary','user_article_stats',
        'user_daily_stats','user_difficulty_stats','user_hourly_stats',
        'payment_settlements','deleted_users_log','user_profiles'
      )
  LOOP
    EXECUTE format('DELETE FROM public.%I WHERE user_id = $1', v_tbl) USING p_user_id;
  END LOOP;

  -- 5. Tablas donde el SUJETO se referencia por otra columna (no user_id).
  DELETE FROM public.feedback_messages WHERE sender_id = p_user_id;

  -- 6. Finalmente user_profiles → CASCADE limpia las ~11 tablas hijas restantes.
  --    test_questions ya está vacío, así que la cascada no re-dispara stats.
  DELETE FROM public.user_profiles WHERE id = p_user_id;

  RETURN jsonb_build_object('ok', true, 'archived', v_archived);
END;
$_$;


--
-- Name: FUNCTION delete_user_account(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.delete_user_account(p_user_id uuid) IS 'Borrado RGPD atómico de una cuenta (schema public). Archiva pagos en deleted_users_log.archived_data de forma idempotente, borra todas las tablas public con user_id (barrido dinámico) en una transacción. NO toca auth.users (eso lo hace el endpoint via el puerto authAdmin). El caller debe haber insertado antes la fila de deleted_users_log con el deletion_reason. Ver docs/maintenance/eliminacion-cuentas.md.';


--
-- Name: derive_display_name(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_display_name(p_nickname text, p_full_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    -- 1. nickname custom (no vacío, no genérico "Usuario")
    CASE
      WHEN p_nickname IS NOT NULL
        AND length(trim(p_nickname)) > 0
        AND p_nickname <> 'Usuario'
      THEN p_nickname
      ELSE NULL
    END,
    -- 2. Primer token (nombre) de full_name, capitalizado
    CASE
      WHEN p_full_name IS NOT NULL AND length(trim(p_full_name)) > 0
      THEN initcap(split_part(trim(p_full_name), ' ', 1))
      ELSE NULL
    END,
    -- 3. Fallback final
    'Usuario'
  )
$$;


--
-- Name: detect_learning_style(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_learning_style(user_uuid uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  avg_time_correct numeric;
  avg_time_incorrect numeric;
  avg_interaction_count numeric;
  time_consistency numeric;
  result_style text := 'unknown';
  sample_size integer;
BEGIN
  -- Verificar que hay suficientes datos
  SELECT COUNT(*) INTO sample_size
  FROM test_questions tq
  JOIN tests t ON tq.test_id = t.id
  WHERE t.user_id = user_uuid;
  
  IF sample_size < 5 THEN
    RETURN 'unknown';
  END IF;
  
  -- Calcular métricas de comportamiento
  SELECT 
    AVG(time_spent_seconds) FILTER (WHERE is_correct = true),
    AVG(time_spent_seconds) FILTER (WHERE is_correct = false),
    AVG(interaction_count),
    CASE WHEN AVG(time_spent_seconds) > 0 THEN
      STDDEV(time_spent_seconds) / AVG(time_spent_seconds)
    ELSE 0 END
  INTO avg_time_correct, avg_time_incorrect, avg_interaction_count, time_consistency
  FROM test_questions tq
  JOIN tests t ON tq.test_id = t.id
  WHERE t.user_id = user_uuid;
  
  -- Lógica de detección de estilo
  IF avg_time_correct IS NOT NULL THEN
    IF avg_time_correct < 25 AND time_consistency < 0.4 THEN
      result_style := 'analytical'; -- Rápido y consistente
    ELSIF avg_interaction_count > 2.0 THEN
      result_style := 'visual'; -- Cambia mucho de opinión, necesita ver
    ELSIF avg_time_correct > 45 THEN
      result_style := 'repetitive'; -- Toma tiempo, necesita repetir
    ELSE
      result_style := 'mixed';
    END IF;
  END IF;
  
  RETURN result_style;
END;
$$;


--
-- Name: diagnose_null_question_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diagnose_null_question_ids() RETURNS TABLE(total_test_questions bigint, null_question_ids bigint, valid_question_ids bigint, null_percentage numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*) as total_test_questions,
        COUNT(*) FILTER (WHERE question_id IS NULL) as null_question_ids,
        COUNT(*) FILTER (WHERE question_id IS NOT NULL) as valid_question_ids,
        ROUND(
            (COUNT(*) FILTER (WHERE question_id IS NULL) * 100.0 / COUNT(*))::DECIMAL, 2
        ) as null_percentage
    FROM test_questions;
END;
$$;


--
-- Name: FUNCTION diagnose_null_question_ids(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.diagnose_null_question_ids() IS 'Función de diagnóstico para analizar datos con question_id NULL';


--
-- Name: diagnose_question_references(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.diagnose_question_references() RETURNS TABLE(total_test_questions bigint, null_question_ids bigint, valid_references bigint, invalid_references bigint, valid_percentage numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*) as total_test_questions,
        COUNT(*) FILTER (WHERE tq.question_id IS NULL) as null_question_ids,
        COUNT(*) FILTER (WHERE tq.question_id IS NOT NULL AND EXISTS (SELECT 1 FROM questions q WHERE q.id = tq.question_id)) as valid_references,
        COUNT(*) FILTER (WHERE tq.question_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = tq.question_id)) as invalid_references,
        ROUND(
            (COUNT(*) FILTER (WHERE tq.question_id IS NOT NULL AND EXISTS (SELECT 1 FROM questions q WHERE q.id = tq.question_id)) * 100.0 / COUNT(*))::DECIMAL, 2
        ) as valid_percentage
    FROM test_questions tq;
END;
$$;


--
-- Name: FUNCTION diagnose_question_references(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.diagnose_question_references() IS 'Diagnóstico de referencias válidas a tabla questions';


--
-- Name: ensure_convocatoria_documento(uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_convocatoria_documento(p_convocatoria_id uuid, p_doc_key text, p_canonical_url text, p_content_hash text DEFAULT NULL::text, p_tipo text DEFAULT 'convocatoria'::text, p_titulo text DEFAULT NULL::text, p_extracted_text text DEFAULT NULL::text, p_fuente text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_convocatoria_id IS NULL THEN
    RAISE EXCEPTION 'ensure_convocatoria_documento: convocatoria_id requerido';
  END IF;
  IF p_doc_key IS NULL OR btrim(p_doc_key) = '' THEN
    RAISE EXCEPTION 'ensure_convocatoria_documento: doc_key requerido (canonicaliza la URL antes con canonicalizeBoletinUrl)';
  END IF;

  -- ¿ya existe el documento CANÓNICO para esta convocatoria? (tipo<>'nota': las notas de
  -- monitoreo comparten doc_key pero NO son el documento oficial — un consumidor jamás debe
  -- enlazar a una nota; si solo hay nota, se crea el canónico).
  SELECT id INTO v_id FROM convocatoria_documentos
   WHERE convocatoria_id = p_convocatoria_id AND doc_key = p_doc_key AND tipo <> 'nota'
   LIMIT 1;

  IF v_id IS NOT NULL THEN
    -- enriquecer sin pisar: rellena hash/texto solo si faltaban
    UPDATE convocatoria_documentos
       SET content_hash   = COALESCE(content_hash, p_content_hash),
           extracted_text = COALESCE(NULLIF(extracted_text, ''), p_extracted_text),
           updated_at     = now()
     WHERE id = v_id
       AND (content_hash IS NULL OR NULLIF(extracted_text, '') IS NULL);
    RETURN v_id;
  END IF;

  -- insertar; ante carrera, el índice único reconduce al SELECT
  BEGIN
    INSERT INTO convocatoria_documentos
      (convocatoria_id, doc_key, url, tipo, titulo, content_hash, extracted_text, fuente, fetched_at, created_at, updated_at)
    VALUES
      (p_convocatoria_id, p_doc_key, p_canonical_url, COALESCE(p_tipo, 'convocatoria'),
       p_titulo, p_content_hash, p_extracted_text, COALESCE(p_fuente, 'manual'), now(), now(), now())
    RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_id FROM convocatoria_documentos
     WHERE convocatoria_id = p_convocatoria_id AND doc_key = p_doc_key AND tipo <> 'nota'
     LIMIT 1;
  END;

  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION ensure_convocatoria_documento(p_convocatoria_id uuid, p_doc_key text, p_canonical_url text, p_content_hash text, p_tipo text, p_titulo text, p_extracted_text text, p_fuente text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_convocatoria_documento(p_convocatoria_id uuid, p_doc_key text, p_canonical_url text, p_content_hash text, p_tipo text, p_titulo text, p_extracted_text text, p_fuente text) IS 'Único camino de escritura del hub de provenance. Idempotente por (convocatoria_id, doc_key). Devuelve el id del documento (existente o nuevo). Ver docs/maintenance/provenance-convocatorias.md.';


--
-- Name: ensure_single_current_convocatoria(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_single_current_convocatoria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.is_current = true THEN
    UPDATE public.convocatorias
    SET is_current = false,
        updated_at = NOW()
    WHERE oposicion_id = NEW.oposicion_id
      AND id != NEW.id
      AND is_current = true;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fn_topic_scope_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_topic_scope_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_actor  text := nullif(current_setting('app.actor', true), '');
  v_reason text := nullif(current_setting('app.change_reason', true), '');
BEGIN
  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.topic_scope_history
      (topic_id, law_id, operation, articles_before, articles_after, changed_by, change_reason)
    VALUES (OLD.topic_id, OLD.law_id, 'DELETE', OLD.article_numbers, NULL, v_actor, v_reason);
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Solo se audita si CAMBIA el temario servido. Un UPDATE que toca `weight` u otra
    -- columna no ensucia el historial: si todo cambio quedara registrado, el ruido haría
    -- inservible la tabla justo cuando hace falta buscar el cambio que rompió algo.
    IF OLD.article_numbers IS NOT DISTINCT FROM NEW.article_numbers THEN
      RETURN NEW;
    END IF;
    INSERT INTO public.topic_scope_history
      (topic_id, law_id, operation, articles_before, articles_after, changed_by, change_reason)
    VALUES (NEW.topic_id, NEW.law_id, 'UPDATE', OLD.article_numbers, NEW.article_numbers, v_actor, v_reason);
    RETURN NEW;
  END IF;

  INSERT INTO public.topic_scope_history
    (topic_id, law_id, operation, articles_before, articles_after, changed_by, change_reason)
  VALUES (NEW.topic_id, NEW.law_id, 'INSERT', NULL, NEW.article_numbers, v_actor, v_reason);
  RETURN NEW;
END;
$$;


--
-- Name: generate_content_hash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_content_hash(content_text text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Verificar que el contenido no sea NULL o vacío
    IF content_text IS NULL OR content_text = '' THEN
        RETURN NULL;
    END IF;
    
    -- Generar hash SHA256 del contenido
    RETURN encode(digest(content_text, 'sha256'), 'hex');
END;
$$;


--
-- Name: generate_test_by_topic(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_test_by_topic(p_topic_id uuid, p_total_questions integer DEFAULT 25, p_difficulty_filter text DEFAULT NULL::text) RETURNS TABLE(question_id uuid, question_text text, option_a text, option_b text, option_c text, option_d text, correct_option integer, primary_article text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    WITH topic_articles AS (
        -- Artículos del tema
        SELECT DISTINCT a.id as article_id, a.article_number, a.title
        FROM public.articles a
        JOIN public.topic_scope ts ON ts.law_id = a.law_id
        WHERE ts.topic_id = p_topic_id
        AND a.is_active = true
        AND (
            (ts.article_numbers IS NOT NULL AND a.article_number = ANY(ts.article_numbers))
            OR
            (ts.include_full_title = true AND ts.title_numbers IS NOT NULL AND a.title_number = ANY(ts.title_numbers))
        )
    ),
    available_questions AS (
        -- Preguntas disponibles del tema
        SELECT 
            q.id,
            q.question_text,
            q.option_a,
            q.option_b,
            q.option_c,
            q.option_d,
            q.correct_option,
            CONCAT('Art. ', ta.article_number, ' - ', ta.title) as article_ref
        FROM public.questions q
        JOIN topic_articles ta ON q.primary_article_id = ta.article_id
        WHERE q.is_active = true
        AND (p_difficulty_filter IS NULL OR q.difficulty = p_difficulty_filter)
    )
    SELECT 
        aq.id,
        aq.question_text,
        aq.option_a,
        aq.option_b,
        aq.option_c,
        aq.option_d,
        aq.correct_option,
        aq.article_ref
    FROM available_questions aq
    ORDER BY RANDOM()
    LIMIT p_total_questions;
END;
$$;


--
-- Name: generate_unsubscribe_token(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_unsubscribe_token(user_uuid uuid, user_email text, email_type_param text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  new_token text;
BEGIN
  -- Generar token único
  new_token := encode(gen_random_bytes(32), 'hex');
  
  -- Insertar en tabla de tokens
  INSERT INTO email_unsubscribe_tokens (
    user_id,
    token,
    email,
    email_type,
    expires_at
  ) VALUES (
    user_uuid,
    new_token,
    user_email,
    email_type_param,
    NOW() + INTERVAL '30 days'
  );
  
  RETURN new_token;
END;
$$;


--
-- Name: FUNCTION generate_unsubscribe_token(user_uuid uuid, user_email text, email_type_param text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_unsubscribe_token(user_uuid uuid, user_email text, email_type_param text) IS 'Genera token único para unsubscribe sin login';


--
-- Name: get_accounts_on_device(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_accounts_on_device(p_device_id text) RETURNS TABLE(user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$           
    SELECT ud.user_id
    FROM user_devices ud
    WHERE ud.device_id = p_device_id
      AND ud.last_seen_at > NOW() - INTERVAL '30 days';
  $$;


--
-- Name: get_active_users_with_automatic_avatar(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_users_with_automatic_avatar(p_days_back integer DEFAULT 7) RETURNS TABLE(user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT DISTINCT uas.user_id
  FROM user_avatar_settings uas
  WHERE uas.mode = 'automatic'
    AND EXISTS (
      SELECT 1
      FROM tests t
      INNER JOIN test_questions tq ON tq.test_id = t.id
      WHERE t.user_id = uas.user_id
        AND tq.created_at >= NOW() - (p_days_back || ' days')::INTERVAL
    );
$$;


--
-- Name: get_admin_dashboard_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_admin_dashboard_stats() RETURNS TABLE(total_users bigint, users_with_tests bigint, engagement_percentage numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  BEGIN
    RETURN QUERY
    WITH user_stats AS (
      -- Total de usuarios registrados
      SELECT COUNT(DISTINCT id) as total_users
      FROM user_profiles
    ),
    users_with_tests_stats AS (
      -- Usuarios que han completado al menos un test
      SELECT COUNT(DISTINCT user_id) as users_with_tests
      FROM tests
      WHERE is_completed = true
    )
    SELECT
      us.total_users,
      uwt.users_with_tests,
      -- Calcular porcentaje de engagement (usuarios con tests / total usuarios)
      CASE
        WHEN us.total_users > 0 THEN
          ROUND((uwt.users_with_tests::NUMERIC / us.total_users::NUMERIC) * 100,
  1)
        ELSE 0
      END as engagement_percentage
    FROM user_stats us
    CROSS JOIN users_with_tests_stats uwt;
  END;
  $$;


--
-- Name: FUNCTION get_admin_dashboard_stats(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_admin_dashboard_stats() IS 'Devuelve estadísticas 
  generales para el admin dashboard: total usuarios, usuarios con tests y 
  porcentaje de engagement';


--
-- Name: get_all_users_with_subscriptions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_users_with_subscriptions() RETURNS TABLE(id uuid, email text, created_at timestamp with time zone, plan_type text, full_name text, unsubscribed_all boolean, unsubscribe_date timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT
      u.id,
      u.email,
      u.created_at,
      u.plan_type,
      u.full_name,
      COALESCE(e.unsubscribed_all, false) as unsubscribed_all,
      e.updated_at as unsubscribe_date
    FROM user_profiles u
    LEFT JOIN email_preferences e ON u.id = e.user_id
    ORDER BY u.created_at DESC;
  $$;


--
-- Name: get_article_context_clean(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_article_context_clean(p_article_number text, p_oposicion_name text DEFAULT NULL::text) RETURNS TABLE(article_number text, oposicion_name text, classification text, total_appearances integer, years_appeared integer[], user_message text)
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT 
        a.article_number,
        o.nombre,
        aes.classification,
        aes.total_appearances,
        aes.years_appeared,
        aes.user_message
    FROM articles a
    JOIN article_exam_stats aes ON a.id = aes.article_id
    JOIN oposiciones o ON aes.oposicion_id = o.id
    WHERE a.article_number = p_article_number
    AND (p_oposicion_name IS NULL OR o.nombre ILIKE '%' || p_oposicion_name || '%')
    ORDER BY aes.total_appearances DESC;
$$;


--
-- Name: get_article_context_final(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_article_context_final(p_article_number text, p_oposicion_name text DEFAULT NULL::text) RETURNS TABLE(article_number text, oposicion_name text, classification text, total_appearances integer, years_appeared integer[], user_message text)
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT DISTINCT ON (a.article_number, o.nombre)
        a.article_number,
        o.nombre,
        aes.classification,
        aes.total_appearances,
        aes.years_appeared,
        aes.user_message
    FROM articles a
    JOIN article_exam_stats aes ON a.id = aes.article_id
    JOIN oposiciones o ON aes.oposicion_id = o.id
    WHERE a.article_number = p_article_number
    AND (p_oposicion_name IS NULL OR o.nombre ILIKE '%' || p_oposicion_name || '%')
    ORDER BY a.article_number, o.nombre, aes.total_appearances DESC;
$$;


--
-- Name: get_article_exam_history(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_article_exam_history(p_article_id uuid, p_oposicion_id uuid) RETURNS TABLE("año" integer, tipo_acceso text, frecuencia integer, tipo_pregunta text, observaciones text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.año,
        o.tipo_acceso,
        ae.frecuencia_aparicion,
        ae.tipo_pregunta,
        ae.observaciones
    FROM public.articulos_examenes ae
    JOIN public.convocatorias c ON ae.convocatoria_id = c.id
    JOIN public.oposiciones o ON c.oposicion_id = o.id
    WHERE ae.article_id = p_article_id
    AND o.id = p_oposicion_id
    ORDER BY c.año DESC;
END;
$$;


--
-- Name: get_article_exam_stats(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_article_exam_stats(p_article_id uuid, p_oposicion_id uuid DEFAULT NULL::uuid) RETURNS TABLE(total_apariciones bigint, "años_aparicion" integer[], ultima_aparicion integer, frecuencia_promedio numeric, nivel_importancia text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    total_count BIGINT;
    years_array INTEGER[];
    last_year INTEGER;
    avg_freq DECIMAL;
    importance_level TEXT;
BEGIN
    -- Calcular estadísticas
    SELECT 
        COUNT(*),
        ARRAY_AGG(DISTINCT c.año ORDER BY c.año DESC),
        MAX(c.año),
        AVG(ae.frecuencia_aparicion)
    INTO total_count, years_array, last_year, avg_freq
    FROM public.articulos_examenes ae
    JOIN public.convocatorias c ON ae.convocatoria_id = c.id
    JOIN public.oposiciones o ON c.oposicion_id = o.id
    WHERE ae.article_id = p_article_id
    AND (p_oposicion_id IS NULL OR o.id = p_oposicion_id);
    
    -- Determinar nivel de importancia
    IF total_count >= 5 THEN
        importance_level := 'MUY PREGUNTADO';
    ELSIF total_count >= 3 THEN
        importance_level := 'FRECUENTE';
    ELSIF total_count >= 1 THEN
        importance_level := 'OCASIONAL';
    ELSE
        importance_level := 'NO REGISTRADO';
    END IF;
    
    RETURN QUERY SELECT total_count, years_array, last_year, avg_freq, importance_level;
END;
$$;


--
-- Name: get_article_questions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_article_questions(p_article_id uuid) RETURNS TABLE(question_id uuid, question_text text, difficulty text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        q.id,
        q.question_text,
        q.difficulty
    FROM public.questions q
    WHERE q.primary_article_id = p_article_id
    AND q.is_active = true
    ORDER BY q.difficulty, q.created_at;
END;
$$;


--
-- Name: get_complete_test_analytics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_complete_test_analytics(test_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  test_info tests%ROWTYPE;
  result_json jsonb;
BEGIN
  -- Obtener información básica del test
  SELECT * INTO test_info FROM tests WHERE id = test_session_id;
  
  IF test_info.id IS NULL THEN
    RETURN '{"error": "Test not found"}'::jsonb;
  END IF;
  
  -- Construir resultado JSON completo
  SELECT jsonb_build_object(
    'test_summary', jsonb_build_object(
      'test_id', test_info.id,
      'title', test_info.title,
      'user_id', test_info.user_id,
      'total_questions', test_info.total_questions,
      'score', test_info.score,
      'accuracy_percentage', ROUND((test_info.score::numeric / test_info.total_questions) * 100, 2),
      'total_time_seconds', test_info.total_time_seconds,
      'average_time_per_question', test_info.average_time_per_question,
      'completion_date', test_info.completed_at,
      'tema_number', test_info.tema_number,
      'test_number', test_info.test_number
    ),
    
    'question_breakdown', (
      SELECT jsonb_object_agg(
        difficulty,
        jsonb_build_object(
          'total', count(*),
          'correct', count(*) FILTER (WHERE is_correct = true),
          'accuracy', ROUND((count(*) FILTER (WHERE is_correct = true) * 100.0 / count(*)), 1),
          'avg_time', ROUND(AVG(time_spent_seconds), 1)
        )
      )
      FROM test_questions 
      WHERE test_id = test_session_id AND difficulty IS NOT NULL
      GROUP BY difficulty
    ),
    
    'article_performance', (
      SELECT jsonb_object_agg(
        COALESCE(article_number, 'Sin artículo'),
        jsonb_build_object(
          'total', count(*),
          'correct', count(*) FILTER (WHERE is_correct = true),
          'accuracy', ROUND((count(*) FILTER (WHERE is_correct = true) * 100.0 / count(*)), 1),
          'avg_time', ROUND(AVG(time_spent_seconds), 1),
          'law', law_name,
          'avg_retention_score', ROUND(AVG(knowledge_retention_score), 1)
        )
      )
      FROM test_questions 
      WHERE test_id = test_session_id
      GROUP BY article_number, law_name
    ),
    
    'learning_insights', jsonb_build_object(
      'confidence_analysis', (
        SELECT jsonb_object_agg(
          confidence_level,
          jsonb_build_object(
            'total', count(*),
            'correct', count(*) FILTER (WHERE is_correct = true),
            'accuracy', ROUND((count(*) FILTER (WHERE is_correct = true) * 100.0 / count(*)), 1)
          )
        )
        FROM test_questions 
        WHERE test_id = test_session_id AND confidence_level IS NOT NULL
        GROUP BY confidence_level
      ),
      'interaction_patterns', (
        SELECT jsonb_build_object(
          'decisive_answers', count(*) FILTER (WHERE interaction_count = 1),
          'hesitant_answers', count(*) FILTER (WHERE interaction_count > 2),
          'avg_interactions', ROUND(AVG(interaction_count), 2)
        )
        FROM test_questions 
        WHERE test_id = test_session_id
      )
    )
    
  ) INTO result_json;
  
  RETURN result_json;
  
END;
$$;


--
-- Name: get_daily_question_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_daily_question_status(p_user_id uuid) RETURNS TABLE(questions_today integer, questions_remaining integer, daily_limit integer, is_limit_reached boolean, is_premium boolean, reset_time timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_plan_type TEXT;
    v_today DATE;
    v_current_count INTEGER;
    v_is_premium BOOLEAN;
    v_limit INTEGER := 25;
  BEGIN
    v_today := (NOW() AT TIME ZONE 'Europe/Madrid')::DATE;

    SELECT up.plan_type INTO v_plan_type
    FROM user_profiles up
    WHERE up.id = p_user_id;

    v_is_premium := COALESCE(v_plan_type, 'free') IN ('premium', 'trial', 'legacy_free', 'premium_semester', 'admin');

    IF v_is_premium THEN
      RETURN QUERY SELECT
        0::INTEGER,
        999::INTEGER,
        v_limit,
        FALSE::BOOLEAN,
        TRUE::BOOLEAN,
        ((v_today + INTERVAL '1 day')::TIMESTAMP AT TIME ZONE 'Europe/Madrid');
      RETURN;
    END IF;

    SELECT COALESCE(dqu.questions_answered, 0) INTO v_current_count
    FROM daily_question_usage dqu
    WHERE dqu.user_id = p_user_id AND dqu.usage_date = v_today;

    IF v_current_count IS NULL THEN
      v_current_count := 0;
    END IF;

    RETURN QUERY SELECT
      v_current_count,
      GREATEST(0, v_limit - v_current_count),
      v_limit,
      v_current_count >= v_limit,
      FALSE::BOOLEAN,
      ((v_today + INTERVAL '1 day')::TIMESTAMP AT TIME ZONE 'Europe/Madrid');
  END;
  $$;


--
-- Name: get_dashboard_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_stats() RETURNS TABLE(total_users bigint, users_with_tests bigint, engagement_percentage integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    RETURN QUERY
    WITH user_counts AS (
      -- Total de usuarios
      SELECT COUNT(DISTINCT user_id) as total
      FROM admin_users_with_roles
    ),
    test_users AS (
      -- Usuarios únicos que han completado al menos un test
      SELECT COUNT(DISTINCT t.user_id) as with_tests
      FROM tests t
      WHERE t.is_completed = true
        AND EXISTS (
          SELECT 1
          FROM admin_users_with_roles u
          WHERE u.user_id = t.user_id
        )
    )
    SELECT
      uc.total as total_users,
      tu.with_tests as users_with_tests,
      CASE
        WHEN uc.total > 0 THEN
          ROUND((tu.with_tests::NUMERIC / uc.total::NUMERIC) * 100)::INTEGER
        ELSE 0
      END as engagement_percentage
    FROM user_counts uc, test_users tu;
  END;
  $$;


--
-- Name: get_device_daily_usage(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_device_daily_usage(p_device_id text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$                                                                                            
  DECLARE         
    v_total INTEGER;
    v_today DATE;
  BEGIN
    v_today := (NOW() AT TIME ZONE 'Europe/Madrid')::DATE;                                         
                                                                                                   
    SELECT COALESCE(SUM(dqu.questions_answered), 0) INTO v_total                                   
    FROM daily_question_usage dqu                                                                  
    INNER JOIN user_devices ud ON ud.user_id = dqu.user_id                                         
    INNER JOIN user_profiles up ON up.id = dqu.user_id
    WHERE ud.device_id = p_device_id                                                               
      AND ud.last_seen_at > NOW() - INTERVAL '30 days'
      AND dqu.usage_date = v_today                                                                 
      AND COALESCE(up.plan_type, 'free') NOT IN ('premium', 'trial', 'legacy_free',
  'premium_semester', 'admin');                                                                    
                  
    RETURN v_total;                                                                                
  END;            
  $$;


--
-- Name: get_device_daily_usage_v2(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_device_daily_usage_v2(p_device_id text, p_fingerprint text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_total INTEGER;
    v_today DATE;
    v_fp    text;
  BEGIN
    v_today := (NOW() AT TIME ZONE 'Europe/Madrid')::DATE;

    -- Solo se agrupa por huella si es v2. Ver la nota de arriba sobre las colisiones de `hw_`.
    v_fp := CASE WHEN p_fingerprint LIKE 'fp2\_%' THEN p_fingerprint ELSE NULL END;

    -- Sin ninguna señal utilizable no se opina: 0 deja pasar (fail-open), que es el
    -- comportamiento correcto cuando no se sabe de quién es el dispositivo.
    IF p_device_id IS NULL AND v_fp IS NULL THEN
      RETURN 0;
    END IF;

    SELECT COALESCE(SUM(dqu.questions_answered), 0) INTO v_total
    FROM daily_question_usage dqu
    INNER JOIN user_profiles up ON up.id = dqu.user_id
    WHERE dqu.usage_date = v_today
      AND COALESCE(up.plan_type, 'free') NOT IN
          ('premium', 'trial', 'legacy_free', 'premium_semester', 'admin')
      AND EXISTS (
        SELECT 1 FROM user_devices ud
         WHERE ud.user_id = dqu.user_id
           AND ud.last_seen_at > NOW() - INTERVAL '30 days'
           AND (
             (p_device_id IS NOT NULL AND ud.device_id = p_device_id)
             OR
             (v_fp IS NOT NULL AND ud.hw_fingerprint = v_fp)
           )
      );

    RETURN v_total;
  END;
$$;


--
-- Name: FUNCTION get_device_daily_usage_v2(p_device_id text, p_fingerprint text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_device_daily_usage_v2(p_device_id text, p_fingerprint text) IS 'Consumo diario agregado del dispositivo, anclado a la huella de hardware v2 (fp2_) además del device_id. Ignora las huellas v1 (hw_) a propósito: colisionan hasta 83 cuentas. T-304.';


--
-- Name: get_device_daily_usage_v3(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_device_daily_usage_v3(p_device_id text, p_fingerprint text DEFAULT NULL::text, p_ip text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_total INTEGER;
    v_today DATE;
    v_fp    text;
    v_ip    inet;
  BEGIN
    v_today := (NOW() AT TIME ZONE 'Europe/Madrid')::DATE;

    -- Igual que en la v2: las huellas v1 (`hw_`) no se usan, colisionan hasta 83 cuentas.
    v_fp := CASE WHEN p_fingerprint LIKE 'fp2\_%' THEN p_fingerprint ELSE NULL END;

    -- `user_sessions.ip_address` es `inet`. La cabecera llega como texto y puede traer cualquier
    -- cosa, así que una IP que no parsea NO corrobora (y no revienta la consulta): sin IP válida
    -- la huella no agrupa, que es el lado seguro de equivocarse.
    BEGIN
      v_ip := p_ip::inet;
    EXCEPTION WHEN others THEN
      v_ip := NULL;
    END;

    -- Sin ninguna señal utilizable no se opina: fail-open.
    IF p_device_id IS NULL AND v_fp IS NULL THEN
      RETURN 0;
    END IF;

    SELECT COALESCE(SUM(dqu.questions_answered), 0) INTO v_total
    FROM daily_question_usage dqu
    INNER JOIN user_profiles up ON up.id = dqu.user_id
    WHERE dqu.usage_date = v_today
      AND COALESCE(up.plan_type, 'free') NOT IN
          ('premium', 'trial', 'legacy_free', 'premium_semester', 'admin')
      AND EXISTS (
        SELECT 1 FROM user_devices ud
         WHERE ud.user_id = dqu.user_id
           AND ud.last_seen_at > NOW() - INTERVAL '30 days'
           AND (
             -- (a) MISMO navegador: prueba directa, no necesita corroboración.
             (p_device_id IS NOT NULL AND ud.device_id = p_device_id)
             OR
             -- (b) Misma huella Y corroborada por IP compartida. Sin IP válida la huella NO agrupa
             --     por sí sola: es el punto entero de este cambio.
             (v_fp IS NOT NULL AND v_ip IS NOT NULL AND ud.hw_fingerprint = v_fp
              AND EXISTS (
                SELECT 1 FROM user_sessions s
                 WHERE s.user_id = ud.user_id
                   AND s.ip_address = v_ip
                   AND s.created_at > NOW() - INTERVAL '30 days'
              ))
           )
      );

    RETURN v_total;
  END;
$$;


--
-- Name: FUNCTION get_device_daily_usage_v3(p_device_id text, p_fingerprint text, p_ip text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_device_daily_usage_v3(p_device_id text, p_fingerprint text, p_ip text) IS 'Consumo diario agregado del dispositivo. La huella v2 solo agrupa cuentas si la corrobora una IP compartida: por sí sola identifica el MODELO de móvil, no el aparato (125 huellas / 369 cuentas colisionadas medidas el 07/08/2026). T-657.';


--
-- Name: get_disputes_with_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_disputes_with_users() RETURNS TABLE(id uuid, question_id uuid, user_id uuid, dispute_type text, description text, status text, admin_response text, admin_user_id uuid, created_at timestamp with time zone, resolved_at timestamp with time zone, updated_at timestamp with time zone, is_read boolean, appeal_text text, appeal_submitted_at timestamp with time zone, user_profiles jsonb, questions jsonb)
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
      SELECT
          qd.id,
          qd.question_id,
          qd.user_id,
          qd.dispute_type,
          qd.description,
          qd.status,
          qd.admin_response,
          qd.admin_user_id,
          qd.created_at,
          qd.resolved_at,
          qd.updated_at,
          qd.is_read,
          qd.appeal_text,
          qd.appeal_submitted_at,
          jsonb_build_object(
              'email', up.email,
              'full_name', up.full_name
          ) as user_profiles,
          jsonb_build_object(
              'question_text', q.question_text,
              'option_a', q.option_a,
              'option_b', q.option_b,
              'option_c', q.option_c,
              'option_d', q.option_d,
              'correct_option', q.correct_option,
              'explanation', q.explanation
          ) as questions
      FROM question_disputes qd
      LEFT JOIN user_profiles up ON qd.user_id = up.id
      LEFT JOIN questions q ON qd.question_id = q.id
      ORDER BY qd.created_at DESC;
  $$;


