--
-- Name: get_effective_law_question_difficulty(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_law_question_difficulty(user_uuid uuid, question_uuid uuid) RETURNS TABLE(difficulty_value numeric, difficulty_source text, sample_size integer, confidence numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    personal_diff NUMERIC;
    global_diff NUMERIC;
    sample_size_val INTEGER;
    confidence_val NUMERIC;
  BEGIN
    -- Intentar obtener dificultad personal primero
    personal_diff := calculate_personal_law_question_difficulty(user_uuid, question_uuid);

    -- Obtener dificultad global y metadatos
    SELECT
      global_difficulty,
      difficulty_sample_size,
      difficulty_confidence
    INTO global_diff, sample_size_val, confidence_val
    FROM questions
    WHERE id = question_uuid;

    -- Prioridad: personal > global > base (2.5)
    IF personal_diff IS NOT NULL THEN
      RETURN QUERY SELECT personal_diff, 'personal'::TEXT,
                          COALESCE(sample_size_val, 0),
                          COALESCE(confidence_val, 0.5);
    ELSIF global_diff IS NOT NULL THEN
      RETURN QUERY SELECT global_diff, 'global'::TEXT,
                          COALESCE(sample_size_val, 0),
                          COALESCE(confidence_val, 0.5);
    ELSE
      RETURN QUERY SELECT 2.5::NUMERIC, 'default'::TEXT, 0, 0.0::NUMERIC;
    END IF;
  END;
  $$;


--
-- Name: get_effective_psychometric_difficulty(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_psychometric_difficulty(p_question_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(base_difficulty text, global_difficulty numeric, personal_difficulty numeric, sample_size integer, effective_difficulty numeric, recommendation text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
      v_base_difficulty text;
      v_global_difficulty numeric;
      v_personal_difficulty numeric;
      v_sample_size integer := 0;
      v_effective_difficulty numeric;
      v_recommendation text;
      v_base_numeric numeric;
  BEGIN
      SELECT pq.difficulty
      INTO v_base_difficulty
      FROM psychometric_questions pq
      WHERE pq.id = p_question_id;

      IF v_base_difficulty IS NULL THEN
          v_base_difficulty := 'medium';
      END IF;

      CASE v_base_difficulty
          WHEN 'easy' THEN v_base_numeric := 25.0;
          WHEN 'medium' THEN v_base_numeric := 50.0;
          WHEN 'hard' THEN v_base_numeric := 75.0;
          ELSE v_base_numeric := 50.0;
      END CASE;

      SELECT
          pq.global_difficulty,
          COALESCE(pq.difficulty_sample_size, 0)
      INTO v_global_difficulty, v_sample_size
      FROM psychometric_questions pq
      WHERE pq.id = p_question_id;

      IF p_user_id IS NOT NULL THEN
          SELECT
              CASE
                  WHEN COUNT(*) >= 3 THEN
                      GREATEST(10.0, LEAST(90.0,
                          v_base_numeric +
                          (AVG(CASE WHEN is_correct THEN -10 ELSE 15 END))
                      ))
                  ELSE NULL
              END
          INTO v_personal_difficulty
          FROM psychometric_test_answers pta
          WHERE pta.question_id = p_question_id
          AND pta.user_id = p_user_id;
      END IF;

      IF v_personal_difficulty IS NOT NULL THEN
          v_effective_difficulty := v_personal_difficulty;
          v_recommendation :=
              CASE
                  WHEN v_personal_difficulty < v_base_numeric - 15 THEN
  'decrease_difficulty'
                  WHEN v_personal_difficulty > v_base_numeric + 15 THEN
  'increase_difficulty'
                  ELSE 'optimal'
              END;
      ELSIF v_global_difficulty IS NOT NULL AND v_sample_size >= 5 THEN
          v_effective_difficulty := v_global_difficulty;
          v_recommendation :=
              CASE
                  WHEN v_global_difficulty < v_base_numeric - 15 THEN
  'decrease_difficulty'
                  WHEN v_global_difficulty > v_base_numeric + 15 THEN
  'increase_difficulty'
                  ELSE 'optimal'
              END;
      ELSE
          v_effective_difficulty := v_base_numeric;
          v_recommendation :=
              CASE
                  WHEN v_sample_size < 5 THEN 'need_more_data'
                  ELSE 'fallback'
              END;
      END IF;

      RETURN QUERY SELECT
          v_base_difficulty,
          v_global_difficulty,
          v_personal_difficulty,
          v_sample_size,
          v_effective_difficulty,
          v_recommendation;
  END;
  $$;


--
-- Name: get_engagement_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_engagement_metrics() RETURNS TABLE(total_users bigint, mau bigint, dau numeric, last_7_days_tests bigint, last_30_days_tests bigint, total_tests bigint, activation_rate integer, dau_mau_ratio integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_total_users BIGINT;
    v_mau BIGINT;
    v_dau NUMERIC;
    v_last_7_days_tests BIGINT;
    v_last_30_days_tests BIGINT;
    v_total_tests BIGINT;
  BEGIN
    -- Total de usuarios registrados
    SELECT COUNT(*)::BIGINT INTO v_total_users
    FROM user_profiles;

    -- Total de tests completados
    SELECT COUNT(*)::BIGINT INTO v_total_tests
    FROM tests
    WHERE is_completed = true
      AND completed_at IS NOT NULL;

    -- Tests en los últimos 7 días
    SELECT COUNT(*)::BIGINT INTO v_last_7_days_tests
    FROM tests
    WHERE is_completed = true
      AND completed_at IS NOT NULL
      AND completed_at >= NOW() - INTERVAL '7 days';

    -- Tests en los últimos 30 días
    SELECT COUNT(*)::BIGINT INTO v_last_30_days_tests
    FROM tests
    WHERE is_completed = true
      AND completed_at IS NOT NULL
      AND completed_at >= NOW() - INTERVAL '30 days';

    -- MAU: Usuarios activos únicos en los últimos 30 días
    SELECT COUNT(DISTINCT user_id)::BIGINT INTO v_mau
    FROM tests
    WHERE is_completed = true
      AND completed_at IS NOT NULL
      AND completed_at >= NOW() - INTERVAL '30 days';

    -- DAU promedio: Promedio de usuarios activos diarios en los últimos 7 días
    WITH daily_active AS (
      SELECT
        DATE(completed_at) as day,
        COUNT(DISTINCT user_id) as daily_users
      FROM tests
      WHERE is_completed = true
        AND completed_at IS NOT NULL
        AND completed_at >= NOW() - INTERVAL '7 days'
      GROUP BY DATE(completed_at)
    )
    SELECT COALESCE(AVG(daily_users), 0) INTO v_dau
    FROM daily_active;

    -- Retornar resultados
    RETURN QUERY
    SELECT
      v_total_users as total_users,
      v_mau as mau,
      ROUND(v_dau) as dau,
      v_last_7_days_tests as last_7_days_tests,
      v_last_30_days_tests as last_30_days_tests,
      v_total_tests as total_tests,
      CASE
        WHEN v_total_users > 0 THEN
          ROUND((v_mau::NUMERIC / v_total_users::NUMERIC) * 100)::INTEGER
        ELSE 0
      END as activation_rate,
      CASE
        WHEN v_mau > 0 THEN
          ROUND((v_dau / v_mau::NUMERIC) * 100)::INTEGER
        ELSE 0
      END as dau_mau_ratio;
  END;
  $$;


--
-- Name: get_estadisticas_examenes_oficiales(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_estadisticas_examenes_oficiales(p_oposicion_id uuid) RETURNS TABLE("año" integer, total_preguntas_registradas integer, preguntas_organizacion_publica integer, preguntas_ofimatica integer, preguntas_psicotecnico integer, preguntas_anuladas integer, articulos_diferentes integer, leyes_diferentes integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.año,
        COUNT(peo.id)::integer as total_preguntas_registradas,
        COUNT(CASE WHEN peo.parte_examen = 'organizacion_publica' THEN 1 END)::integer as preguntas_organizacion_publica,
        COUNT(CASE WHEN peo.parte_examen = 'ofimatica' THEN 1 END)::integer as preguntas_ofimatica,
        COUNT(CASE WHEN peo.parte_examen = 'psicotecnico' THEN 1 END)::integer as preguntas_psicotecnico,
        COUNT(CASE WHEN peo.fue_anulada = true THEN 1 END)::integer as preguntas_anuladas,
        COUNT(DISTINCT a.id)::integer as articulos_diferentes,
        COUNT(DISTINCT l.id)::integer as leyes_diferentes
    FROM public.convocatorias c
    LEFT JOIN public.preguntas_examenes_oficiales peo ON c.id = peo.convocatoria_id
    LEFT JOIN public.articles a ON peo.article_id = a.id
    LEFT JOIN public.laws l ON a.law_id = l.id
    WHERE c.oposicion_id = p_oposicion_id
    GROUP BY c.año
    ORDER BY c.año DESC;
END;
$$;


