--
-- Name: get_examen_oficial_exacto(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_examen_oficial_exacto(p_convocatoria_id uuid, p_parte_examen text DEFAULT 'all'::text) RETURNS TABLE(numero_pregunta integer, parte_examen text, pregunta_text text, opcion_a text, opcion_b text, opcion_c text, opcion_d text, respuesta_correcta text, article_number text, law_name text, topic_estimado text, explicacion text, fue_anulada boolean, observaciones text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        peo.numero_pregunta,
        peo.parte_examen,
        peo.pregunta_text,
        peo.opcion_a,
        peo.opcion_b,
        peo.opcion_c,
        peo.opcion_d,
        peo.respuesta_correcta,
        a.article_number,
        l.short_name as law_name,
        peo.topic_estimado,
        peo.explicacion,
        peo.fue_anulada,
        peo.observaciones
    FROM public.preguntas_examenes_oficiales peo
    LEFT JOIN public.articles a ON peo.article_id = a.id
    LEFT JOIN public.laws l ON a.law_id = l.id
    WHERE peo.convocatoria_id = p_convocatoria_id
    AND (p_parte_examen = 'all' OR peo.parte_examen = p_parte_examen)
    AND peo.fue_anulada = false
    ORDER BY 
        CASE peo.parte_examen 
            WHEN 'organizacion_publica' THEN 1
            WHEN 'psicotecnico' THEN 2  
            WHEN 'ofimatica' THEN 3
        END,
        peo.numero_pregunta NULLS LAST;
END;
$$;


--
-- Name: get_inactive_users_for_emails(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_inactive_users_for_emails() RETURNS TABLE(user_id uuid, email text, full_name text, days_inactive integer, last_activity_date timestamp with time zone, total_tests_completed integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    up.id as user_id,
    up.email,
    up.full_name,
    EXTRACT(days FROM (NOW() - COALESCE(
      (SELECT MAX(t.completed_at) FROM tests t WHERE t.user_id = up.id AND t.is_completed = true),
      up.created_at
    )))::integer as days_inactive,
    COALESCE(
      (SELECT MAX(t.completed_at) FROM tests t WHERE t.user_id = up.id AND t.is_completed = true),
      up.created_at
    ) as last_activity_date,
    (SELECT COUNT(*) FROM tests t WHERE t.user_id = up.id AND t.is_completed = true)::integer as total_tests_completed
  FROM user_profiles up
  WHERE 
    -- Solo usuarios con email válido
    up.email IS NOT NULL 
    AND up.email != ''
    AND up.email NOT LIKE '%test%'  -- Excluir emails de prueba
    AND up.email != 'ilovetestpro@gmail.com'  -- Excluir tu email de admin
    -- Usuarios que no han recibido email en los últimos 3 días
    AND NOT EXISTS (
      SELECT 1 FROM email_logs el 
      WHERE el.user_id = up.id 
      AND el.sent_at > NOW() - INTERVAL '3 days'
    )
    -- Y que están inactivos hace 7+ días
    AND EXTRACT(days FROM (NOW() - COALESCE(
      (SELECT MAX(t.completed_at) FROM tests t WHERE t.user_id = up.id AND t.is_completed = true),
      up.created_at
    ))) >= 7
    -- Solo usuarios que han completado al menos 1 test (no spam a usuarios que nunca usaron la app)
    AND EXISTS (
      SELECT 1 FROM tests t WHERE t.user_id = up.id AND t.is_completed = true
    )
  ORDER BY days_inactive DESC
  LIMIT 10; -- Máximo 10 emails por ejecución para empezar suave
END;
$$;


--
-- Name: get_law_difficulty_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_law_difficulty_stats() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    result JSONB;
  BEGIN
    SELECT jsonb_build_object(
      'total_questions', (SELECT COUNT(*) FROM questions WHERE is_active = true),
      'total_first_attempts', (SELECT COUNT(*) FROM law_question_first_attempts),
      'questions_with_global_difficulty', (SELECT COUNT(*) FROM questions WHERE global_difficulty IS NOT NULL),
      'avg_global_difficulty', (SELECT ROUND(AVG(global_difficulty), 2) FROM questions WHERE global_difficulty IS NOT NULL),
      'questions_needing_more_data', (SELECT COUNT(*) FROM questions WHERE difficulty_sample_size < 5 AND
  difficulty_sample_size > 0),
      'high_confidence_questions', (SELECT COUNT(*) FROM questions WHERE difficulty_confidence > 0.8),
      'corrupted_test_questions', (SELECT COUNT(*) FROM test_questions WHERE question_id IS NULL)
    ) INTO result;

    RETURN result;
  END;
  $$;


--
-- Name: get_laws_with_question_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_laws_with_question_counts() RETURNS TABLE(id uuid, name text, short_name text, description text, year integer, type text, "questionCount" bigint, "officialQuestions" bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT
      l.id,
      l.name,
      l.short_name,
      l.description,
      l.year,
      l.type,
      COUNT(q.id) AS "questionCount",
      COUNT(q.id) FILTER (WHERE q.is_official_exam = true) AS "officialQuestions"
    FROM laws l
    LEFT JOIN articles a ON a.law_id = l.id
    LEFT JOIN questions q ON q.primary_article_id = a.id AND q.is_active = true
    WHERE l.is_active = true
    GROUP BY l.id, l.name, l.short_name, l.description, l.year, l.type
    HAVING COUNT(q.id) >= 5
    ORDER BY COUNT(q.id) DESC;
  $$;


--
-- Name: get_mastered_questions(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_mastered_questions(p_user_id uuid, p_limit integer DEFAULT 5) RETURNS TABLE(question_id uuid, question_text text, total_attempts integer, success_rate numeric, last_attempt timestamp with time zone, personal_difficulty numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH base AS (
    SELECT uqh.question_id AS q_id, uqh.total_attempts AS ta,
           uqh.correct_attempts::numeric * 100.0 / uqh.total_attempts AS sr
    FROM user_question_history_v2 uqh
    WHERE uqh.user_id = p_user_id AND uqh.total_attempts >= 2
  ),
  s AS (
    SELECT base.q_id, base.ta, base.sr FROM base
    WHERE base.sr >= 80
    ORDER BY base.sr DESC, base.ta DESC, base.q_id ASC
    LIMIT p_limit
  ),
  la AS (
    SELECT tq.question_id AS q_id, MAX(tq.created_at) AS mx
    FROM test_questions tq
    WHERE tq.user_id = p_user_id AND tq.question_id IN (SELECT s.q_id FROM s)
    GROUP BY tq.question_id
  )
  SELECT s.q_id, q.question_text, s.ta::integer, ROUND(s.sr, 2),
         la.mx, ROUND(100 - s.sr, 2)
  FROM s
  JOIN questions q ON q.id = s.q_id
  LEFT JOIN la ON la.q_id = s.q_id
  ORDER BY s.sr DESC, s.ta DESC, s.q_id ASC;
END;
$$;


--
-- Name: get_oposicion_articles(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_oposicion_articles(p_oposicion_id uuid) RETURNS TABLE(article_id uuid, article_number text, article_title text, law_short_name text, via_mapeo text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT * FROM (
        -- Artículos vía topic_scope (lo normal)
        SELECT DISTINCT
            a.id,
            a.article_number,
            a.title,
            l.short_name,
            'topic_scope'::TEXT
        FROM public.oposicion_topics ot
        JOIN public.topics t ON ot.topic_id = t.id
        JOIN public.topic_scope ts ON t.id = ts.topic_id
        JOIN public.articles a ON ts.law_id = a.law_id
        JOIN public.laws l ON a.law_id = l.id
        WHERE ot.oposicion_id = p_oposicion_id
        AND a.is_active = true
        AND (
            (ts.article_numbers IS NOT NULL AND a.article_number = ANY(ts.article_numbers))
            OR
            (ts.include_full_title = true AND ts.title_numbers IS NOT NULL AND a.title_number = ANY(ts.title_numbers))
        )
        
        UNION
        
        -- Artículos directos (casos especiales)
        SELECT DISTINCT
            a.id,
            a.article_number,
            a.title,
            l.short_name,
            'directo'::TEXT
        FROM public.oposicion_articles oa
        JOIN public.articles a ON oa.article_id = a.id
        JOIN public.laws l ON a.law_id = l.id
        WHERE oa.oposicion_id = p_oposicion_id
        AND a.is_active = true
    ) combined_results
    ORDER BY law_short_name, article_number;
END;
$$;


--
-- Name: get_oposicion_coverage_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_oposicion_coverage_stats(p_oposicion_id uuid) RETURNS TABLE(total_articulos_temario integer, articulos_con_preguntas integer, articulos_registrados_examenes integer, cobertura_preguntas numeric, cobertura_examenes numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    total_arts INTEGER;
    arts_with_questions INTEGER;
    arts_in_exams INTEGER;
    coverage_q DECIMAL;
    coverage_e DECIMAL;
BEGIN
    -- Total de artículos en el temario de esta oposición
    SELECT COUNT(DISTINCT oa.article_id) INTO total_arts
    FROM public.get_oposicion_articles(p_oposicion_id) oa;
    
    -- Artículos que tienen preguntas creadas
    SELECT COUNT(DISTINCT oa.article_id) INTO arts_with_questions
    FROM public.get_oposicion_articles(p_oposicion_id) oa
    JOIN public.questions q ON oa.article_id = q.primary_article_id;
    
    -- Artículos que han aparecido en exámenes de esta oposición
    SELECT COUNT(DISTINCT ae.article_id) INTO arts_in_exams
    FROM public.articulos_examenes ae
    JOIN public.convocatorias c ON ae.convocatoria_id = c.id
    WHERE c.oposicion_id = p_oposicion_id;
    
    -- Calcular coberturas
    coverage_q := CASE WHEN total_arts > 0 THEN (arts_with_questions::DECIMAL / total_arts * 100) ELSE 0 END;
    coverage_e := CASE WHEN total_arts > 0 THEN (arts_in_exams::DECIMAL / total_arts * 100) ELSE 0 END;
    
    RETURN QUERY SELECT total_arts, arts_with_questions, arts_in_exams, coverage_q, coverage_e;
END;
$$;


--
-- Name: get_personalized_message(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_personalized_message(p_user_id uuid, p_category text, p_context jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(message_id uuid, message_text text, emoji text, tone text, color_scheme text, times_shown_to_user integer, user_has_liked boolean, user_has_disliked boolean, total_likes integer, total_dislikes integer, like_rate numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_user_gender TEXT;
    v_user_city TEXT;
    v_accuracy NUMERIC;
    v_streak INTEGER;
    v_current_hour INTEGER;
    v_current_day INTEGER;
    v_time_of_day TEXT;
    v_message_id UUID;
    v_message_variants JSONB;
    v_emoji TEXT;
    v_tone TEXT;
    v_color_scheme TEXT;
    v_total_likes INTEGER;
    v_like_rate NUMERIC;
    v_times_shown INTEGER;
    v_has_loved BOOLEAN;
    v_total_dislikes INTEGER;
    v_message_variant TEXT;
    v_total_eligible_messages INTEGER;
    v_messages_shown_to_user INTEGER;
    v_min_times_shown INTEGER;
    v_random_index INTEGER;
    v_variants_count INTEGER;
  BEGIN
    SELECT
      COALESCE(up.gender, 'neutral'),
      COALESCE(up.ciudad, ''),
      COALESCE((p_context->>'accuracy')::numeric, 0),
      COALESCE((p_context->>'streak')::integer, 0)
    INTO v_user_gender, v_user_city, v_accuracy, v_streak
    FROM user_profiles up
    WHERE up.id = p_user_id;

    v_current_hour := EXTRACT(HOUR FROM NOW() AT TIME ZONE 'Europe/Madrid');
    v_current_day := EXTRACT(DOW FROM NOW());

    v_time_of_day := CASE
      WHEN v_current_hour >= 6 AND v_current_hour < 14 THEN 'morning'
      WHEN v_current_hour >= 14 AND v_current_hour < 21 THEN 'afternoon'
      ELSE 'night'
    END;

    SELECT COUNT(*)
    INTO v_total_eligible_messages
    FROM motivational_messages mm
    WHERE mm.is_active = true
      AND mm.category = p_category
      AND (mm.gender_target IN ('neutral', 'any') OR mm.gender_target =
  v_user_gender)
      AND (mm.min_accuracy IS NULL OR v_accuracy >= mm.min_accuracy)
      AND (mm.max_accuracy IS NULL OR v_accuracy <= mm.max_accuracy)
      AND (mm.min_streak IS NULL OR v_streak >= mm.min_streak)
      AND (mm.max_streak IS NULL OR v_streak <= mm.max_streak)
      AND (mm.time_of_day IS NULL OR v_time_of_day = ANY(mm.time_of_day))
      AND (mm.day_of_week IS NULL OR v_current_day = ANY(mm.day_of_week))
      AND NOT EXISTS (
        SELECT 1 FROM user_message_interactions umi_dislike
        WHERE umi_dislike.user_id = p_user_id
          AND umi_dislike.message_id = mm.id
          AND umi_dislike.action_type = 'dislike'
      );

    SELECT COUNT(DISTINCT umi.message_id)
    INTO v_messages_shown_to_user
    FROM user_message_interactions umi
    WHERE umi.user_id = p_user_id
      AND umi.action_type = 'view'
      AND umi.message_id IN (
        SELECT mm2.id FROM motivational_messages mm2
        WHERE mm2.category = p_category AND mm2.is_active = true
      );

    IF v_messages_shown_to_user >= v_total_eligible_messages THEN
      SELECT COALESCE(MIN(view_count), 0)
      INTO v_min_times_shown
      FROM (
        SELECT COUNT(*) as view_count
        FROM user_message_interactions umi
        WHERE umi.user_id = p_user_id
          AND umi.action_type = 'view'
          AND umi.message_id IN (
            SELECT mm3.id
            FROM motivational_messages mm3
            WHERE mm3.is_active = true
              AND mm3.category = p_category
              AND (mm3.gender_target IN ('neutral', 'any') OR
  mm3.gender_target = v_user_gender)
              AND (mm3.min_accuracy IS NULL OR v_accuracy >=
  mm3.min_accuracy)
              AND (mm3.max_accuracy IS NULL OR v_accuracy <=
  mm3.max_accuracy)
              AND (mm3.min_streak IS NULL OR v_streak >= mm3.min_streak)
              AND (mm3.max_streak IS NULL OR v_streak <= mm3.max_streak)
              AND (mm3.time_of_day IS NULL OR v_time_of_day =
  ANY(mm3.time_of_day))
              AND (mm3.day_of_week IS NULL OR v_current_day =
  ANY(mm3.day_of_week))
              AND NOT EXISTS (
                SELECT 1 FROM user_message_interactions umi_dislike2
                WHERE umi_dislike2.user_id = p_user_id
                  AND umi_dislike2.message_id = mm3.id
                  AND umi_dislike2.action_type = 'dislike'
              )
          )
        GROUP BY umi.message_id
      ) counts;
    ELSE
      v_min_times_shown := 0;
    END IF;

    SELECT
      mm.id,
      mm.message_variants,
      mm.emoji,
      mm.tone,
      mm.color_scheme,
      mm.total_likes,
      mm.like_rate,
      COALESCE(user_views.view_count, 0),
      COALESCE(user_reactions.has_love, false),
      COALESCE(total_dislikes.dislike_count, 0)
    INTO
      v_message_id,
      v_message_variants,
      v_emoji,
      v_tone,
      v_color_scheme,
      v_total_likes,
      v_like_rate,
      v_times_shown,
      v_has_loved,
      v_total_dislikes
    FROM motivational_messages mm

    LEFT JOIN (
      SELECT umi_view.message_id, COUNT(*) as view_count
      FROM user_message_interactions umi_view
      WHERE umi_view.user_id = p_user_id AND umi_view.action_type = 'view'
      GROUP BY umi_view.message_id
    ) user_views ON user_views.message_id = mm.id

    LEFT JOIN (
      SELECT umi_react.message_id, true as has_love
      FROM user_message_interactions umi_react
      WHERE umi_react.user_id = p_user_id AND umi_react.action_type IN
  ('love', 'like', 'funny')
    ) user_reactions ON user_reactions.message_id = mm.id

    LEFT JOIN (
      SELECT umi_dislike3.message_id, COUNT(*) as dislike_count
      FROM user_message_interactions umi_dislike3
      WHERE umi_dislike3.action_type = 'dislike'
      GROUP BY umi_dislike3.message_id
    ) total_dislikes ON total_dislikes.message_id = mm.id

    WHERE mm.is_active = true
      AND mm.category = p_category
      AND (mm.gender_target IN ('neutral', 'any') OR mm.gender_target =
  v_user_gender)
      AND (mm.min_accuracy IS NULL OR v_accuracy >= mm.min_accuracy)
      AND (mm.max_accuracy IS NULL OR v_accuracy <= mm.max_accuracy)
      AND (mm.min_streak IS NULL OR v_streak >= mm.min_streak)
      AND (mm.max_streak IS NULL OR v_streak <= mm.max_streak)
      AND (mm.time_of_day IS NULL OR v_time_of_day = ANY(mm.time_of_day))
      AND (mm.day_of_week IS NULL OR v_current_day = ANY(mm.day_of_week))
      AND NOT EXISTS (
        SELECT 1 FROM user_message_interactions umi_check
        WHERE umi_check.user_id = p_user_id
          AND umi_check.message_id = mm.id
          AND umi_check.action_type = 'dislike'
      )
      AND (
        mm.cooldown_hours = 0
        OR NOT EXISTS (
          SELECT 1 FROM user_message_interactions umi_cooldown
          WHERE umi_cooldown.user_id = p_user_id
            AND umi_cooldown.message_id = mm.id
            AND umi_cooldown.action_type = 'view'
            AND umi_cooldown.created_at > NOW() - (mm.cooldown_hours || ' 
  hours')::INTERVAL
        )
      )
      AND COALESCE(user_views.view_count, 0) <= v_min_times_shown

    ORDER BY
      COALESCE(user_views.view_count, 0) ASC,
      CASE WHEN user_reactions.has_love THEN 1 ELSE 0 END DESC,
      mm.like_rate DESC,
      mm.priority DESC,
      RANDOM()

    LIMIT 1;

    IF v_message_id IS NULL THEN
      RETURN;
    END IF;

    v_variants_count := jsonb_array_length(v_message_variants);
    v_random_index := floor(random() * v_variants_count)::int;
    v_message_variant := v_message_variants->>v_random_index;

    v_message_variant := REPLACE(v_message_variant, '{nombre}',
  COALESCE((p_context->>'nombre')::text, 'Estudiante'));
    v_message_variant := REPLACE(v_message_variant, '{ciudad}',
  v_user_city);
    v_message_variant := REPLACE(v_message_variant, '{racha}',
  COALESCE((p_context->>'racha')::text, '0'));
    v_message_variant := REPLACE(v_message_variant, '{nota}',
  COALESCE((p_context->>'nota')::text, '0'));
    v_message_variant := REPLACE(v_message_variant, '{preguntas}',
  COALESCE((p_context->>'preguntas')::text, '0'));
    v_message_variant := REPLACE(v_message_variant, '{porcentaje}',
  COALESCE((p_context->>'porcentaje')::text, '0'));
    v_message_variant := REPLACE(v_message_variant, '{mejora}',
  COALESCE((p_context->>'mejora')::text, '0'));
    v_message_variant := REPLACE(v_message_variant, '{dias}',
  COALESCE((p_context->>'dias')::text, '0'));

    RETURN QUERY SELECT
      v_message_id,
      v_message_variant,
      v_emoji,
      v_tone,
      v_color_scheme,
      v_times_shown::INTEGER,
      v_has_loved,
      false,
      v_total_likes::INTEGER,
      v_total_dislikes::INTEGER,
      v_like_rate;

  END;
  $$;


