--
-- Name: get_personalized_recommendations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_personalized_recommendations(p_user_id uuid) RETURNS TABLE(priority text, title text, description text, action_type text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    RETURN QUERY
    WITH user_stats AS (
      SELECT
        COUNT(DISTINCT tq.question_id) as total_questions,
        COUNT(DISTINCT tq.tema_number) as topics_attempted,
        AVG(CASE WHEN tq.is_correct THEN 100 ELSE 0 END) as avg_accuracy,
        COUNT(*) FILTER (WHERE tq.created_at > NOW() - INTERVAL '7 days') as
  recent_activity
      FROM test_questions tq
      JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = p_user_id
    ),
    struggling_topics AS (
      SELECT
        tq.tema_number,
        COUNT(*) as attempts,
        AVG(CASE WHEN tq.is_correct THEN 100 ELSE 0 END) as accuracy
      FROM test_questions tq
      JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = p_user_id
        AND tq.tema_number IS NOT NULL
      GROUP BY tq.tema_number
      HAVING AVG(CASE WHEN tq.is_correct THEN 100 ELSE 0 END) < 60
        AND COUNT(*) >= 5
      ORDER BY accuracy ASC
      LIMIT 3
    )
    SELECT * FROM (
      SELECT
        'high'::TEXT as priority,
        ('Reforzar Tema ' || tema_number)::TEXT as title,
        ('Tu precisión es del ' || ROUND(accuracy::NUMERIC, 0) || '%. Dedica más 
  tiempo a este tema.')::TEXT as description,
        'study_topic'::TEXT as action_type
      FROM struggling_topics

      UNION ALL

      SELECT
        'medium'::TEXT as priority,
        'Mantén tu ritmo de estudio'::TEXT as title,
        'Has estado menos activo últimamente. Intenta estudiar al menos 15 minutos
   al día.'::TEXT as description,
        'increase_activity'::TEXT as action_type
      FROM user_stats
      WHERE recent_activity < 10

      UNION ALL

      SELECT
        'high'::TEXT as priority,
        'Revisa los conceptos básicos'::TEXT as title,
        ('Tu precisión general es del ' || ROUND(avg_accuracy::NUMERIC, 0) || '%. 
  Repasa los temas fundamentales.')::TEXT as description,
        'review_basics'::TEXT as action_type
      FROM user_stats
      WHERE avg_accuracy < 60

      UNION ALL

      SELECT
        'low'::TEXT as priority,
        'Excelente progreso'::TEXT as title,
        'Tu rendimiento es muy bueno. Considera aumentar la dificultad de las 
  preguntas.'::TEXT as description,
        'increase_difficulty'::TEXT as action_type
      FROM user_stats
      WHERE avg_accuracy > 85
        AND total_questions > 100
    ) recommendations
    ORDER BY
      CASE recommendations.priority
        WHEN 'high' THEN 1
        WHEN 'medium' THEN 2
        WHEN 'low' THEN 3
      END
    LIMIT 5;
  END;
  $$;


--
-- Name: get_popular_custom_oposiciones(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_popular_custom_oposiciones(p_limit integer DEFAULT 10) RETURNS TABLE(id uuid, nombre text, categoria text, administracion text, times_selected integer, created_by text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
      RETURN QUERY
      SELECT
          co.id,
          co.nombre,
          co.categoria,
          co.administracion,
          co.times_selected,
          co.created_by_username
      FROM custom_oposiciones co
      WHERE co.is_public = true
      AND co.is_active = true
      ORDER BY co.times_selected DESC, co.created_at DESC
      LIMIT p_limit;
  END;
  $$;


--
-- Name: get_preguntas_oficiales_por_tema(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_preguntas_oficiales_por_tema(p_oposicion_id uuid, p_topic_name text, p_num_questions integer DEFAULT 10) RETURNS TABLE(pregunta_text text, opcion_a text, opcion_b text, opcion_c text, opcion_d text, respuesta_correcta text, article_number text, law_name text, "año_examen" integer, observaciones text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        peo.pregunta_text,
        peo.opcion_a,
        peo.opcion_b,
        peo.opcion_c,
        peo.opcion_d,
        peo.respuesta_correcta,
        a.article_number,
        l.short_name as law_name,
        c.año as año_examen,
        peo.observaciones
    FROM public.preguntas_examenes_oficiales peo
    JOIN public.convocatorias c ON peo.convocatoria_id = c.id
    LEFT JOIN public.articles a ON peo.article_id = a.id
    LEFT JOIN public.laws l ON a.law_id = l.id
    WHERE c.oposicion_id = p_oposicion_id
    AND (peo.topic_estimado ILIKE '%' || p_topic_name || '%' OR p_topic_name = 'all')
    AND peo.fue_anulada = false
    ORDER BY c.año DESC, RANDOM()
    LIMIT p_num_questions;
END;
$$;


--
-- Name: get_question_counts_by_law(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_question_counts_by_law() RETURNS TABLE(law_short_name text, question_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT l.short_name as law_short_name, count(q.id) as question_count
  FROM questions q
  JOIN articles a ON a.id = q.primary_article_id
  JOIN laws l ON l.id = a.law_id
  WHERE q.is_active = true AND l.is_active = true
  GROUP BY l.short_name
$$;


--
-- Name: get_question_exam_context_v2(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_question_exam_context_v2(p_question_id uuid, p_user_oposicion_id uuid) RETURNS TABLE(mostrar_contexto boolean, mensaje_contexto text, "años_aparicion" integer[], nivel_importancia text, es_articulo_valido boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    article_uuid UUID;
    stats_record RECORD;
    context_message TEXT;
    should_show BOOLEAN := false;
    is_valid_article BOOLEAN := false;
BEGIN
    -- Obtener el artículo principal de la pregunta
    SELECT primary_article_id INTO article_uuid
    FROM public.questions WHERE id = p_question_id;
    
    IF article_uuid IS NULL THEN
        RETURN QUERY SELECT false, '', ARRAY[]::INTEGER[], '', false;
        RETURN;
    END IF;
    
    -- Verificar si este artículo pertenece a esta oposición
    SELECT COUNT(*) > 0 INTO is_valid_article
    FROM public.get_oposicion_articles(p_user_oposicion_id) oa
    WHERE oa.article_id = article_uuid;
    
    -- Solo proceder si el artículo es válido para esta oposición
    IF NOT is_valid_article THEN
        RETURN QUERY SELECT false, '', ARRAY[]::INTEGER[], '', false;
        RETURN;
    END IF;
    
    -- Obtener estadísticas del artículo para esta oposición específica
    SELECT * INTO stats_record
    FROM public.get_article_exam_stats(article_uuid, p_user_oposicion_id);
    
    -- Decidir si mostrar contexto
    IF stats_record.total_apariciones > 0 THEN
        should_show := true;
        
        -- Construir mensaje contextual más específico
        context_message := format(
            '🎯 %s en esta oposición - %s apariciones',
            stats_record.nivel_importancia,
            stats_record.total_apariciones
        );
        
        IF stats_record.ultima_aparicion IS NOT NULL THEN
            context_message := context_message || format(
                ' (última: %s)', 
                stats_record.ultima_aparicion
            );
        END IF;
        
        -- Añadir consejo estratégico
        IF stats_record.nivel_importancia = 'MUY PREGUNTADO' THEN
            context_message := context_message || ' ⚡ ¡MEMORIZA LITERALMENTE!';
        ELSIF stats_record.nivel_importancia = 'FRECUENTE' THEN
            context_message := context_message || ' 📚 Repasar bien';
        END IF;
        
    ELSE
        -- Artículo válido pero no ha caído aún
        context_message := '📝 Artículo del temario pero no registrado en exámenes oficiales recientes';
        should_show := true; -- Mostrar que es del temario
    END IF;
    
    RETURN QUERY SELECT 
        should_show, 
        COALESCE(context_message, ''),
        COALESCE(stats_record.años_aparicion, ARRAY[]::INTEGER[]),
        COALESCE(stats_record.nivel_importancia, 'NO REGISTRADO'),
        is_valid_article;
END;
$$;


--
-- Name: get_question_lifecycle_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_question_lifecycle_history(p_question_id uuid) RETURNS TABLE(id uuid, from_state text, to_state text, reason_code text, changed_at timestamp with time zone, changed_by uuid, ai_verification_id uuid, notes text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT id, from_state, to_state, reason_code, changed_at, changed_by, ai_verification_id, notes
  FROM public.question_lifecycle_history
  WHERE question_id = p_question_id
  ORDER BY changed_at ASC;
$$;


--
-- Name: FUNCTION get_question_lifecycle_history(p_question_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_question_lifecycle_history(p_question_id uuid) IS 'Lee la biografía completa de una pregunta. SECURITY DEFINER bypassa RLS. EXECUTE solo a service_role (admin panel server-side).';


--
-- Name: get_question_stats_by_position(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_question_stats_by_position(p_position_type text) RETURNS TABLE(topic_number integer, topic_title text, total_articles integer, total_questions integer, by_difficulty jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    WITH topic_stats AS (
        SELECT 
            t.topic_number,
            t.title,
            COUNT(DISTINCT a.id) as articles_count,
            COUNT(DISTINCT q.id) as questions_count,
            jsonb_object_agg(
                q.difficulty, 
                COUNT(q.id)
            ) FILTER (WHERE q.difficulty IS NOT NULL) as difficulty_breakdown
        FROM public.topics t
        LEFT JOIN public.topic_scope ts ON t.id = ts.topic_id
        LEFT JOIN public.articles a ON ts.law_id = a.law_id 
            AND (
                (ts.article_numbers IS NOT NULL AND a.article_number = ANY(ts.article_numbers))
                OR (ts.include_full_title = true AND ts.title_numbers IS NOT NULL AND a.title_number = ANY(ts.title_numbers))
            )
        LEFT JOIN public.questions q ON a.id = q.primary_article_id
        WHERE t.position_type = p_position_type
        GROUP BY t.topic_number, t.title
        ORDER BY t.topic_number
    )
    SELECT 
        ts.topic_number,
        ts.title,
        ts.articles_count::INTEGER,
        ts.questions_count::INTEGER,
        COALESCE(ts.difficulty_breakdown, '{}'::jsonb)
    FROM topic_stats ts;
END;
$$;


--
-- Name: get_questions_by_tema_and_difficulty(integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_questions_by_tema_and_difficulty(p_tema_number integer, p_total_questions integer, p_difficulty_filter text) RETURNS TABLE(question_id uuid, question_text text, option_a text, option_b text, option_c text, option_d text, correct_option integer, explanation text, difficulty text, article_number text, article_title text, law_name text, law_short_name text, question_tags text[], primary_article_id uuid, article_content text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    q.id,
    q.question_text,
    q.option_a,
    q.option_b,
    q.option_c,
    q.option_d,
    q.correct_option,
    q.explanation,
    q.difficulty,
    a.article_number,
    a.title,
    l.name,
    l.short_name,
    q.tags,
    q.primary_article_id,
    a.content  -- ✅ NUEVO CAMPO
  FROM questions q
  JOIN articles a ON q.primary_article_id = a.id
  JOIN laws l ON a.law_id = l.id
  JOIN topic_scope ts ON l.id = ts.law_id
  JOIN topics t ON ts.topic_id = t.id
  WHERE t.topic_number = p_tema_number
    AND t.position_type = 'auxiliar_administrativo'
    AND a.article_number = ANY(ts.article_numbers)
    AND q.is_active = true
    AND a.is_active = true
    AND (
      CASE 
        WHEN p_difficulty_filter = 'all' THEN true
        WHEN p_difficulty_filter = 'easy' THEN q.difficulty = 'easy'
        WHEN p_difficulty_filter = 'medium' THEN q.difficulty = 'medium'
        WHEN p_difficulty_filter = 'hard' THEN q.difficulty = 'hard'
        WHEN p_difficulty_filter = 'extreme' THEN q.difficulty = 'extreme'
        ELSE true
      END
    )
  ORDER BY RANDOM()
  LIMIT p_total_questions;
END;
$$;


--
-- Name: get_random_upgrade_message(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_random_upgrade_message(p_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, message_key text, title text, subtitle text, body_message text, highlight text, icon text, gradient text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_total_weight INTEGER;
    v_random_weight INTEGER;
    v_cumulative INTEGER := 0;
    v_selected_id UUID;
  BEGIN
    SELECT COALESCE(SUM(weight), 0) INTO v_total_weight
    FROM upgrade_messages
    WHERE is_active = true;

    IF v_total_weight = 0 THEN
      RETURN;
    END IF;

    v_random_weight := floor(random() * v_total_weight)::INTEGER;

    FOR v_selected_id IN
      SELECT um.id FROM upgrade_messages um WHERE um.is_active = true ORDER BY um.id
    LOOP
      SELECT v_cumulative + um.weight INTO v_cumulative
      FROM upgrade_messages um WHERE um.id = v_selected_id;

      IF v_cumulative > v_random_weight THEN
        RETURN QUERY
        SELECT um.id, um.message_key, um.title, um.subtitle,
               um.body_message, um.highlight, um.icon, um.gradient
        FROM upgrade_messages um WHERE um.id = v_selected_id;
        RETURN;
      END IF;
    END LOOP;

    RETURN QUERY
    SELECT um.id, um.message_key, um.title, um.subtitle,
           um.body_message, um.highlight, um.icon, um.gradient
    FROM upgrade_messages um WHERE um.is_active = true
    ORDER BY um.created_at LIMIT 1;
  END;
  $$;


--
-- Name: get_ranking_for_period(timestamp with time zone, timestamp with time zone, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ranking_for_period(p_start_date timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_min_questions integer DEFAULT 5, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid, total_questions bigint, correct_answers bigint, accuracy numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        combined.user_id,
        COUNT(*)::bigint as total_questions,
        COUNT(*) FILTER (WHERE combined.is_correct)::bigint as correct_answers,
        ROUND((COUNT(*) FILTER (WHERE combined.is_correct)::numeric / COUNT(*)) * 100, 0) as accuracy
    FROM (
        -- Respuestas legislativas
        SELECT t.user_id, tq.is_correct, tq.created_at
        FROM test_questions tq
        INNER JOIN tests t ON t.id = tq.test_id
        WHERE tq.created_at >= p_start_date
          AND (p_end_date IS NULL OR tq.created_at <= p_end_date)

        UNION ALL

        -- Respuestas psicotécnicas
        SELECT pa.user_id, pa.is_correct, pa.created_at
        FROM psychometric_test_answers pa
        WHERE pa.user_id IS NOT NULL
          AND pa.created_at >= p_start_date
          AND (p_end_date IS NULL OR pa.created_at <= p_end_date)
    ) combined
    GROUP BY combined.user_id
    HAVING COUNT(*) >= p_min_questions
    ORDER BY
        accuracy DESC,
        total_questions DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


--
-- Name: FUNCTION get_ranking_for_period(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_min_questions integer, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_ranking_for_period(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_min_questions integer, p_limit integer, p_offset integer) IS 'Ranking unificado (legislativo + psicotécnico) con paginación';


--
-- Name: get_recent_tests_data(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recent_tests_data(days_back integer DEFAULT 30) RETURNS TABLE(user_id uuid, completed_at timestamp with time zone, test_date date)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    RETURN QUERY
    SELECT
      t.user_id,
      t.completed_at,
      DATE(t.completed_at) as test_date
    FROM tests t
    WHERE t.is_completed = true
      AND t.completed_at IS NOT NULL
      AND t.completed_at >= NOW() - (days_back || ' days')::INTERVAL
    ORDER BY t.completed_at DESC;
  END;
  $$;


--
-- Name: get_struggling_questions(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_struggling_questions(p_user_id uuid, p_limit integer DEFAULT 5) RETURNS TABLE(question_id uuid, question_text text, total_attempts integer, success_rate numeric, last_attempt timestamp with time zone, trend text, personal_difficulty numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH base AS (
    SELECT uqh.question_id AS q_id, uqh.total_attempts AS ta,
           uqh.correct_attempts::numeric * 100.0 / uqh.total_attempts AS sr
    FROM user_question_history_v2 uqh
    WHERE uqh.user_id = p_user_id AND uqh.total_attempts >= 2
  ),
  s AS (
    SELECT base.q_id, base.ta, base.sr FROM base
    WHERE base.sr < 60
    ORDER BY base.sr ASC, base.ta DESC, base.q_id ASC
    LIMIT p_limit
  ),
  detail AS (
    SELECT tq.question_id AS qid,
      MAX(tq.created_at) AS last_at,
      COUNT(*) FILTER (WHERE tq.created_at > NOW() - INTERVAL '7 days') AS c7,
      SUM(CASE WHEN tq.is_correct AND tq.created_at > NOW() - INTERVAL '7 days' THEN 1 ELSE 0 END) AS ok7,
      COUNT(*) FILTER (WHERE tq.created_at <= NOW() - INTERVAL '7 days') AS cold,
      SUM(CASE WHEN tq.is_correct AND tq.created_at <= NOW() - INTERVAL '7 days' THEN 1 ELSE 0 END) AS okold
    FROM test_questions tq
    WHERE tq.user_id = p_user_id AND tq.question_id IN (SELECT s.q_id FROM s)
    GROUP BY tq.question_id
  )
  SELECT s.q_id, q.question_text, s.ta::integer, ROUND(s.sr, 2),
    d.last_at,
    (CASE
      WHEN d.c7 = 0 THEN 'stable'
      WHEN d.c7 >= 2 AND (d.ok7::numeric / d.c7) > (d.okold::numeric / NULLIF(d.cold, 0)) THEN 'improving'
      WHEN d.c7 >= 2 AND (d.ok7::numeric / d.c7) < (d.okold::numeric / NULLIF(d.cold, 0)) THEN 'declining'
      ELSE 'stable'
    END)::text,
    ROUND(100 - s.sr, 2)
  FROM s
  JOIN questions q ON q.id = s.q_id
  LEFT JOIN detail d ON d.qid = s.q_id
  ORDER BY s.sr ASC, s.ta DESC, s.q_id ASC;
END;
$$;


--
-- Name: get_subscription_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_subscription_count() RETURNS TABLE(suscritos integer, no_suscritos integer, total integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
      RETURN QUERY
      WITH user_counts AS (
          SELECT
              COUNT(*) FILTER (WHERE ep.unsubscribed_all IS NULL OR
  ep.unsubscribed_all = false) as subscribed_count,
              COUNT(*) FILTER (WHERE ep.unsubscribed_all = true) as
  unsubscribed_count,
              COUNT(*) as total_count
          FROM auth.users u
          LEFT JOIN email_preferences ep ON ep.user_id = u.id
          WHERE u.email_confirmed_at IS NOT NULL
      )
      SELECT
          subscribed_count::INTEGER as suscritos,
          unsubscribed_count::INTEGER as no_suscritos,
          total_count::INTEGER as total
      FROM user_counts;
  END;
  $$;


