-- Name: FUNCTION get_subscription_count(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_subscription_count() IS 'Returns subscription 
  statistics for email tracking admin panel';


--
-- Name: get_tema_stats(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tema_stats(p_tema_number integer) RETURNS TABLE(tema_number integer, tema_title text, total_questions integer, articles_count integer, easy_count integer, medium_count integer, hard_count integer, extreme_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p_tema_number,
    t.title,
    COUNT(q.id)::INTEGER,
    COUNT(DISTINCT a.id)::INTEGER,
    COUNT(CASE WHEN q.difficulty = 'easy' THEN 1 END)::INTEGER,
    COUNT(CASE WHEN q.difficulty = 'medium' THEN 1 END)::INTEGER,
    COUNT(CASE WHEN q.difficulty = 'hard' THEN 1 END)::INTEGER,
    COUNT(CASE WHEN q.difficulty = 'extreme' THEN 1 END)::INTEGER
  FROM questions q
  JOIN articles a ON q.primary_article_id = a.id
  JOIN laws l ON a.law_id = l.id
  JOIN topic_scope ts ON l.id = ts.law_id
  JOIN topics t ON ts.topic_id = t.id
  WHERE t.topic_number = p_tema_number
    AND t.position_type = 'auxiliar_administrativo'
    AND a.article_number = ANY(ts.article_numbers)
    AND q.is_active = true
  GROUP BY t.title;
END;
$$;


--
-- Name: get_theme_performance_by_scope(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_theme_performance_by_scope(p_user_id uuid) RETURNS TABLE(topic_number integer, topic_title text, total_questions bigint, correct_answers bigint, accuracy numeric, average_time numeric, last_practiced timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
      DECLARE
        v_position_type TEXT;
      BEGIN
        -- Obtener la oposición del usuario y normalizarla
        SELECT
          CASE
            WHEN up.target_oposicion ILIKE '%auxiliar_administrativo%' OR up.target_oposicion ILIKE '%auxiliar-administrativo%'
              THEN 'auxiliar_administrativo'
            WHEN up.target_oposicion ILIKE '%administrativo%' AND up.target_oposicion NOT ILIKE '%auxiliar%'
              THEN 'administrativo'
            WHEN up.target_oposicion ILIKE '%auxilio_judicial%' OR up.target_oposicion ILIKE '%auxilio-judicial%'
              THEN 'auxilio_judicial'
            WHEN up.target_oposicion ILIKE '%tramitacion%'
              THEN 'tramitacion_procesal'
            ELSE 'auxiliar_administrativo'
          END INTO v_position_type
        FROM user_profiles up
        WHERE up.id = p_user_id;

        IF v_position_type IS NULL THEN
          v_position_type := 'auxiliar_administrativo';
        END IF;

        RETURN QUERY
        WITH topic_articles_flat AS MATERIALIZED (
          SELECT DISTINCT
            ts.law_id,
            unnest(ts.article_numbers) as article_number,
            top.topic_number,
            top.title as topic_title
          FROM topic_scope ts
          INNER JOIN topics top ON top.id = ts.topic_id
          WHERE top.position_type = v_position_type
        ),
        user_responses AS MATERIALIZED (
          SELECT
            tq.id AS response_id,
            tq.is_correct,
            tq.time_spent_seconds,
            tq.created_at,
            a.article_number,
            a.law_id
          FROM test_questions tq
          INNER JOIN tests t ON t.id = tq.test_id
          INNER JOIN articles a ON a.id = tq.article_id
          WHERE t.user_id = p_user_id
            AND tq.article_id IS NOT NULL
        ),
        responses_with_topics AS (
          SELECT DISTINCT
            ur.response_id,
            ur.is_correct,
            ur.time_spent_seconds,
            ur.created_at,
            taf.topic_number,
            taf.topic_title
          FROM user_responses ur
          INNER JOIN topic_articles_flat taf
            ON taf.law_id = ur.law_id
            AND taf.article_number = ur.article_number
        )
        SELECT
          rwt.topic_number,
          MAX(rwt.topic_title) AS topic_title,
          COUNT(*)::BIGINT AS total_questions,
          SUM(CASE WHEN rwt.is_correct THEN 1 ELSE 0 END)::BIGINT AS correct_answers,
          ROUND(
            (SUM(CASE WHEN rwt.is_correct THEN 1 ELSE 0 END)::NUMERIC / COUNT(*)::NUMERIC) * 100,
            1
          ) AS accuracy,
          ROUND(AVG(COALESCE(rwt.time_spent_seconds, 0))::NUMERIC, 1) AS average_time,
          MAX(rwt.created_at) AS last_practiced
        FROM responses_with_topics rwt
        GROUP BY rwt.topic_number
        ORDER BY rwt.topic_number;
      END;
    $$;


--
-- Name: get_topic_questions_simple(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_topic_questions_simple(p_topic_id uuid) RETURNS TABLE(question_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT q.id
    FROM public.questions q
    JOIN public.question_articles qa ON q.id = qa.question_id
    JOIN public.articles a ON qa.article_id = a.id
    JOIN public.topic_scope ts ON ts.law_id = a.law_id
    WHERE ts.topic_id = p_topic_id
    AND q.is_active = true
    AND (
        (ts.article_numbers IS NOT NULL AND a.article_number = ANY(ts.article_numbers))
        OR
        (ts.include_full_title = true AND ts.title_numbers IS NOT NULL AND a.title_number = ANY(ts.title_numbers))
    );
END;
$$;


--
-- Name: get_topic_questions_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_topic_questions_v2(p_topic_id uuid) RETURNS TABLE(question_id uuid, primary_article text, question_text text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    WITH topic_articles AS (
        -- Obtener todos los artículos que abarca este tema
        SELECT DISTINCT a.id as article_id, a.article_number, a.title
        FROM public.articles a
        JOIN public.topic_scope ts ON ts.law_id = a.law_id
        WHERE ts.topic_id = p_topic_id
        AND a.is_active = true
        AND (
            -- Artículos específicos
            (ts.article_numbers IS NOT NULL AND a.article_number = ANY(ts.article_numbers))
            OR
            -- Títulos completos
            (ts.include_full_title = true AND ts.title_numbers IS NOT NULL AND a.title_number = ANY(ts.title_numbers))
            OR
            -- Capítulos completos
            (ts.include_full_chapter = true AND ts.chapter_numbers IS NOT NULL AND a.chapter_number = ANY(ts.chapter_numbers))
        )
    )
    SELECT 
        q.id,
        CONCAT('Art. ', ta.article_number, ' - ', ta.title),
        q.question_text
    FROM public.questions q
    JOIN topic_articles ta ON q.primary_article_id = ta.article_id
    WHERE q.is_active = true
    ORDER BY ta.article_number;
END;
$$;


--
-- Name: get_unmotivated_new_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_unmotivated_new_users() RETURNS TABLE(user_id uuid, email text, full_name text, days_since_registration integer, registration_date timestamp with time zone, attempted_tests_count integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    up.id as user_id,
    up.email,
    up.full_name,
    EXTRACT(days FROM (NOW() - up.created_at))::integer as days_since_registration,
    up.created_at as registration_date,
    (SELECT COUNT(*) FROM tests t WHERE t.user_id = up.id)::integer as attempted_tests_count
  FROM user_profiles up
  WHERE 
    -- Solo usuarios con email válido
    up.email IS NOT NULL 
    AND up.email != ''
    AND up.email NOT LIKE '%test%'  -- Excluir emails de prueba
    AND up.email != 'ilovetestpro@gmail.com'  -- Excluir tu email de admin
    -- Registrados hace 3+ días pero menos de 30 días (ventana de oportunidad)
    AND EXTRACT(days FROM (NOW() - up.created_at)) >= 3
    AND EXTRACT(days FROM (NOW() - up.created_at)) <= 30
    -- NUNCA completaron un test
    AND NOT EXISTS (
      SELECT 1 FROM tests t WHERE t.user_id = up.id AND t.is_completed = true
    )
    -- No han recibido email de motivación en los últimos 7 días
    AND NOT EXISTS (
      SELECT 1 FROM email_logs el 
      WHERE el.user_id = up.id 
      AND el.email_type = 'bienvenida_motivacional'
      AND el.sent_at > NOW() - INTERVAL '7 days'
    )
  ORDER BY days_since_registration DESC
  LIMIT 5; -- Máximo 5 emails motivacionales por vez (ser suave)
END;
$$;


--
-- Name: get_user_complete_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_complete_stats(p_user_id uuid) RETURNS TABLE(total_questions integer, correct_answers integer, global_accuracy numeric, total_tests integer, completed_tests integer, tema_stats jsonb, law_stats jsonb, difficulty_stats jsonb, monthly_stats jsonb, weekly_progress jsonb, total_study_time integer, average_time_per_question numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    RETURN QUERY
    WITH user_responses AS (
      SELECT
        tq.*,
        t.created_at as test_date,
        t.is_completed
      FROM test_questions tq
      JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = p_user_id
    ),

    tema_calculations AS (
      SELECT
        tema_number,
        COUNT(*) as total,
        SUM(CASE WHEN is_correct THEN 1 ELSE 0 END) as correct,
        ROUND(
          SUM(CASE WHEN is_correct THEN 1 ELSE 0 END)::NUMERIC * 100.0 /
          COUNT(*)::NUMERIC, 2
        ) as accuracy
      FROM user_responses
      WHERE tema_number IS NOT NULL
      GROUP BY tema_number
    ),

    law_calculations AS (
      SELECT
        law_name,
        COUNT(*) as total,
        SUM(CASE WHEN is_correct THEN 1 ELSE 0 END) as correct,
        ROUND(
          SUM(CASE WHEN is_correct THEN 1 ELSE 0 END)::NUMERIC * 100.0 /
          COUNT(*)::NUMERIC, 2
        ) as accuracy
      FROM user_responses
      WHERE law_name IS NOT NULL
      GROUP BY law_name
    ),

    difficulty_calculations AS (
      SELECT
        difficulty,
        COUNT(*) as total,
        SUM(CASE WHEN is_correct THEN 1 ELSE 0 END) as correct
      FROM user_responses
      WHERE difficulty IS NOT NULL
      GROUP BY difficulty
    ),

    monthly_calculations AS (
      SELECT
        TO_CHAR(test_date, 'YYYY-MM') as month,
        COUNT(*) as total,
        SUM(CASE WHEN is_correct THEN 1 ELSE 0 END) as correct,
        ROUND(
          SUM(CASE WHEN is_correct THEN 1 ELSE 0 END)::NUMERIC * 100.0 /
          COUNT(*)::NUMERIC, 2
        ) as accuracy
      FROM user_responses
      GROUP BY TO_CHAR(test_date, 'YYYY-MM')
      ORDER BY month DESC
      LIMIT 12
    ),

    weekly_calculations AS (
      SELECT
        DATE_TRUNC('week', test_date) as week,
        COUNT(*) as total,
        SUM(CASE WHEN is_correct THEN 1 ELSE 0 END) as correct
      FROM user_responses
      WHERE test_date >= NOW() - INTERVAL '8 weeks'
      GROUP BY DATE_TRUNC('week', test_date)
      ORDER BY week DESC
    )

    SELECT
      COUNT(*)::INTEGER as total_questions,
      SUM(CASE WHEN is_correct THEN 1 ELSE 0 END)::INTEGER as correct_answers,
      CASE
        WHEN COUNT(*) > 0 THEN
          ROUND(
            SUM(CASE WHEN is_correct THEN 1 ELSE 0 END)::NUMERIC * 100.0 /
            COUNT(*)::NUMERIC, 2
          )
        ELSE 0
      END as global_accuracy,
      COUNT(DISTINCT test_id)::INTEGER as total_tests,
      COUNT(DISTINCT CASE WHEN is_completed THEN test_id END)::INTEGER as
  completed_tests,

      (SELECT JSONB_AGG(
        JSONB_BUILD_OBJECT(
          'tema', tema_number,
          'total', total,
          'correct', correct,
          'accuracy', accuracy,
          'mastered', CASE WHEN total >= 10 AND accuracy > 80 THEN true ELSE false
   END
        ) ORDER BY tema_number
      ) FROM tema_calculations),

      (SELECT JSONB_AGG(
        JSONB_BUILD_OBJECT(
          'law', law_name,
          'total', total,
          'correct', correct,
          'accuracy', accuracy
        ) ORDER BY total DESC
      ) FROM law_calculations),

      (SELECT JSONB_BUILD_OBJECT(
        'easy', COALESCE((SELECT total FROM difficulty_calculations WHERE
  difficulty = 'easy'), 0),
        'medium', COALESCE((SELECT total FROM difficulty_calculations WHERE
  difficulty = 'medium'), 0),
        'hard', COALESCE((SELECT total FROM difficulty_calculations WHERE
  difficulty = 'hard'), 0),
        'easy_correct', COALESCE((SELECT correct FROM difficulty_calculations
  WHERE difficulty = 'easy'), 0),
        'medium_correct', COALESCE((SELECT correct FROM difficulty_calculations
  WHERE difficulty = 'medium'), 0),
        'hard_correct', COALESCE((SELECT correct FROM difficulty_calculations
  WHERE difficulty = 'hard'), 0)
      )),

      (SELECT JSONB_AGG(
        JSONB_BUILD_OBJECT(
          'month', month,
          'total', total,
          'correct', correct,
          'accuracy', accuracy
        ) ORDER BY month DESC
      ) FROM monthly_calculations),

      (SELECT JSONB_AGG(
        JSONB_BUILD_OBJECT(
          'week', week,
          'total', total,
          'correct', correct
        ) ORDER BY week DESC
      ) FROM weekly_calculations),

      COALESCE(SUM(time_spent_seconds), 0)::INTEGER as total_study_time,
      CASE
        WHEN COUNT(*) > 0 THEN
          ROUND(AVG(time_spent_seconds)::NUMERIC, 2)
        ELSE 0
      END as average_time_per_question

    FROM user_responses;
  END;
  $$;


--
-- Name: get_user_conversion_journey(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_conversion_journey(p_user_id uuid) RETURNS TABLE(event_type text, event_data jsonb, days_since_registration integer, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    RETURN QUERY
    SELECT
      ce.event_type,
      ce.event_data,
      ce.days_since_registration,
      ce.created_at
    FROM conversion_events ce
    WHERE ce.user_id = p_user_id
    ORDER BY ce.created_at ASC;
  END;
  $$;


--
-- Name: get_user_difficulty_metrics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_difficulty_metrics(p_user_id uuid) RETURNS TABLE(user_id uuid, total_questions_attempted integer, questions_mastered integer, questions_struggling integer, avg_personal_difficulty numeric, accuracy_trend text, last_updated timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH uqs AS (
    SELECT uqh.total_attempts AS attempts,
           ROUND(uqh.correct_attempts::numeric * 100.0 / uqh.total_attempts, 2) AS success_rate
    FROM user_question_history_v2 uqh
    WHERE uqh.user_id = p_user_id
  ),
  recent_accuracy AS (
    SELECT CASE
      WHEN COUNT(*) FILTER (WHERE tq.created_at > NOW() - INTERVAL '15 days') = 0 THEN 'stable'
      WHEN (SUM(CASE WHEN tq.is_correct AND tq.created_at > NOW() - INTERVAL '15 days' THEN 1 ELSE 0 END)::numeric * 100.0 /
            NULLIF(COUNT(*) FILTER (WHERE tq.created_at > NOW() - INTERVAL '15 days'), 0)) >
           (SUM(CASE WHEN tq.is_correct AND tq.created_at BETWEEN NOW() - INTERVAL '30 days' AND NOW() - INTERVAL '15 days' THEN 1 ELSE 0 END)::numeric * 100.0 /
            NULLIF(COUNT(*) FILTER (WHERE tq.created_at BETWEEN NOW() - INTERVAL '30 days' AND NOW() - INTERVAL '15 days'), 0))
        THEN 'improving'
      WHEN (SUM(CASE WHEN tq.is_correct AND tq.created_at > NOW() - INTERVAL '15 days' THEN 1 ELSE 0 END)::numeric * 100.0 /
            NULLIF(COUNT(*) FILTER (WHERE tq.created_at > NOW() - INTERVAL '15 days'), 0)) <
           (SUM(CASE WHEN tq.is_correct AND tq.created_at BETWEEN NOW() - INTERVAL '30 days' AND NOW() - INTERVAL '15 days' THEN 1 ELSE 0 END)::numeric * 100.0 /
            NULLIF(COUNT(*) FILTER (WHERE tq.created_at BETWEEN NOW() - INTERVAL '30 days' AND NOW() - INTERVAL '15 days'), 0))
        THEN 'declining'
      ELSE 'stable'
    END AS trend
    FROM test_questions tq
    WHERE tq.user_id = p_user_id
      AND tq.created_at > NOW() - INTERVAL '30 days'
  )
  SELECT
    p_user_id,
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE uqs.success_rate >= 80 AND uqs.attempts >= 2)::integer,
    COUNT(*) FILTER (WHERE uqs.success_rate < 50 AND uqs.attempts >= 2)::integer,
    ROUND(AVG(CASE WHEN uqs.success_rate > 0 THEN (100 - uqs.success_rate) ELSE 50 END), 2),
    COALESCE((SELECT recent_accuracy.trend FROM recent_accuracy), 'stable'),
    NOW()
  FROM uqs;
END;
$$;


--
-- Name: get_user_problematic_articles_weekly(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_problematic_articles_weekly(user_uuid uuid) RETURNS TABLE(article_id uuid, article_number text, law_name text, total_attempts integer, correct_attempts integer, accuracy_percentage numeric, last_attempt_date timestamp with time zone, recommendation text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    tq.article_id,
    a.article_number,
    l.short_name as law_name,
    COUNT(*)::integer as total_attempts,
    SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::integer as correct_attempts,
    ROUND(
      (SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::numeric / COUNT(*)) * 100, 
      1
    ) as accuracy_percentage,
    MAX(tq.created_at) as last_attempt_date,
    CASE 
      WHEN ROUND((SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::numeric / COUNT(*)) * 100, 1) = 0 
        THEN '📚 Repasar teoría urgente'
      WHEN ROUND((SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::numeric / COUNT(*)) * 100, 1) < 30 
        THEN '⚠️ Necesita más práctica'
      WHEN ROUND((SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::numeric / COUNT(*)) * 100, 1) < 50 
        THEN '📖 Repasar conceptos'
      ELSE '👍 Casi dominado'
    END as recommendation
  FROM test_questions tq
  JOIN tests t ON tq.test_id = t.id
  JOIN articles a ON tq.article_id = a.id
  JOIN laws l ON a.law_id = l.id
  WHERE t.user_id = user_uuid
    AND t.is_completed = true
    AND tq.created_at >= CURRENT_DATE - INTERVAL '7 days'  -- Solo última semana
    AND tq.article_id IS NOT NULL
  GROUP BY tq.article_id, a.article_number, l.short_name
  HAVING 
    COUNT(*) >= 1  -- Al menos 1 intento
    AND ROUND((SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::numeric / COUNT(*)) * 100, 1) < 60  -- Menos de 60% accuracy
  ORDER BY 
    accuracy_percentage ASC,  -- Peores primero
    total_attempts DESC       -- Más intentados primero si mismo accuracy
  LIMIT 5;  -- Máximo 5 artículos problemáticos
END;
$$;


--
-- Name: get_user_progress_trends(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_progress_trends(p_user_id uuid) RETURNS TABLE(total integer, improving integer, stable integer, declining integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH active AS (
    SELECT DISTINCT tq.question_id AS qid
    FROM test_questions tq
    WHERE tq.user_id = p_user_id
      AND tq.question_id IS NOT NULL
      AND tq.created_at > NOW() - INTERVAL '14 days'
  ),
  recent7 AS (
    SELECT tq.question_id AS qid,
      COUNT(*) AS c7,
      SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END) AS ok7
    FROM test_questions tq
    WHERE tq.user_id = p_user_id
      AND tq.question_id IS NOT NULL
      AND tq.created_at > NOW() - INTERVAL '7 days'
    GROUP BY tq.question_id
  ),
  qt AS (
    SELECT (CASE
      WHEN COALESCE(r.c7, 0) < 2 THEN 'stable'
      WHEN (r.ok7::numeric / r.c7) >
           ((uqh.correct_attempts - r.ok7)::numeric / NULLIF(uqh.total_attempts - r.c7, 0))
        THEN 'improving'
      WHEN (r.ok7::numeric / r.c7) <
           ((uqh.correct_attempts - r.ok7)::numeric / NULLIF(uqh.total_attempts - r.c7, 0))
        THEN 'declining'
      ELSE 'stable'
    END) AS trend
    FROM user_question_history_v2 uqh
    JOIN active a ON a.qid = uqh.question_id
    LEFT JOIN recent7 r ON r.qid = uqh.question_id
    WHERE uqh.user_id = p_user_id AND uqh.total_attempts >= 2
  )
  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (WHERE qt.trend = 'improving')::integer,
    COUNT(*) FILTER (WHERE qt.trend = 'stable')::integer,
    COUNT(*) FILTER (WHERE qt.trend = 'declining')::integer
  FROM qt;
END;
$$;


--
-- Name: get_user_public_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_public_stats(p_user_id uuid) RETURNS TABLE(user_id uuid, user_created_at timestamp with time zone, total_questions bigint, correct_answers bigint, global_accuracy numeric, total_tests bigint, current_streak integer, longest_streak integer, target_oposicion text, mastered_topics bigint, total_topics integer, last_activity timestamp with time zone, study_days bigint, total_study_time bigint, average_time_per_question numeric, best_performance_time text, favorite_topics text[], weak_areas text[], improvement_rate numeric, predicted_score numeric, study_consistency numeric, total_tests_completed bigint, today_tests bigint, today_questions bigint, today_correct bigint, questions_this_week bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_target_oposicion TEXT;
  v_total_topics INTEGER;
BEGIN
  -- 1. Obtener la oposición objetivo del usuario
  SELECT up.target_oposicion INTO v_target_oposicion
  FROM user_profiles up
  WHERE up.id = p_user_id;

  -- 2. Normalizar slug (convertir guiones bajos a guiones)
  v_target_oposicion := REPLACE(COALESCE(v_target_oposicion, 'auxiliar-administrativo-estado'), '_', '-');

  -- 3. Obtener total_topics de la tabla oposiciones
  SELECT COALESCE(o.temas_count, 28) INTO v_total_topics
  FROM oposiciones o
  WHERE o.slug = v_target_oposicion;

  -- Si no se encuentra, usar 28 como default (Auxiliar)
  IF v_total_topics IS NULL THEN
    v_total_topics := 28;
  END IF;

  RETURN QUERY
  WITH user_stats AS (
    SELECT
      u.id AS user_id,
      u.created_at AS user_created_at,
      up.target_oposicion
    FROM auth.users u
    LEFT JOIN user_profiles up ON up.id = u.id
    WHERE u.id = p_user_id
  ),
  -- Usar test_questions en lugar de detailed_answers
  answer_stats AS (
    SELECT
      COUNT(*) AS total_questions,
      COUNT(*) FILTER (WHERE tq.is_correct) AS correct_answers,
      ROUND(
        CASE WHEN COUNT(*) > 0
        THEN (COUNT(*) FILTER (WHERE tq.is_correct)::NUMERIC / COUNT(*)::NUMERIC) * 100
        ELSE 0 END,
        1
      ) AS global_accuracy,
      MAX(tq.created_at) AS last_activity,
      COUNT(DISTINCT DATE(tq.created_at AT TIME ZONE 'Europe/Madrid')) AS study_days,
      COALESCE(SUM(tq.time_spent_seconds), 0) AS total_study_time,
      ROUND(
        CASE WHEN COUNT(*) > 0
        THEN AVG(tq.time_spent_seconds)
        ELSE 0 END,
        2
      ) AS average_time_per_question
    FROM test_questions tq
    JOIN tests t ON t.id = tq.test_id
    WHERE t.user_id = p_user_id
  ),
  test_stats AS (
    SELECT
      COUNT(*) AS total_tests,
      COUNT(*) FILTER (WHERE t.is_completed) AS total_tests_completed
    FROM tests t
    WHERE t.user_id = p_user_id
  ),
  streak_stats AS (
    SELECT
      COALESCE(us.current_streak, 0) AS current_streak,
      COALESCE(us.longest_streak, 0) AS longest_streak
    FROM user_streaks us
    WHERE us.user_id = p_user_id
  ),
  -- Contar temas dominados (≥70% accuracy con ≥10 preguntas)
  mastered_stats AS (
    SELECT COUNT(DISTINCT tema_number) AS mastered_count
    FROM (
      SELECT
        tq.tema_number,
        COUNT(*) AS total,
        ROUND((COUNT(*) FILTER (WHERE tq.is_correct)::NUMERIC / NULLIF(COUNT(*)::NUMERIC, 0)) * 100, 1) AS accuracy
      FROM test_questions tq
      JOIN tests t ON t.id = tq.test_id
      WHERE t.user_id = p_user_id
        AND tq.tema_number IS NOT NULL
      GROUP BY tq.tema_number
      HAVING COUNT(*) >= 10
    ) tema_stats
    WHERE accuracy >= 70
      -- Filtrar por temas válidos según oposición
      AND (
        (v_target_oposicion = 'auxiliar-administrativo-estado' AND (
          tema_number BETWEEN 1 AND 16 OR tema_number BETWEEN 101 AND 112
        ))
        OR
        (v_target_oposicion = 'administrativo-estado' AND (
          tema_number BETWEEN 1 AND 16 OR
          tema_number BETWEEN 101 AND 112 OR
          tema_number BETWEEN 201 AND 207 OR
          tema_number BETWEEN 301 AND 307 OR
          tema_number BETWEEN 401 AND 409 OR
          tema_number BETWEEN 501 AND 506
        ))
        OR
        (v_target_oposicion NOT IN ('auxiliar-administrativo-estado', 'administrativo-estado'))
      )
  ),
  today_stats AS (
    SELECT
      COUNT(DISTINCT t.id) AS today_tests,
      COUNT(tq.id) AS today_questions,
      COUNT(tq.id) FILTER (WHERE tq.is_correct) AS today_correct
    FROM tests t
    LEFT JOIN test_questions tq ON tq.test_id = t.id
    WHERE t.user_id = p_user_id
      AND t.created_at >= (CURRENT_DATE AT TIME ZONE 'Europe/Madrid')
      AND t.created_at < ((CURRENT_DATE + INTERVAL '1 day') AT TIME ZONE 'Europe/Madrid')
  ),
  week_stats AS (
    SELECT COUNT(*) AS questions_this_week
    FROM test_questions tq
    JOIN tests t ON t.id = tq.test_id
    WHERE t.user_id = p_user_id
      AND tq.created_at >= (DATE_TRUNC('week', CURRENT_DATE)::DATE AT TIME ZONE 'Europe/Madrid')
  )
  SELECT
    us.user_id,
    us.user_created_at,
    COALESCE(ans.total_questions, 0),
    COALESCE(ans.correct_answers, 0),
    COALESCE(ans.global_accuracy, 0),
    COALESCE(ts.total_tests, 0),
    COALESCE(ss.current_streak, 0),
    COALESCE(ss.longest_streak, 0),
    us.target_oposicion,
    COALESCE(ms.mastered_count, 0),
    v_total_topics,  -- Ahora es dinámico
    ans.last_activity,
    COALESCE(ans.study_days, 0),
    COALESCE(ans.total_study_time, 0),
    COALESCE(ans.average_time_per_question, 0),
    'afternoon'::TEXT,  -- Simplified
    ARRAY[]::TEXT[],
    ARRAY[]::TEXT[],
    0::NUMERIC,
    0::NUMERIC,
    CASE WHEN ans.study_days > 0
      THEN ROUND((ans.study_days::NUMERIC / 30) * 100, 2)
      ELSE 0
    END,
    COALESCE(ts.total_tests_completed, 0),
    COALESCE(tds.today_tests, 0),
    COALESCE(tds.today_questions, 0),
    COALESCE(tds.today_correct, 0),
    COALESCE(ws.questions_this_week, 0)
  FROM user_stats us
  CROSS JOIN answer_stats ans
  CROSS JOIN test_stats ts
  LEFT JOIN streak_stats ss ON TRUE
  CROSS JOIN mastered_stats ms
  CROSS JOIN today_stats tds
  CROSS JOIN week_stats ws;
END;
$$;


--
-- Name: FUNCTION get_user_public_stats(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_user_public_stats(p_user_id uuid) IS 'Estadísticas públicas del usuario. Usa test_questions (no detailed_answers). total_topics es dinámico según la oposición.';


--
-- Name: get_user_ranking_position(uuid, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_ranking_position(p_user_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_min_questions integer DEFAULT 5) RETURNS TABLE(user_rank bigint, total_questions bigint, correct_answers bigint, accuracy numeric, total_users_in_ranking bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    WITH user_stats AS (
        SELECT
            combined.user_id,
            COUNT(*)::bigint as total_questions,
            COUNT(*) FILTER (WHERE combined.is_correct)::bigint as correct_answers,
            ROUND((COUNT(*) FILTER (WHERE combined.is_correct)::numeric / COUNT(*)) * 100, 0) as accuracy
        FROM (
            SELECT t.user_id, tq.is_correct, tq.created_at
            FROM test_questions tq
            INNER JOIN tests t ON t.id = tq.test_id
            WHERE tq.created_at >= p_start_date
              AND (p_end_date IS NULL OR tq.created_at <= p_end_date)

            UNION ALL

            SELECT pa.user_id, pa.is_correct, pa.created_at
            FROM psychometric_test_answers pa
            WHERE pa.user_id IS NOT NULL
              AND pa.created_at >= p_start_date
              AND (p_end_date IS NULL OR pa.created_at <= p_end_date)
        ) combined
        GROUP BY combined.user_id
        HAVING COUNT(*) >= p_min_questions
    ),
    ranked_users AS (
        SELECT
            us.user_id,
            us.total_questions as tq,
            us.correct_answers as ca,
            us.accuracy as acc,
            ROW_NUMBER() OVER (ORDER BY us.accuracy DESC, us.total_questions DESC) as rank
        FROM user_stats us
    )
    SELECT
        ru.rank::bigint as user_rank,
        ru.tq as total_questions,
        ru.ca as correct_answers,
        ru.acc as accuracy,
        (SELECT COUNT(*) FROM ranked_users)::bigint as total_users_in_ranking
    FROM ranked_users ru
    WHERE ru.user_id = p_user_id;
END;
$$;


--
-- Name: FUNCTION get_user_ranking_position(p_user_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_min_questions integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_user_ranking_position(p_user_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_min_questions integer) IS 'Posición del usuario en ranking unificado (legislativo + psicotécnico)';


--
-- Name: get_user_share_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_share_stats(p_user_id uuid) RETURNS TABLE(total_shares bigint, shares_last_30_days bigint, last_share_at timestamp with time zone, platforms_used text[], total_tests bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$                                                                                     
  BEGIN                                                                                       
    RETURN QUERY                                                                              
    SELECT                                                                                    
      COUNT(se.id)::bigint as total_shares,                                                   
      COUNT(se.id) FILTER (WHERE se.created_at > now() - interval '30 days')::bigint as       
  shares_last_30_days,                                                                        
      MAX(se.created_at) as last_share_at,                                                    
      ARRAY_AGG(DISTINCT se.platform) FILTER (WHERE se.platform IS NOT NULL) as               
  platforms_used,                                                                             
      (SELECT COUNT(*) FROM detailed_answers da WHERE da.user_id = p_user_id)::bigint as      
  total_tests                                                                                 
    FROM share_events se                                                                      
    WHERE se.user_id = p_user_id;                                                             
  END;                                                                                        
  $$;


--
-- Name: get_user_statistics_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_statistics_complete(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
    result JSON;
    v_total_questions BIGINT;
    v_correct_answers BIGINT;
    v_total_study_time BIGINT;
    v_tests_completed BIGINT;
  BEGIN
    -- ===========================================
    -- 1. CONTEOS GLOBALES (una sola pasada)
    -- ===========================================
    SELECT
      COUNT(*),
      SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)
    INTO v_total_questions, v_correct_answers
    FROM test_questions tq
    JOIN tests t ON tq.test_id = t.id
    WHERE t.user_id = p_user_id;

    -- Total tests completados y tiempo de estudio
    SELECT
      COUNT(*),
      COALESCE(SUM(total_time_seconds), 0)
    INTO v_tests_completed, v_total_study_time
    FROM tests
    WHERE user_id = p_user_id
      AND is_completed = true
      AND completed_at IS NOT NULL;

    -- ===========================================
    -- 2. CONSTRUIR JSON COMPLETO
    -- ===========================================
    SELECT json_build_object(
      -- ========== ESTADÍSTICAS BÁSICAS ==========
      'tests_completed', v_tests_completed,
      'total_questions', v_total_questions,
      'correct_answers', v_correct_answers,
      'accuracy', CASE WHEN v_total_questions > 0
        THEN ROUND((v_correct_answers::NUMERIC / v_total_questions) * 100, 1)
        ELSE 0 END,
      'total_study_time', v_total_study_time,

      -- ========== TIEMPO PROMEDIO ==========
      'average_time', (
        SELECT COALESCE(ROUND(AVG(time_spent_seconds)), 0)
        FROM test_questions tq
        JOIN tests t ON tq.test_id = t.id
        WHERE t.user_id = p_user_id
          AND tq.time_spent_seconds IS NOT NULL
          AND tq.time_spent_seconds > 0
          AND tq.time_spent_seconds < 300
      ),

      -- ========== MEJOR PUNTUACIÓN ==========
      'best_score', (
        SELECT COALESCE(MAX(ROUND((score::NUMERIC / NULLIF(total_questions, 0)) * 100)), 0)
        FROM tests
        WHERE user_id = p_user_id
          AND is_completed = true
          AND total_questions > 0
      ),

      -- ========== RACHA ACTUAL ==========
      'current_streak', (
        WITH consecutive_days AS (
          SELECT DISTINCT DATE(completed_at AT TIME ZONE 'Europe/Madrid') as study_date
          FROM tests
          WHERE user_id = p_user_id
            AND completed_at IS NOT NULL
          ORDER BY study_date DESC
        ),
        streak_calc AS (
          SELECT
            study_date,
            study_date - (ROW_NUMBER() OVER (ORDER BY study_date DESC))::INT as grp
          FROM consecutive_days
          WHERE study_date >= CURRENT_DATE - INTERVAL '30 days'
        )
        SELECT COALESCE(COUNT(*), 0)
        FROM streak_calc
        WHERE grp = (
          SELECT grp FROM streak_calc
          WHERE study_date >= CURRENT_DATE - INTERVAL '1 day'
          LIMIT 1
        )
      ),

      -- ========== TESTS RECIENTES (últimos 10) ==========
      'recent_tests', (
        SELECT COALESCE(json_agg(recent), '[]'::json)
        FROM (
          SELECT
            id,
            title,
            test_type,
            tema_number,
            score,
            total_questions,
            ROUND((score::NUMERIC / NULLIF(total_questions, 0)) * 100) as percentage,
            total_time_seconds,
            completed_at
          FROM tests
          WHERE user_id = p_user_id
            AND is_completed = true
            AND completed_at IS NOT NULL
          ORDER BY completed_at DESC
          LIMIT 10
        ) recent
      ),

      -- ========== PROGRESO SEMANAL (últimas 4 semanas) ==========
      'weekly_progress', (
        SELECT COALESCE(json_agg(weekly ORDER BY week_start), '[]'::json)
        FROM (
          SELECT
            DATE_TRUNC('week', tq.created_at AT TIME ZONE 'Europe/Madrid') as week_start,
            COUNT(*) as questions_answered,
            SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END) as correct_answers,
            ROUND((SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::NUMERIC / COUNT(*)) * 100, 1) as accuracy,
            COUNT(DISTINCT t.id) as tests_completed,
            COALESCE(SUM(t.total_time_seconds), 0) as study_time
          FROM test_questions tq
          JOIN tests t ON tq.test_id = t.id
          WHERE t.user_id = p_user_id
            AND tq.created_at >= NOW() - INTERVAL '4 weeks'
          GROUP BY DATE_TRUNC('week', tq.created_at AT TIME ZONE 'Europe/Madrid')
        ) weekly
      ),

      -- ========== DESGLOSE POR DIFICULTAD ==========
      'difficulty_breakdown', (
        SELECT COALESCE(json_agg(diff), '[]'::json)
        FROM (
          SELECT
            COALESCE(tq.difficulty, 'unknown') as difficulty,
            COUNT(*) as total,
            SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END) as correct,
            ROUND((SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::NUMERIC / COUNT(*)) * 100, 1) as accuracy,
            ROUND(AVG(CASE WHEN tq.time_spent_seconds > 0 AND tq.time_spent_seconds < 300
              THEN tq.time_spent_seconds END)) as avg_time
          FROM test_questions tq
          JOIN tests t ON tq.test_id = t.id
          WHERE t.user_id = p_user_id
          GROUP BY COALESCE(tq.difficulty, 'unknown')
          HAVING COUNT(*) >= 5
          ORDER BY
            CASE COALESCE(tq.difficulty, 'unknown')
              WHEN 'easy' THEN 1
              WHEN 'medium' THEN 2
              WHEN 'hard' THEN 3
              WHEN 'extreme' THEN 4
              ELSE 5
            END
        ) diff
      ),

      -- ========== RENDIMIENTO POR TEMA (top 20) ==========
      'theme_performance', (
        SELECT COALESCE(json_agg(theme), '[]'::json)
        FROM (
          SELECT
            COALESCE(tq.tema_number, 0) as tema_number,
            COUNT(*) as total,
            SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END) as correct,
            ROUND((SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::NUMERIC / COUNT(*)) * 100, 1) as accuracy,
            ROUND(AVG(CASE WHEN tq.time_spent_seconds > 0 THEN tq.time_spent_seconds END)) as avg_time,
            COUNT(DISTINCT tq.article_number) as articles_count
          FROM test_questions tq
          JOIN tests t ON tq.test_id = t.id
          WHERE t.user_id = p_user_id
          GROUP BY COALESCE(tq.tema_number, 0)
          HAVING COUNT(*) >= 3
          ORDER BY accuracy ASC, total DESC
          LIMIT 20
        ) theme
      ),

      -- ========== RENDIMIENTO POR ARTÍCULO (top 30 peores) ==========
      'article_performance', (
        SELECT COALESCE(json_agg(article), '[]'::json)
        FROM (
          SELECT
            tq.law_name,
            tq.article_number,
            COALESCE(tq.tema_number, 0) as tema_number,
            COUNT(*) as total,
            SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END) as correct,
            ROUND((SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::NUMERIC / COUNT(*)) * 100, 1) as accuracy,
            ROUND(AVG(CASE WHEN tq.time_spent_seconds > 0 THEN tq.time_spent_seconds END)) as avg_time
          FROM test_questions tq
          JOIN tests t ON tq.test_id = t.id
          WHERE t.user_id = p_user_id
            AND tq.law_name IS NOT NULL
            AND tq.article_number IS NOT NULL
          GROUP BY tq.law_name, tq.article_number, COALESCE(tq.tema_number, 0)
          HAVING COUNT(*) >= 2
          ORDER BY accuracy ASC, total DESC
          LIMIT 30
        ) article
      ),

      -- ========== PATRONES DE TIEMPO (por hora del día) ==========
      'time_patterns', (
        SELECT COALESCE(json_agg(hourly), '[]'::json)
        FROM (
          SELECT
            EXTRACT(HOUR FROM t.completed_at AT TIME ZONE 'Europe/Madrid')::INT as hour,
            COUNT(DISTINCT t.id) as tests,
            ROUND(AVG((t.score::NUMERIC / NULLIF(t.total_questions, 0)) * 100), 1) as accuracy
          FROM tests t
          WHERE t.user_id = p_user_id
            AND t.completed_at IS NOT NULL
            AND t.is_completed = true
            AND t.total_questions > 0
          GROUP BY EXTRACT(HOUR FROM t.completed_at AT TIME ZONE 'Europe/Madrid')
          HAVING COUNT(*) >= 2
          ORDER BY hour
        ) hourly
      ),

      -- ========== DÍAS ACTIVOS (últimos 30 días) ==========
      'active_days', (
        SELECT COUNT(DISTINCT DATE(completed_at AT TIME ZONE 'Europe/Madrid'))
        FROM tests
        WHERE user_id = p_user_id
          AND completed_at IS NOT NULL
          AND completed_at >= NOW() - INTERVAL '30 days'
      ),

      -- ========== PREGUNTAS HOY ==========
      'questions_today', (
        SELECT COUNT(*)
        FROM test_questions tq
        JOIN tests t ON tq.test_id = t.id
        WHERE t.user_id = p_user_id
          AND DATE(tq.created_at AT TIME ZONE 'Europe/Madrid') = CURRENT_DATE
      ),

      -- ========== METADATA ==========
      'generated_at', NOW(),
      'user_id', p_user_id

    ) INTO result;

    RETURN result;
  END;
  $$;


--
-- Name: get_user_theme_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_theme_stats(p_user_id uuid) RETURNS TABLE(tema_number integer, total bigint, correct bigint, accuracy numeric, last_study timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    RETURN QUERY
    SELECT
      tq.tema_number,
      COUNT(*) as total,
      SUM(CASE WHEN tq.is_correct = true THEN 1 ELSE 0 END) as correct,
      ROUND((SUM(CASE WHEN tq.is_correct = true THEN 1 ELSE 0 END)::numeric
   / COUNT(*)) * 100, 0) as accuracy,
      MAX(tq.created_at) as last_study
    FROM test_questions tq
    JOIN tests t ON tq.test_id = t.id
    WHERE t.user_id = p_user_id AND tq.tema_number IS NOT NULL
    GROUP BY tq.tema_number
    ORDER BY tq.tema_number;
  END;
  $$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
  BEGIN
      -- Insertar en user_profiles
      INSERT INTO public.user_profiles (id, email, full_name, avatar_url)
      VALUES (
          NEW.id,
          NEW.email,
          NEW.raw_user_meta_data->>'full_name',
          NEW.raw_user_meta_data->>'avatar_url'
      );

      -- Insertar en public_user_profiles para rankings
      INSERT INTO public.public_user_profiles (id, display_name)
      VALUES (
          NEW.id,
          COALESCE(
              NULLIF(trim(split_part(NEW.raw_user_meta_data->>'full_name', ' ',
  1)), ''),
              split_part(NEW.email, '@', 1),
              'Usuario'
          )
      );

      RETURN NEW;
  EXCEPTION
      WHEN OTHERS THEN
          -- Log el error pero no fallar el registro
          RAISE WARNING 'Error en handle_new_user para user %: %', NEW.id,
  SQLERRM;
          RETURN NEW;
  END;
  $$;


--
-- Name: hybrid_search_articles(extensions.vector, text, integer, double precision, double precision, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hybrid_search_articles(query_embedding extensions.vector, query_text text, match_count integer DEFAULT 15, semantic_weight double precision DEFAULT 0.4, text_weight double precision DEFAULT 0.6, priority_law_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS TABLE(id uuid, article_number text, title text, content text, law_id uuid, law_short_name text, semantic_score double precision, text_score double precision, combined_score double precision)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  DECLARE                                                                        
    or_query tsquery;
    has_priorities boolean;
    lexemes text;                                                                
  BEGIN
    has_priorities := array_length(priority_law_ids, 1) IS NOT NULL              
                      AND array_length(priority_law_ids, 1) > 0;
                                                                                 
    lexemes := array_to_string(
      ARRAY(                                                                     
        SELECT lexeme
        FROM unnest(to_tsvector('spanish', COALESCE(query_text, ''))) AS         
  t(lexeme, positions, weights)                                                  
      ),                                                                         
      ' | '                                                                      
    );            

    IF lexemes IS NULL OR lexemes = '' THEN                                      
      or_query := ''::tsquery;
    ELSE                                                                         
      or_query := to_tsquery('spanish', lexemes);
    END IF;                                                                      
  
    RETURN QUERY                                                                 
    WITH semantic AS (
      SELECT                                                                     
        a.id, a.article_number, a.title, a.content, a.law_id,
        l.short_name AS law_short_name,                                          
        CASE                                                                     
          WHEN a.embedding IS NULL THEN 0::float
          WHEN (a.embedding <=> query_embedding) IS NULL THEN 0::float           
          WHEN (a.embedding <=> query_embedding)::text = 'NaN' THEN 0::float     
          ELSE GREATEST(0, 1 - (a.embedding <=> query_embedding))::float         
        END AS score                                                             
      FROM articles a JOIN laws l ON a.law_id = l.id                             
      WHERE a.is_active = true AND a.embedding IS NOT NULL                       
        AND l.is_active = true AND (l.is_derogated IS NULL OR l.is_derogated =   
  false)                                                                         
      ORDER BY a.embedding <=> query_embedding                                   
      LIMIT 30                                                                   
    ),            
    fulltext AS (                                                                
      SELECT      
        a.id, a.article_number, a.title, a.content, a.law_id,                    
        l.short_name AS law_short_name,
        ts_rank_cd(                                                              
          setweight(to_tsvector('spanish', COALESCE(a.title,   '')), 'A') ||     
          setweight(to_tsvector('spanish', COALESCE(a.content, '')), 'B'),       
          or_query,                                                              
          32                                                                     
        )::float AS score
      FROM articles a JOIN laws l ON a.law_id = l.id                             
      WHERE a.is_active = true AND l.is_active = true
        AND (l.is_derogated IS NULL OR l.is_derogated = false)                   
        AND or_query <> ''::tsquery
        AND (                                                                    
          setweight(to_tsvector('spanish', COALESCE(a.title,   '')), 'A') ||
          setweight(to_tsvector('spanish', COALESCE(a.content, '')), 'B')        
        ) @@ or_query                                                            
      ORDER BY score DESC
      LIMIT 30                                                                   
    ),                                                                           
    combined AS (
      SELECT                                                                     
        COALESCE(s.id, f.id) AS id,
        COALESCE(s.article_number, f.article_number) AS article_number,          
        COALESCE(s.title, f.title) AS title,
        COALESCE(s.content, f.content) AS content,                               
        COALESCE(s.law_id, f.law_id) AS law_id,                                  
        COALESCE(s.law_short_name, f.law_short_name) AS law_short_name,
        COALESCE(s.score, 0)::float AS semantic_score,                           
        COALESCE(f.score, 0)::float AS text_score,                               
        (
          COALESCE(s.score, 0) * semantic_weight                                 
          + COALESCE(f.score, 0) * text_weight
          + CASE                                                                 
              WHEN has_priorities                                                
                AND COALESCE(s.law_id, f.law_id) = ANY(priority_law_ids)
              THEN 0.3                                                           
              ELSE 0
            END                                                                  
        )::float AS combined_score
      FROM semantic s                                                            
      FULL OUTER JOIN fulltext f ON s.id = f.id
    )                                                                            
    SELECT combined.id, combined.article_number, combined.title,
  combined.content,                                                              
           combined.law_id, combined.law_short_name,
           combined.semantic_score, combined.text_score, combined.combined_score 
    FROM combined
    ORDER BY combined.combined_score DESC                                        
    LIMIT match_count;
  END;                                                                           
  $$;


