--
-- Name: lifecycle_grandfather_expire(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lifecycle_grandfather_expire(p_days_threshold integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_question_id uuid;
  v_count integer := 0;
  v_failed integer := 0;
  v_chunk_size integer := 500;
  v_processed integer := 0;
BEGIN
  FOR v_question_id IN
    SELECT id FROM public.questions
    WHERE lifecycle_state = 'approved'
      AND verified_at IS NULL
      AND created_at < NOW() - (p_days_threshold || ' days')::interval
    LIMIT v_chunk_size
  LOOP
    BEGIN
      PERFORM public.transition_question_state(
        v_question_id,
        'approved'::text,
        'draft'::text,
        'cron_legacy_grandfather_expired'::text,
        NULL,
        NULL,
        format('Auto-degradada por cron tras %s días sin verificar', p_days_threshold)
      );
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      RAISE NOTICE 'Failed transition for %: %', v_question_id, SQLERRM;
    END;
    v_processed := v_processed + 1;
  END LOOP;

  RAISE NOTICE 'lifecycle_grandfather_expire: processed=%, degraded=%, failed=%',
    v_processed, v_count, v_failed;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION lifecycle_grandfather_expire(p_days_threshold integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lifecycle_grandfather_expire(p_days_threshold integer) IS 'Cron: degrada a draft preguntas legacy approved sin verificar tras N días. Decisión #1 del roadmap lifecycle. Procesa hasta 500 por invocación (cron debería llamarla repetidamente). Devuelve número degradadas.';


--
-- Name: log_lifecycle_change_fallback(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_lifecycle_change_fallback() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    BEGIN
      IF OLD.lifecycle_state IS DISTINCT FROM NEW.lifecycle_state THEN
        -- FIX: current_setting(_, true) devuelve NULL si no existe.
        -- NULL <> 'true' = NULL; IF NULL = FALSE en plpgsql → NO loga.
        -- coalesce convierte NULL a '' (string vacío), <> 'true' = TRUE → loga bypass.
        IF coalesce(current_setting('app.lifecycle_via_function', true), '') <> 'true' THEN
          INSERT INTO public.question_lifecycle_history
            (question_id, from_state, to_state, reason_code, notes)
          VALUES
            (NEW.id, OLD.lifecycle_state, NEW.lifecycle_state, 'bypass_detected',
             'WARNING: lifecycle_state changed without transition_question_state() — investigate session/user');
        END IF;
      END IF;
      RETURN NEW;
    END;
    $$;


--
-- Name: FUNCTION log_lifecycle_change_fallback(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.log_lifecycle_change_fallback() IS 'Trigger AFTER UPDATE OF lifecycle_state: red de seguridad anti-bypass. Detecta UPDATEs directos a lifecycle_state que no pasaron por transition_question_state() (que setea session var app.lifecycle_via_function). Loga reason_code=bypass_detected para detección. NO bloquea el UPDATE — solo audita.';


