--
-- Name: FUNCTION log_lifecycle_initial(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.log_lifecycle_initial() IS 'Trigger AFTER INSERT en questions: registra automáticamente la creación de cada pregunta nueva en question_lifecycle_history. Garantiza que toda fila de questions tiene >= 1 entrada en history desde el momento de su INSERT.';


--
-- Name: log_plan_type_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_plan_type_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    -- Solo registrar si plan_type realmente cambió
    IF OLD.plan_type IS DISTINCT FROM NEW.plan_type THEN
      BEGIN
        INSERT INTO plan_type_audit_log (
          user_id,
          user_email,
          old_plan_type,
          new_plan_type,
          changed_at
        ) VALUES (
          NEW.id,
          NEW.email,
          OLD.plan_type,
          NEW.plan_type,
          NOW()
        );
      EXCEPTION WHEN OTHERS THEN
        -- Si falla el audit log, NO bloquear el cambio principal
        -- Solo loguear el error (visible en logs de Supabase)
        RAISE WARNING 'Error logging plan_type change for user %: %', NEW.id, SQLERRM;
      END;
    END IF;

    RETURN NEW;
  END;
  $$;


--
-- Name: mark_article_embedding_stale(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_article_embedding_stale() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    BEGIN
      -- Cuando se modifica question_text, is_active, o primary_article_id
      IF TG_OP = 'UPDATE' THEN
        -- Marcar artículo antiguo si cambió primary_article_id
        IF OLD.primary_article_id IS NOT NULL AND 
           (OLD.primary_article_id != NEW.primary_article_id OR NEW.primary_article_id IS NULL) THEN
          UPDATE articles SET embedding_stale = true WHERE id = OLD.primary_article_id;
        END IF;
        
        -- Marcar artículo nuevo
        IF NEW.primary_article_id IS NOT NULL AND (
          OLD.question_text != NEW.question_text OR
          OLD.is_active != NEW.is_active OR
          OLD.primary_article_id IS DISTINCT FROM NEW.primary_article_id
        ) THEN
          UPDATE articles SET embedding_stale = true WHERE id = NEW.primary_article_id;
        END IF;
      END IF;

      -- Cuando se elimina una pregunta
      IF TG_OP = 'DELETE' AND OLD.primary_article_id IS NOT NULL THEN
        UPDATE articles SET embedding_stale = true WHERE id = OLD.primary_article_id;
      END IF;

      -- Cuando se inserta una pregunta nueva
      IF TG_OP = 'INSERT' AND NEW.primary_article_id IS NOT NULL THEN
        UPDATE articles SET embedding_stale = true WHERE id = NEW.primary_article_id;
      END IF;

      RETURN COALESCE(NEW, OLD);
    END;
    $$;


