-- Name: mark_upgrade_conversion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_upgrade_conversion(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE v_updated INTEGER;
  BEGIN
    UPDATE upgrade_message_impressions SET converted_to_premium = true, converted_at = now()
    WHERE user_id = p_user_id AND converted_to_premium = false AND shown_at > now() - INTERVAL '7 days';
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated;
  END;
  $$;


--
-- Name: match_articles(extensions.vector, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_articles(query_embedding extensions.vector, match_threshold double precision DEFAULT 0.2, match_count integer DEFAULT 10) RETURNS TABLE(id uuid, article_number text, title text, content text, law_id uuid, similarity double precision)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    BEGIN
      RETURN QUERY
      SELECT
        a.id,
        a.article_number,
        a.title,
        a.content,
        a.law_id,
        1 - (a.embedding <=> query_embedding) as similarity
      FROM articles a
      JOIN laws l ON a.law_id = l.id
      WHERE a.is_active = true
        AND a.embedding IS NOT NULL
        AND l.is_active = true
        AND (l.is_derogated IS NULL OR l.is_derogated = false)
        AND 1 - (a.embedding <=> query_embedding) > match_threshold
      ORDER BY a.embedding <=> query_embedding
      LIMIT match_count;
    END;
    $$;


--
-- Name: match_help_articles(extensions.vector, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_help_articles(query_embedding extensions.vector, match_threshold double precision DEFAULT 0.3, match_count integer DEFAULT 3) RETURNS TABLE(id uuid, slug text, title text, category text, content text, keywords text[], related_urls text[], similarity double precision)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
    BEGIN
      RETURN QUERY
      SELECT
        ha.id,
        ha.slug,
        ha.title,
        ha.category,
        ha.content,
        ha.keywords,
        ha.related_urls,
        1 - (ha.embedding <=> query_embedding) AS similarity
      FROM help_articles ha
      WHERE ha.is_published = true
        AND ha.embedding IS NOT NULL
        AND 1 - (ha.embedding <=> query_embedding) > match_threshold
      ORDER BY ha.embedding <=> query_embedding
      LIMIT match_count;
    END;
    $$;


--
-- Name: match_knowledge_base(extensions.vector, double precision, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_knowledge_base(query_embedding extensions.vector, match_threshold double precision DEFAULT 0.7, match_count integer DEFAULT 5, filter_category text DEFAULT NULL::text) RETURNS TABLE(id uuid, category text, title text, content text, short_answer text, metadata jsonb, similarity double precision)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
      BEGIN
        RETURN QUERY
        SELECT
          kb.id,
          kb.category,
          kb.title,
          kb.content,
          kb.short_answer,
          kb.metadata,
          1 - (kb.embedding <=> query_embedding) as similarity
        FROM ai_knowledge_base kb
        WHERE kb.is_active = true
          AND kb.embedding IS NOT NULL
          AND 1 - (kb.embedding <=> query_embedding) > match_threshold
          AND (filter_category IS NULL OR kb.category = filter_category)
        ORDER BY kb.priority DESC, kb.embedding <=> query_embedding
        LIMIT match_count;
      END;
      $$;


--
-- Name: migrate_existing_data(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migrate_existing_data() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    processed_count INTEGER := 0;
BEGIN
    -- Migrar datos agrupando por question_id real (de la tabla questions)
    INSERT INTO user_question_history (
        user_id,
        question_id,
        total_attempts,
        correct_attempts,
        success_rate,
        personal_difficulty,
        first_attempt_at,
        last_attempt_at,
        trend
    )
    SELECT 
        t.user_id,
        tq.question_id,  -- Este question_id debe existir en la tabla 'questions'
        COUNT(*)::INTEGER as total_attempts,
        SUM(CASE WHEN tq.is_correct THEN 1 ELSE 0 END)::INTEGER as correct_attempts,
        ROUND(AVG(CASE WHEN tq.is_correct THEN 1.0 ELSE 0.0 END), 2)::DECIMAL(3,2) as success_rate,
        calculate_personal_difficulty(
            AVG(CASE WHEN tq.is_correct THEN 1.0 ELSE 0.0 END)::NUMERIC,
            COUNT(*)::BIGINT
        ) as personal_difficulty,
        MIN(t.completed_at) as first_attempt_at,
        MAX(t.completed_at) as last_attempt_at,
        'stable'::VARCHAR as trend
    FROM test_questions tq
    JOIN tests t ON t.id = tq.test_id
    WHERE t.is_completed = true
    AND tq.is_correct IS NOT NULL
    AND tq.question_id IS NOT NULL
    AND t.user_id IS NOT NULL
    -- ✅ FILTRO CRÍTICO: Solo question_id que existen en la tabla questions
    AND EXISTS (SELECT 1 FROM questions q WHERE q.id = tq.question_id)
    GROUP BY t.user_id, tq.question_id
    HAVING COUNT(*) >= 1
    ON CONFLICT (user_id, question_id) DO NOTHING;
    
    GET DIAGNOSTICS processed_count = ROW_COUNT;
    RETURN processed_count;
END;
$$;


--
-- Name: FUNCTION migrate_existing_data(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.migrate_existing_data() IS 'Función de migración con validación de FK a tabla questions';


--
-- Name: plazas_otros_turnos_bien_formado(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plazas_otros_turnos_bien_formado(j jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT j IS NULL OR (
    jsonb_typeof(j) = 'array'
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(j) t
       WHERE jsonb_typeof(t) <> 'object'
          -- 'plazas' debe ser un entero de verdad: es lo que el sum() castea y lo que revienta
          OR coalesce(t->>'plazas', '') !~ '^[0-9]+$'
          -- sin turno no se sabe qué se cuenta; sin cita no se prueba nada (misma doctrina que hitos)
          OR coalesce(t->>'turno', '') = ''
          OR coalesce(t->>'cita', '') = ''
    )
  );
$_$;


--
-- Name: FUNCTION plazas_otros_turnos_bien_formado(j jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.plazas_otros_turnos_bien_formado(j jsonb) IS 'Forma exigida a plazas_otros_turnos: array de objetos con plazas entera, turno y cita no vacíos. Existe porque la columna la rellena una persona leyendo boletines y un solo valor mal escrito tumbaba oposiciones_ssot —y con ella la landing entera y el propio auditor.';


--
-- Name: predict_exam_readiness(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.predict_exam_readiness(user_uuid uuid, opos_type text DEFAULT 'auxiliar_administrativo_estado'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  total_tests integer;
  avg_accuracy numeric;
  consistency_score numeric;
  time_efficiency numeric;
  readiness_score numeric;
  prediction_result jsonb;
BEGIN
  -- Métricas básicas del usuario
  SELECT 
    COUNT(DISTINCT t.id),
    AVG(CASE WHEN tq.is_correct THEN 100.0 ELSE 0.0 END),
    1.0 - (STDDEV(CASE WHEN tq.is_correct THEN 100.0 ELSE 0.0 END) / NULLIF(100.0, 0)),
    AVG(60.0 / GREATEST(tq.time_spent_seconds, 1))
  INTO total_tests, avg_accuracy, consistency_score, time_efficiency
  FROM tests t
  JOIN test_questions tq ON t.id = tq.test_id
  WHERE t.user_id = user_uuid AND t.is_completed = true;
  
  -- Calcular puntuación de preparación (algoritmo ponderado)
  readiness_score := (
    COALESCE(avg_accuracy, 0) * 0.5 +
    COALESCE(consistency_score * 100, 0) * 0.3 +
    LEAST(COALESCE(time_efficiency * 20, 0), 100) * 0.2
  );
  
  -- Generar predicción estructurada
  prediction_result := jsonb_build_object(
    'readiness_score', ROUND(readiness_score, 1),
    'readiness_level', CASE
      WHEN readiness_score >= 85 THEN 'excellent'
      WHEN readiness_score >= 75 THEN 'good'
      WHEN readiness_score >= 65 THEN 'fair'
      WHEN readiness_score >= 50 THEN 'needs_work'
      ELSE 'not_ready'
    END,
    'component_scores', jsonb_build_object(
      'accuracy', ROUND(COALESCE(avg_accuracy, 0), 1),
      'consistency', ROUND(COALESCE(consistency_score * 100, 0), 1),
      'time_efficiency', ROUND(COALESCE(time_efficiency * 20, 0), 1)
    ),
    'statistics', jsonb_build_object(
      'total_tests_completed', COALESCE(total_tests, 0)
    ),
    'estimated_weeks_to_ready', CASE
      WHEN readiness_score >= 75 THEN 2
      WHEN readiness_score >= 60 THEN 4
      WHEN readiness_score >= 40 THEN 8
      ELSE 16
    END
  );
  
  RETURN prediction_result;
END;
$$;


--
-- Name: process_unsubscribe_by_token(text, boolean, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_unsubscribe_by_token(token_param text, unsubscribe_all_param boolean DEFAULT false, specific_types_param text[] DEFAULT NULL::text[]) RETURNS TABLE(success boolean, message text, email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  token_info record;
  update_data jsonb := '{}';
BEGIN
  -- Validar token
  SELECT * INTO token_info FROM validate_unsubscribe_token(token_param);
  
  IF token_info.user_id IS NULL THEN
    RETURN QUERY SELECT false, 'Token inválido, expirado o ya usado', ''::text;
    RETURN;
  END IF;
  
  -- Determinar qué actualizar
  IF unsubscribe_all_param THEN
    -- Desactivar todos los emails
    INSERT INTO email_preferences (
      user_id,
      email_reactivacion,
      email_urgente, 
      email_bienvenida_motivacional,
      unsubscribed_all,
      unsubscribed_at,
      updated_at
    ) VALUES (
      token_info.user_id,
      false,
      false,
      false,
      true,
      NOW(),
      NOW()
    )
    ON CONFLICT (user_id) 
    DO UPDATE SET
      email_reactivacion = false,
      email_urgente = false,
      email_bienvenida_motivacional = false,
      unsubscribed_all = true,
      unsubscribed_at = NOW(),
      updated_at = NOW();
  ELSE
    -- Desactivar tipos específicos
    IF 'reactivacion' = ANY(specific_types_param) THEN
      INSERT INTO email_preferences (user_id, email_reactivacion, updated_at)
      VALUES (token_info.user_id, false, NOW())
      ON CONFLICT (user_id) 
      DO UPDATE SET email_reactivacion = false, updated_at = NOW();
    END IF;
    
    IF 'urgente' = ANY(specific_types_param) THEN
      INSERT INTO email_preferences (user_id, email_urgente, updated_at)
      VALUES (token_info.user_id, false, NOW())
      ON CONFLICT (user_id) 
      DO UPDATE SET email_urgente = false, updated_at = NOW();
    END IF;
    
    IF 'bienvenida_motivacional' = ANY(specific_types_param) THEN
      INSERT INTO email_preferences (user_id, email_bienvenida_motivacional, updated_at)
      VALUES (token_info.user_id, false, NOW())
      ON CONFLICT (user_id) 
      DO UPDATE SET email_bienvenida_motivacional = false, updated_at = NOW();
    END IF;
  END IF;
  
  -- Marcar token como usado
  UPDATE email_unsubscribe_tokens 
  SET used_at = NOW()
  WHERE token = token_param;
  
  RETURN QUERY SELECT 
    true, 
    'Preferencias actualizadas correctamente'::text,
    token_info.email;
END;
$$;


--
-- Name: FUNCTION process_unsubscribe_by_token(token_param text, unsubscribe_all_param boolean, specific_types_param text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.process_unsubscribe_by_token(token_param text, unsubscribe_all_param boolean, specific_types_param text[]) IS 'Procesa unsubscribe y actualiza preferencias';


