-- Name: prune_pg_stat_statements_snapshots(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_pg_stat_statements_snapshots(p_keep_days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_deleted integer;
BEGIN
  DELETE FROM public.pg_stat_statements_snapshots
  WHERE snapshot_at < NOW() - (p_keep_days || ' days')::interval;

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$$;


