--
-- Name: record_convocatoria_verification(uuid, text, jsonb, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_convocatoria_verification(p_convocatoria_id uuid, p_verdict text, p_findings jsonb, p_source_url text, p_source_snippet text, p_source_hash text, p_agent_run_id text, p_verified_by text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_hash  text;
  v_state text;
BEGIN
  IF p_verdict NOT IN ('correct','issues','needs_human') THEN
    RAISE EXCEPTION 'verdict inválido: %', p_verdict;
  END IF;
  v_hash := public.compute_convocatoria_hash(p_convocatoria_id);
  v_state := CASE p_verdict
               WHEN 'correct'      THEN 'verified_correct'
               WHEN 'issues'       THEN 'verified_issues'
               WHEN 'needs_human'  THEN 'needs_human'
             END;

  INSERT INTO public.convocatoria_verification AS cv (
    convocatoria_id, state, verified_data_hash, verified_source_hash, source_url,
    source_snippet, verdict, findings, agent_run_id, verified_by, verified_at, updated_at
  ) VALUES (
    p_convocatoria_id, v_state, v_hash, p_source_hash, p_source_url,
    p_source_snippet, p_verdict, p_findings, p_agent_run_id, p_verified_by, now(), now()
  )
  ON CONFLICT (convocatoria_id) DO UPDATE SET
    state = EXCLUDED.state, verified_data_hash = EXCLUDED.verified_data_hash,
    verified_source_hash = EXCLUDED.verified_source_hash, source_url = EXCLUDED.source_url,
    source_snippet = EXCLUDED.source_snippet, verdict = EXCLUDED.verdict,
    findings = EXCLUDED.findings, agent_run_id = EXCLUDED.agent_run_id,
    verified_by = EXCLUDED.verified_by, verified_at = now(), updated_at = now();

  INSERT INTO public.convocatoria_verification_history (
    convocatoria_id, state, data_hash, source_hash, source_url, verdict, findings, agent_run_id, verified_by
  ) VALUES (
    p_convocatoria_id, v_state, v_hash, p_source_hash, p_source_url, p_verdict, p_findings, p_agent_run_id, p_verified_by
  );
END;
$$;


--
-- Name: record_epigrafe_verification(uuid, text, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_epigrafe_verification(p_topic_id uuid, p_verdict text, p_source_convocatoria_id uuid, p_programa_hash text, p_findings jsonb, p_verified_by text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_epi_hash text;
  v_state    text;
BEGIN
  IF p_verdict NOT IN ('literal','drift','provisional','needs_human') THEN
    RAISE EXCEPTION 'verdict inválido: % (literal|drift|provisional|needs_human)', p_verdict;
  END IF;
  v_epi_hash := md5(coalesce((SELECT epigrafe FROM topics WHERE id = p_topic_id), ''));
  v_state := CASE p_verdict
               WHEN 'literal'     THEN 'verified_literal'
               WHEN 'drift'       THEN 'drift_detected'
               WHEN 'provisional' THEN 'provisional_anterior'
               WHEN 'needs_human' THEN 'needs_human'
             END;

  INSERT INTO topic_epigrafe_verification
    (topic_id, state, source_convocatoria_id, verified_epigrafe_hash, verified_programa_hash, findings, verified_by, verified_at, updated_at)
  VALUES
    (p_topic_id, v_state, p_source_convocatoria_id, v_epi_hash, p_programa_hash, p_findings, p_verified_by, now(), now())
  ON CONFLICT (topic_id) DO UPDATE SET
    state=EXCLUDED.state, source_convocatoria_id=EXCLUDED.source_convocatoria_id,
    verified_epigrafe_hash=EXCLUDED.verified_epigrafe_hash, verified_programa_hash=EXCLUDED.verified_programa_hash,
    findings=EXCLUDED.findings, verified_by=EXCLUDED.verified_by, verified_at=now(), updated_at=now();

  INSERT INTO topic_epigrafe_verification_history
    (topic_id, state, source_convocatoria_id, epigrafe_hash, programa_hash, findings, verified_by)
  VALUES (p_topic_id, v_state, p_source_convocatoria_id, v_epi_hash, p_programa_hash, p_findings, p_verified_by);
END;
$$;


--
-- Name: record_law_source_verification(uuid, text, text, text, integer, integer, integer, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_law_source_verification(p_law_id uuid, p_verdict text, p_source_url text, p_source_hash text, p_boe_count integer, p_db_count integer, p_missing integer, p_findings jsonb, p_verified_by text, p_agent_run_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_content_hash text;
  v_state text;
BEGIN
  IF p_verdict NOT IN ('verified','incomplete','issues') THEN
    RAISE EXCEPTION 'verdict inválido: % (verified|incomplete|issues)', p_verdict;
  END IF;
  -- Coherencia: no se puede declarar "verified" con faltantes.
  IF p_verdict = 'verified' AND coalesce(p_missing,0) > 0 THEN
    RAISE EXCEPTION 'verified con % faltantes: usa incomplete', p_missing;
  END IF;
  v_content_hash := compute_law_content_hash(p_law_id);
  v_state := p_verdict;  -- verified|incomplete|issues coinciden con el estado

  INSERT INTO law_source_verification
    (law_id, state, verified_content_hash, verified_source_hash, source_url,
     boe_count, db_count, missing_in_db, verdict, findings, verified_by, agent_run_id, verified_at, updated_at)
  VALUES
    (p_law_id, v_state, v_content_hash, p_source_hash, p_source_url,
     p_boe_count, p_db_count, p_missing, p_verdict, p_findings, p_verified_by, p_agent_run_id, now(), now())
  ON CONFLICT (law_id) DO UPDATE SET
    state=EXCLUDED.state, verified_content_hash=EXCLUDED.verified_content_hash,
    verified_source_hash=EXCLUDED.verified_source_hash, source_url=EXCLUDED.source_url,
    boe_count=EXCLUDED.boe_count, db_count=EXCLUDED.db_count, missing_in_db=EXCLUDED.missing_in_db,
    verdict=EXCLUDED.verdict, findings=EXCLUDED.findings, verified_by=EXCLUDED.verified_by,
    agent_run_id=EXCLUDED.agent_run_id, verified_at=now(), updated_at=now();

  INSERT INTO law_source_verification_history
    (law_id, state, content_hash, source_hash, verdict, findings, verified_by, agent_run_id)
  VALUES (p_law_id, v_state, v_content_hash, p_source_hash, p_verdict, p_findings, p_verified_by, p_agent_run_id);
END;
$$;


--
-- Name: record_shuffle_safety(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_shuffle_safety(p_question_id uuid, p_state text, p_reason text, p_verified_by text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE v_hash text;
BEGIN
  IF p_state NOT IN ('unverified','safe','unsafe','stale') THEN
    RAISE EXCEPTION 'estado shuffle_safety inválido: %', p_state;
  END IF;
  SELECT public.compute_shuffle_safety_hash(
           q.explanation, q.option_a, q.option_b, q.option_c, q.option_d, q.option_e,
           q.shuffle_mode, q.explanation_data::text)
    INTO v_hash FROM public.questions q WHERE q.id = p_question_id;

  UPDATE public.questions
     SET shuffle_safety = p_state,
         shuffle_safety_reason = p_reason,
         shuffle_safety_hash = v_hash,
         shuffle_safety_verified_at = now(),
         shuffle_safety_verified_by = p_verified_by
   WHERE id = p_question_id;

  INSERT INTO public.question_shuffle_safety_history (question_id, state, reason, content_hash, verified_by)
  VALUES (p_question_id, p_state, p_reason, v_hash, p_verified_by);
END$$;


