--
-- Name: refresh_all_theme_performance_cache(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_all_theme_performance_cache() RETURNS TABLE(user_id uuid, topics_cached integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    r RECORD;
    count INTEGER;
  BEGIN
    -- Obtener usuarios que han respondido preguntas en los últimos 90 días
    FOR r IN
      SELECT DISTINCT t.user_id
      FROM tests t
      WHERE t.created_at > NOW() - INTERVAL '90 days'
        AND t.is_completed = true
    LOOP
      count := refresh_user_theme_performance_cache(r.user_id);
      user_id := r.user_id;
      topics_cached := count;
      RETURN NEXT;
    END LOOP;

    RETURN;
  END;
  $$;


--
-- Name: FUNCTION refresh_all_theme_performance_cache(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_all_theme_performance_cache() IS 'Recalcula el caché de rendimiento por tema para todos los usuarios activos (últimos 90 días).';


--
-- Name: refresh_ranking_cache(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_ranking_cache() RETURNS TABLE(filter_name text, rows_inserted integer, duration_ms integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_start timestamptz;
  v_cycle_start timestamptz;
  v_count integer;
  v_today date;
  v_yesterday date;
  v_week_start date;
  v_month_start date;
BEGIN
  v_start := clock_timestamp();
  v_today := (now() AT TIME ZONE 'Europe/Madrid')::date;
  v_yesterday := v_today - 1;
  v_week_start := v_today - (EXTRACT(ISODOW FROM v_today)::int - 1);
  v_month_start := date_trunc('month', v_today)::date;

  -- TODAY
  v_cycle_start := clock_timestamp();
  INSERT INTO ranking_cache (time_filter, user_id, total_questions, correct_answers, accuracy, refreshed_at)
  SELECT 'today', user_id, SUM(total_questions)::int, SUM(correct_answers)::int,
         ROUND(SUM(correct_answers)::numeric / SUM(total_questions) * 100, 0), v_start
  FROM user_daily_stats WHERE day = v_today
    AND user_id NOT IN (SELECT id FROM user_profiles WHERE is_synthetic)
  GROUP BY user_id HAVING SUM(total_questions) > 0
  ON CONFLICT (time_filter, user_id) DO UPDATE SET
    total_questions = EXCLUDED.total_questions, correct_answers = EXCLUDED.correct_answers,
    accuracy = EXCLUDED.accuracy, refreshed_at = EXCLUDED.refreshed_at;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  DELETE FROM ranking_cache WHERE time_filter = 'today' AND refreshed_at < v_start;
  filter_name := 'today'; rows_inserted := v_count;
  duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_cycle_start)) * 1000; RETURN NEXT;

  -- YESTERDAY
  v_cycle_start := clock_timestamp();
  INSERT INTO ranking_cache (time_filter, user_id, total_questions, correct_answers, accuracy, refreshed_at)
  SELECT 'yesterday', user_id, SUM(total_questions)::int, SUM(correct_answers)::int,
         ROUND(SUM(correct_answers)::numeric / SUM(total_questions) * 100, 0), v_start
  FROM user_daily_stats WHERE day = v_yesterday
    AND user_id NOT IN (SELECT id FROM user_profiles WHERE is_synthetic)
  GROUP BY user_id HAVING SUM(total_questions) > 0
  ON CONFLICT (time_filter, user_id) DO UPDATE SET
    total_questions = EXCLUDED.total_questions, correct_answers = EXCLUDED.correct_answers,
    accuracy = EXCLUDED.accuracy, refreshed_at = EXCLUDED.refreshed_at;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  DELETE FROM ranking_cache WHERE time_filter = 'yesterday' AND refreshed_at < v_start;
  filter_name := 'yesterday'; rows_inserted := v_count;
  duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_cycle_start)) * 1000; RETURN NEXT;

  -- WEEK
  v_cycle_start := clock_timestamp();
  INSERT INTO ranking_cache (time_filter, user_id, total_questions, correct_answers, accuracy, refreshed_at)
  SELECT 'week', user_id, SUM(total_questions)::int, SUM(correct_answers)::int,
         ROUND(SUM(correct_answers)::numeric / SUM(total_questions) * 100, 0), v_start
  FROM user_daily_stats WHERE day >= v_week_start
    AND user_id NOT IN (SELECT id FROM user_profiles WHERE is_synthetic)
  GROUP BY user_id HAVING SUM(total_questions) > 0
  ON CONFLICT (time_filter, user_id) DO UPDATE SET
    total_questions = EXCLUDED.total_questions, correct_answers = EXCLUDED.correct_answers,
    accuracy = EXCLUDED.accuracy, refreshed_at = EXCLUDED.refreshed_at;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  DELETE FROM ranking_cache WHERE time_filter = 'week' AND refreshed_at < v_start;
  filter_name := 'week'; rows_inserted := v_count;
  duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_cycle_start)) * 1000; RETURN NEXT;

  -- MONTH
  v_cycle_start := clock_timestamp();
  INSERT INTO ranking_cache (time_filter, user_id, total_questions, correct_answers, accuracy, refreshed_at)
  SELECT 'month', user_id, SUM(total_questions)::int, SUM(correct_answers)::int,
         ROUND(SUM(correct_answers)::numeric / SUM(total_questions) * 100, 0), v_start
  FROM user_daily_stats WHERE day >= v_month_start
    AND user_id NOT IN (SELECT id FROM user_profiles WHERE is_synthetic)
  GROUP BY user_id HAVING SUM(total_questions) > 0
  ON CONFLICT (time_filter, user_id) DO UPDATE SET
    total_questions = EXCLUDED.total_questions, correct_answers = EXCLUDED.correct_answers,
    accuracy = EXCLUDED.accuracy, refreshed_at = EXCLUDED.refreshed_at;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  DELETE FROM ranking_cache WHERE time_filter = 'month' AND refreshed_at < v_start;
  filter_name := 'month'; rows_inserted := v_count;
  duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_cycle_start)) * 1000; RETURN NEXT;

  RETURN;
END;
$$;


--
-- Name: FUNCTION refresh_ranking_cache(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_ranking_cache() IS 'Refresca ranking_cache para los 4 timeFilters. Llamado por cron cada 5min. Devuelve una fila por filtro con stats de la operación.';


--
-- Name: refresh_topic_question_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_topic_question_summary() RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
    DECLARE t0 timestamptz := clock_timestamp(); t1 timestamptz; t2 timestamptz; t3 timestamptz;
    BEGIN
      REFRESH MATERIALIZED VIEW CONCURRENTLY topic_law_question_summary; t1 := clock_timestamp();
      REFRESH MATERIALIZED VIEW CONCURRENTLY topic_official_by_position; t2 := clock_timestamp();
      REFRESH MATERIALIZED VIEW CONCURRENTLY public.law_question_counts; t3 := clock_timestamp();
      RETURN jsonb_build_object('success',true,
        'topic_law_summary_ms', EXTRACT(MILLISECONDS FROM (t1-t0))::int,
        'topic_official_ms',    EXTRACT(MILLISECONDS FROM (t2-t1))::int,
        'law_counts_ms',        EXTRACT(MILLISECONDS FROM (t3-t2))::int,
        'total_ms',             EXTRACT(MILLISECONDS FROM (t3-t0))::int,
        'refreshed_at',         t3);
    END $$;


--
-- Name: FUNCTION refresh_topic_question_summary(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_topic_question_summary() IS 'Refresca las 2 MVs de Fase D-bis Iter 1.5 con REFRESH CONCURRENTLY. Llamada por cron @4am UTC (cron refresh-topic-summary) y por endpoint admin tras edits.';


--
-- Name: refresh_user_theme_performance_cache(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_user_theme_performance_cache(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    rows_affected INTEGER;
  BEGIN
    -- Eliminar datos antiguos del usuario
    DELETE FROM user_theme_performance_cache WHERE user_id = p_user_id;

    -- Insertar datos frescos usando la función existente
    INSERT INTO user_theme_performance_cache (
      user_id, topic_number, topic_title, total_questions,
      correct_answers, accuracy, average_time, last_practiced, calculated_at
    )
    SELECT
      p_user_id,
      topic_number,
      topic_title,
      total_questions::INTEGER,
      correct_answers::INTEGER,
      accuracy,
      average_time,
      last_practiced,
      NOW()
    FROM get_theme_performance_by_scope(p_user_id);

    GET DIAGNOSTICS rows_affected = ROW_COUNT;
    RETURN rows_affected;
  END;
  $$;


--
-- Name: FUNCTION refresh_user_theme_performance_cache(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_user_theme_performance_cache(p_user_id uuid) IS 'Recalcula el caché de rendimiento por tema para un usuario específico.';


--
-- Name: register_device(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_device(p_user_id uuid, p_device_id text, p_device_label text DEFAULT NULL::text, p_hw_fingerprint text DEFAULT NULL::text) RETURNS TABLE(allowed boolean, device_count integer, max_devices integer, is_new_device boolean, is_premium boolean, existing_devices text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    DECLARE
      v_plan_type TEXT;
      v_is_premium BOOLEAN;
      v_max INTEGER;
      v_existing_id UUID;
      v_current_count INTEGER;
      v_is_new BOOLEAN := FALSE;
      v_device_labels TEXT;
      v_fp_match_id UUID;
      -- Cuánto tiene que llevar un aparato sin usarse para dejar de ocupar plaza (04/08/2026).
      v_slot_ttl INTERVAL := INTERVAL '7 days';
    BEGIN
      -- Limpieza: se queda en 30 días A PROPÓSITO. Estas filas son la prueba de qué cuentas
      -- comparten aparato y las leen el barrido de fraude, el cupo compartido del plan gratuito
      -- y el anti-autoreferido, todos con ventana de 30 días. Lo que se acorta es lo que OCUPA
      -- PLAZA (abajo), no lo que se recuerda.
      DELETE FROM user_devices
      WHERE user_id = p_user_id
        AND last_seen_at < NOW() - INTERVAL '30 days';

      -- Obtener plan del usuario
      SELECT up.plan_type INTO v_plan_type
      FROM user_profiles up
      WHERE up.id = p_user_id;

      v_is_premium := COALESCE(v_plan_type, 'free') IN ('premium', 'trial', 'legacy_free', 'premium_semester', 'admin');
      v_max := 2;

      -- PASO 1: ¿Este device_id ya está registrado?
      SELECT ud.id INTO v_existing_id
      FROM user_devices ud
      WHERE ud.user_id = p_user_id AND ud.device_id = p_device_id;

      IF v_existing_id IS NOT NULL THEN
        -- Dispositivo conocido: actualizar last_seen y fingerprint
        UPDATE user_devices
        SET last_seen_at = NOW(),
            device_label = COALESCE(p_device_label, device_label),
            hw_fingerprint = COALESCE(p_hw_fingerprint, hw_fingerprint)
        WHERE id = v_existing_id;
        SELECT COUNT(*)::INTEGER INTO v_current_count
        FROM user_devices WHERE user_id = p_user_id AND last_seen_at >= NOW() - v_slot_ttl;
        RETURN QUERY SELECT TRUE, v_current_count, v_max, FALSE, v_is_premium, ''::TEXT;
        RETURN;
      END IF;

      -- PASO 2: device_id nuevo — ¿hay un dispositivo con mismo fingerprint+label?
      -- Esto detecta localStorage regenerado: mismo hardware, nueva cookie.
      -- Solo si el fingerprint no es null (si no se envió, no deduplicar).
      IF p_hw_fingerprint IS NOT NULL THEN
        SELECT ud.id INTO v_fp_match_id
        FROM user_devices ud
        WHERE ud.user_id = p_user_id
          AND ud.hw_fingerprint = p_hw_fingerprint
          AND ud.device_label = p_device_label
        ORDER BY ud.last_seen_at DESC
        LIMIT 1;

        IF v_fp_match_id IS NOT NULL THEN
          -- Mismo hardware: reemplazar device_id viejo por el nuevo
          UPDATE user_devices
          SET device_id = p_device_id,
              last_seen_at = NOW(),
              device_label = COALESCE(p_device_label, device_label)
          WHERE id = v_fp_match_id;
          SELECT COUNT(*)::INTEGER INTO v_current_count
          FROM user_devices WHERE user_id = p_user_id AND last_seen_at >= NOW() - v_slot_ttl;
          RETURN QUERY SELECT TRUE, v_current_count, v_max, FALSE, v_is_premium, ''::TEXT;
          RETURN;
        END IF;
      END IF;

      -- PASO 3: Dispositivo realmente nuevo — verificar límite contando SOLO los que siguen vivos.
      SELECT COUNT(*)::INTEGER INTO v_current_count
      FROM user_devices WHERE user_id = p_user_id AND last_seen_at >= NOW() - v_slot_ttl;

      IF v_current_count >= v_max THEN
        -- En el mensaje solo se nombran los que de verdad ocupan plaza: enseñar un aparato que ya
        -- no cuenta le diría a alguien que desconecte algo que no le está bloqueando.
        SELECT string_agg(COALESCE(ud.device_label, 'Dispositivo desconocido'), ', ' ORDER BY ud.last_seen_at DESC)
        INTO v_device_labels
        FROM user_devices ud
        WHERE ud.user_id = p_user_id AND ud.last_seen_at >= NOW() - v_slot_ttl;

        RETURN QUERY SELECT FALSE, v_current_count, v_max, TRUE, v_is_premium, COALESCE(v_device_labels, '');
        RETURN;
      END IF;

      -- Registrar nuevo dispositivo
      INSERT INTO user_devices (user_id, device_id, device_label, hw_fingerprint)
      VALUES (p_user_id, p_device_id, p_device_label, p_hw_fingerprint);

      v_current_count := v_current_count + 1;
      v_is_new := TRUE;

      RETURN QUERY SELECT TRUE, v_current_count, v_max, v_is_new, v_is_premium, ''::TEXT;
    END;
    $$;


--
-- Name: reset_question_verification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_question_verification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    IF (
      OLD.question_text IS DISTINCT FROM NEW.question_text OR
      OLD.option_a IS DISTINCT FROM NEW.option_a OR
      OLD.option_b IS DISTINCT FROM NEW.option_b OR
      OLD.option_c IS DISTINCT FROM NEW.option_c OR
      OLD.option_d IS DISTINCT FROM NEW.option_d OR
      OLD.correct_option IS DISTINCT FROM NEW.correct_option OR
      OLD.explanation IS DISTINCT FROM NEW.explanation OR
      OLD.primary_article_id IS DISTINCT FROM NEW.primary_article_id
    ) THEN
      IF (
        OLD.verification_status IS NOT DISTINCT FROM NEW.verification_status AND
        OLD.topic_review_status IS NOT DISTINCT FROM NEW.topic_review_status
      ) THEN
        NEW.verification_status := NULL;
        NEW.topic_review_status := NULL;
        NEW.verified_at := NULL;
      END IF;
    END IF;
    RETURN NEW;
  END;
  $$;


--
-- Name: reset_questions_on_article_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_questions_on_article_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    affected_count INTEGER;
  BEGIN
    IF (
      OLD.content IS DISTINCT FROM NEW.content OR
      OLD.title IS DISTINCT FROM NEW.title OR
      OLD.article_number IS DISTINCT FROM NEW.article_number
    ) THEN
      UPDATE questions
      SET
        verification_status = NULL,
        topic_review_status = NULL,
        verified_at = NULL,
        updated_at = NOW()
      WHERE primary_article_id = NEW.id
        AND (verification_status IS NOT NULL OR topic_review_status IS NOT NULL);

      GET DIAGNOSTICS affected_count = ROW_COUNT;
    END IF;
    RETURN NEW;
  END;
  $$;


--
-- Name: reset_user_stats(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_user_stats(p_user_id uuid, p_requested_by text, p_reason text, p_include_analytics boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_counts    jsonb := '{}'::jsonb;
  v_snapshot  jsonb := '{}'::jsonb;
  v_email     text;
  v_reset_id  uuid;
  v_tbl       text;
  v_n         integer;
  v_rows      jsonb;

  -- ORDEN CRÍTICO (ver cabecera §1): las fuentes ANTES que las derivadas.
  -- test_questions dispara los triggers que decrementan las 5 stats; borrarlas
  -- después limpia cualquier repueblo. Invertir el orden deja stats resucitadas.
  --
  -- test_questions_outbox VA AQUÍ, y no es opcional (bug real, reset de Ja Fe
  -- 16/07): `tg_test_questions_emit_outbox` encola UN EVENTO POR FILA borrada, y
  -- el outbox-processor (backend ECS, asíncrono) los replica DESPUÉS del commit
  -- → reescribe las filas de stats que esta función acababa de borrar. La
  -- transacción no protege de esto: el processor es otro proceso, actúa después.
  -- Purgar los eventos en la MISMA transacción es lo que cierra la carrera (al
  -- commit ya no existen, así que no hay nada que replicar). delete_user_account()
  -- no sufría el bug porque su barrido dinámico se llevaba el outbox de rebote.
  c_source_tables  text[] := ARRAY['test_questions', 'tests', 'test_questions_outbox'];

  c_stats_tables   text[] := ARRAY[
    'user_stats_summary',
    'user_article_stats',      -- el muro rojo: la razón de existir de esta función
    'user_daily_stats',
    'user_difficulty_stats',
    'user_hourly_stats',
    'user_question_history_v2',
    'question_first_attempts',
    'law_question_first_attempts',
    'user_learning_analytics',
    'user_progress',
    'user_streaks'
  ];

  -- Cadáveres del cutover del outbox (tablas reales renombradas, ya no las lee la
  -- app). Se limpian igualmente: si algún día se revirtiera el cutover, las stats
  -- viejas resucitarían y el "empezar de 0" del usuario se desharía solo.
  c_shadow_tables  text[] := ARRAY[
    'user_stats_summary_pre_outbox',
    'user_article_stats_pre_outbox',
    'user_daily_stats_pre_outbox',
    'user_difficulty_stats_pre_outbox',
    'user_hourly_stats_pre_outbox',
    'user_question_history_v2_pre_outbox',
    'question_first_attempts_pre_outbox',
    'law_question_first_attempts_pre_outbox'
  ];

  c_analytics_tables text[] := ARRAY['user_interactions', 'user_sessions'];

  v_all_tables text[];
BEGIN
  -- Guard: el perfil debe existir. Sin esto, un userId inventado devolvería
  -- "todo 0 borrado" y parecería un éxito.
  SELECT email INTO v_email FROM public.user_profiles WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'reset_user_stats: no existe user_profiles con id=%', p_user_id
      USING ERRCODE = 'no_data_found';
  END IF;

  IF coalesce(trim(p_requested_by), '') = '' OR coalesce(trim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'reset_user_stats: requested_by y reason son obligatorios (audit trail)'
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  v_all_tables := c_source_tables || c_stats_tables || c_shadow_tables;
  IF p_include_analytics THEN
    v_all_tables := v_all_tables || c_analytics_tables;
  END IF;

  -- ── Snapshot ANTES de borrar (marcha atrás) ────────────────────────────────
  -- to_jsonb(t.*) preserva la fila entera sin listar columnas → sobrevive a
  -- futuros ALTER TABLE sin mantenimiento.
  FOREACH v_tbl IN ARRAY v_all_tables LOOP
    IF to_regclass('public.' || v_tbl) IS NULL THEN
      CONTINUE;  -- tabla no existe en este entorno (p.ej. shadow ya dropeada)
    END IF;

    EXECUTE format(
      'SELECT coalesce(jsonb_agg(to_jsonb(t.*)), ''[]''::jsonb) FROM public.%I t WHERE t.user_id = $1',
      v_tbl
    ) INTO v_rows USING p_user_id;

    IF jsonb_array_length(v_rows) > 0 THEN
      v_snapshot := v_snapshot || jsonb_build_object(v_tbl, v_rows);
    END IF;
  END LOOP;

  -- ── Borrado, en orden ──────────────────────────────────────────────────────
  FOREACH v_tbl IN ARRAY v_all_tables LOOP
    IF to_regclass('public.' || v_tbl) IS NULL THEN
      CONTINUE;
    END IF;

    EXECUTE format('DELETE FROM public.%I WHERE user_id = $1', v_tbl) USING p_user_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;

    IF v_n > 0 THEN
      v_counts := v_counts || jsonb_build_object(v_tbl, v_n);
    END IF;
  END LOOP;

  -- ── Audit ──────────────────────────────────────────────────────────────────
  INSERT INTO public.user_stats_resets
    (user_id, user_email, requested_by, reason, deleted_counts, snapshot)
  VALUES
    (p_user_id, v_email, p_requested_by, p_reason, v_counts, v_snapshot)
  RETURNING id INTO v_reset_id;

  RETURN v_counts || jsonb_build_object('_reset_id', v_reset_id);
END;
$_$;


--
-- Name: FUNCTION reset_user_stats(p_user_id uuid, p_requested_by text, p_reason text, p_include_analytics boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reset_user_stats(p_user_id uuid, p_requested_by text, p_reason text, p_include_analytics boolean) IS 'Resetea las métricas de estudio de un usuario conservando su cuenta. Atómica, con snapshot en user_stats_resets. Orden test_questions/tests → stats (los triggers repueblan si se invierte).';


--
-- Name: rollover_convocatoria(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rollover_convocatoria(p_oposicion_id uuid, p_nuevo_anio integer, p_estado_proceso text DEFAULT 'sin_oep'::text, p_changed_by text DEFAULT 'rollover'::text) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_old convocatorias%ROWTYPE;
  v_new_id uuid;
BEGIN
  PERFORM set_config('app.actor', p_changed_by, true);

  SELECT * INTO v_old FROM public.convocatorias
   WHERE oposicion_id = p_oposicion_id AND is_current = true;

  IF FOUND AND v_old."año" = p_nuevo_anio THEN
    RAISE EXCEPTION 'La convocatoria vigente de esta oposición YA es del año % — no hay ciclo nuevo que abrir (¿querías un UPDATE normal?)', p_nuevo_anio;
  END IF;

  -- archivar el ciclo saliente (su verdad se conserva INTACTA: nada se sobrescribe)
  IF FOUND THEN
    UPDATE public.convocatorias
       SET is_current = false, archived_at = now()
     WHERE id = v_old.id;
  END IF;

  INSERT INTO public.convocatorias (
    oposicion_id, "año", is_current, estado_proceso,
    programa_url, examen_config, requisitos_especiales, sistema_selectivo
  ) VALUES (
    p_oposicion_id, p_nuevo_anio, true, p_estado_proceso,
    v_old.programa_url, v_old.examen_config, v_old.requisitos_especiales, v_old.sistema_selectivo
  ) RETURNING id INTO v_new_id;

  -- La landing lee oposiciones_ssot = COALESCE(c.campo, o.campo). Si el ciclo nuevo nace vacío y las
  -- columnas LEGACY de `oposiciones` conservan los datos del ciclo viejo, la vista cae al fallback y
  -- SIGUE MOSTRANDO el ciclo anterior (gotcha documentado en rollover-oposiciones.md §2).
  -- Abrir ciclo = dejar de afirmar los hechos del anterior.
  UPDATE public.oposiciones
     SET exam_date = NULL, exam_date_approximate = NULL
   WHERE id = p_oposicion_id;

  RETURN v_new_id;
END;
$$;


--
-- Name: FUNCTION rollover_convocatoria(p_oposicion_id uuid, p_nuevo_anio integer, p_estado_proceso text, p_changed_by text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rollover_convocatoria(p_oposicion_id uuid, p_nuevo_anio integer, p_estado_proceso text, p_changed_by text) IS 'Única vía legítima para abrir un ciclo. Archiva el vigente (is_current=false, archived_at) e INSERTA uno nuevo VACÍO de hechos. Nunca muta la fila viva.';


--
-- Name: search_available_oposiciones(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_available_oposiciones(p_search_term text DEFAULT NULL::text) RETURNS TABLE(id text, nombre text, categoria text, administracion text, tipo text, times_selected integer, created_by text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
      RETURN QUERY
      SELECT
          o.id::TEXT,
          o.nombre,
          o.categoria,
          o.administracion,
          'oficial'::TEXT as tipo,
          0 as times_selected,
          NULL::TEXT as created_by
      FROM oposiciones o
      WHERE (p_search_term IS NULL OR o.nombre ILIKE '%' || p_search_term ||
   '%')

      UNION ALL

      SELECT
          co.id::TEXT,
          co.nombre,
          co.categoria,
          co.administracion,
          'custom'::TEXT as tipo,
          co.times_selected,
          co.created_by_username as created_by
      FROM custom_oposiciones co
      WHERE co.is_public = true
      AND co.is_active = true
      AND (p_search_term IS NULL OR co.nombre ILIKE '%' || p_search_term ||
  '%')

      ORDER BY
          CASE WHEN tipo = 'oficial' THEN 0 ELSE 1 END,
          times_selected DESC NULLS LAST,
          nombre ASC;
  END;
  $$;


--
-- Name: search_convocatorias(text, text, text, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_convocatorias(search_term text, p_categoria text DEFAULT NULL::text, p_tipo text DEFAULT NULL::text, p_ambito text DEFAULT NULL::text, p_ccaa text DEFAULT NULL::text, p_provincia text DEFAULT NULL::text, p_orden text DEFAULT 'recientes'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, boe_id text, boe_fecha date, boe_url_pdf text, boe_url_html text, titulo text, titulo_limpio text, departamento_nombre text, epigrafe text, tipo text, categoria text, num_plazas integer, num_plazas_libre integer, num_plazas_pi integer, oposicion_relacionada text, ambito text, comunidad_autonoma text, provincia text, municipio text, resumen text, acceso text, fecha_limite_inscripcion date, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    search_normalized TEXT;
    total BIGINT;
  BEGIN
    -- Normalizar término de búsqueda
    search_normalized := unaccent(lower(search_term));

    -- Contar total
    SELECT COUNT(*) INTO total
    FROM convocatorias_boe c
    WHERE c.is_active = true
      AND (search_term IS NULL OR search_term = '' OR
           unaccent(lower(c.titulo)) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(c.resumen)) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(c.departamento_nombre)) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(c.cuerpo)) ILIKE '%' || search_normalized || '%')
      AND (p_categoria IS NULL OR c.categoria = p_categoria)
      AND (p_tipo IS NULL OR c.tipo = p_tipo)
      AND (p_ambito IS NULL OR c.ambito = p_ambito)
      AND (p_ccaa IS NULL OR c.comunidad_autonoma = p_ccaa)
      AND (p_provincia IS NULL OR unaccent(lower(c.provincia)) ILIKE unaccent(lower(p_provincia)));

    RETURN QUERY
    SELECT
      c.id,
      c.boe_id,
      c.boe_fecha,
      c.boe_url_pdf,
      c.boe_url_html,
      c.titulo,
      c.titulo_limpio,
      c.departamento_nombre,
      c.epigrafe,
      c.tipo,
      c.categoria,
      c.num_plazas,
      c.num_plazas_libre,
      c.num_plazas_pi,
      c.oposicion_relacionada,
      c.ambito,
      c.comunidad_autonoma,
      c.provincia,
      c.municipio,
      c.resumen,
      c.acceso,
      c.fecha_limite_inscripcion,
      total
    FROM convocatorias_boe c
    WHERE c.is_active = true
      AND (search_term IS NULL OR search_term = '' OR
           unaccent(lower(c.titulo)) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(c.resumen)) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(c.departamento_nombre)) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(c.cuerpo)) ILIKE '%' || search_normalized || '%')
      AND (p_categoria IS NULL OR c.categoria = p_categoria)
      AND (p_tipo IS NULL OR c.tipo = p_tipo)
      AND (p_ambito IS NULL OR c.ambito = p_ambito)
      AND (p_ccaa IS NULL OR c.comunidad_autonoma = p_ccaa)
      AND (p_provincia IS NULL OR unaccent(lower(c.provincia)) ILIKE unaccent(lower(p_provincia)))
    ORDER BY
      CASE WHEN p_orden = 'antiguos' THEN c.boe_fecha END ASC,
      CASE WHEN p_orden = 'plazas' THEN COALESCE(c.num_plazas, 0) END DESC,
      CASE WHEN p_orden = 'recientes' OR p_orden IS NULL THEN c.boe_fecha END DESC,
      c.relevancia_score DESC
    LIMIT p_limit
    OFFSET p_offset;
  END;
  $$;


--
-- Name: search_convocatorias_grouped(text, text, text, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_convocatorias_grouped(search_term text, p_categoria text DEFAULT NULL::text, p_tipo text DEFAULT NULL::text, p_ambito text DEFAULT NULL::text, p_ccaa text DEFAULT NULL::text, p_provincia text DEFAULT NULL::text, p_orden text DEFAULT 'recientes'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, boe_id text, boe_fecha date, boe_url_pdf text, boe_url_html text, titulo text, titulo_limpio text, departamento_nombre text, epigrafe text, tipo text, categoria text, num_plazas integer, num_plazas_libre integer, num_plazas_pi integer, oposicion_relacionada text, ambito text, comunidad_autonoma text, provincia text, municipio text, resumen text, acceso text, fecha_limite_inscripcion date, publicaciones_relacionadas jsonb, total_relacionadas integer, es_standalone boolean, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    search_normalized TEXT;
    v_total BIGINT;  -- Renombrado para evitar conflicto
  BEGIN
    search_normalized := unaccent(lower(COALESCE(search_term, '')));

    SELECT COUNT(*) INTO v_total
    FROM convocatorias_boe c
    WHERE c.is_active = true
      AND c.tipo = 'convocatoria'
      AND (search_term IS NULL OR search_term = '' OR
           unaccent(lower(c.titulo)) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(COALESCE(c.resumen, ''))) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(COALESCE(c.departamento_nombre, ''))) ILIKE '%' || search_normalized || '%' OR
           unaccent(lower(COALESCE(c.cuerpo, ''))) ILIKE '%' || search_normalized || '%')
      AND (p_categoria IS NULL OR c.categoria = p_categoria)
      AND (p_ambito IS NULL OR c.ambito = p_ambito)
      AND (p_ccaa IS NULL OR c.comunidad_autonoma = p_ccaa)
      AND (p_provincia IS NULL OR unaccent(lower(COALESCE(c.provincia, ''))) ILIKE unaccent(lower(p_provincia)));

    RETURN QUERY
    WITH items_principales AS (
      SELECT
        c.*,
        false as is_standalone
      FROM convocatorias_boe c
      WHERE c.is_active = true
        AND c.tipo = 'convocatoria'
        AND (search_term IS NULL OR search_term = '' OR
             unaccent(lower(c.titulo)) ILIKE '%' || search_normalized || '%' OR
             unaccent(lower(COALESCE(c.resumen, ''))) ILIKE '%' || search_normalized || '%' OR
             unaccent(lower(COALESCE(c.departamento_nombre, ''))) ILIKE '%' || search_normalized || '%' OR
             unaccent(lower(COALESCE(c.cuerpo, ''))) ILIKE '%' || search_normalized || '%')
        AND (p_categoria IS NULL OR c.categoria = p_categoria)
        AND (p_ambito IS NULL OR c.ambito = p_ambito)
        AND (p_ccaa IS NULL OR c.comunidad_autonoma = p_ccaa)
        AND (p_provincia IS NULL OR unaccent(lower(COALESCE(c.provincia, ''))) ILIKE unaccent(lower(p_provincia)))
      ORDER BY
        CASE WHEN p_orden = 'antiguos' THEN c.boe_fecha END ASC,
        CASE WHEN p_orden = 'plazas' THEN COALESCE(c.num_plazas, 0) END DESC,
        CASE WHEN p_orden = 'recientes' OR p_orden IS NULL THEN c.boe_fecha END DESC,
        c.relevancia_score DESC
      LIMIT p_limit
      OFFSET p_offset
    ),
    relacionadas AS (
      SELECT
        r.convocatoria_origen_id,
        jsonb_agg(
          jsonb_build_object(
            'id', r.id,
            'boe_id', r.boe_id,
            'boe_fecha', r.boe_fecha,
            'boe_url_html', r.boe_url_html,
            'titulo_limpio', r.titulo_limpio,
            'tipo', r.tipo,
            'resumen', r.resumen
          ) ORDER BY r.boe_fecha DESC
        ) as publicaciones,
        COUNT(*)::INT as total_rel  -- Renombrado
      FROM convocatorias_boe r
      WHERE r.is_active = true
        AND r.convocatoria_origen_id IN (SELECT ip.id FROM items_principales ip)
      GROUP BY r.convocatoria_origen_id
    )
    SELECT
      ip.id,
      ip.boe_id,
      ip.boe_fecha,
      ip.boe_url_pdf,
      ip.boe_url_html,
      ip.titulo,
      ip.titulo_limpio,
      ip.departamento_nombre,
      ip.epigrafe,
      ip.tipo,
      ip.categoria,
      ip.num_plazas,
      ip.num_plazas_libre,
      ip.num_plazas_pi,
      ip.oposicion_relacionada,
      ip.ambito,
      ip.comunidad_autonoma,
      ip.provincia,
      ip.municipio,
      ip.resumen,
      ip.acceso,
      ip.fecha_limite_inscripcion,
      COALESCE(rel.publicaciones, '[]'::jsonb) as publicaciones_relacionadas,
      COALESCE(rel.total_rel, 0) as total_relacionadas,
      ip.is_standalone as es_standalone,
      v_total as total_count
    FROM items_principales ip
    LEFT JOIN relacionadas rel ON rel.convocatoria_origen_id = ip.id
    ORDER BY
      CASE WHEN p_orden = 'antiguos' THEN ip.boe_fecha END ASC,
      CASE WHEN p_orden = 'plazas' THEN COALESCE(ip.num_plazas, 0) END DESC,
      CASE WHEN p_orden = 'recientes' OR p_orden IS NULL THEN ip.boe_fecha END DESC,
      ip.relevancia_score DESC;
  END;
  $$;


--
-- Name: FUNCTION search_convocatorias_grouped(search_term text, p_categoria text, p_tipo text, p_ambito text, p_ccaa text, p_provincia text, p_orden text, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_convocatorias_grouped(search_term text, p_categoria text, p_tipo text, p_ambito text, p_ccaa text, p_provincia text, p_orden text, p_limit integer, p_offset integer) IS 'Busca convocatorias con publicaciones relacionadas agrupadas. Items sin vínculo aparecen sueltos.';


--
-- Name: skip_synthetic_first_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.skip_synthetic_first_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Si el usuario es sintético, NO insertamos la fila → questions.global_difficulty
  -- (que se re-agrega desde question_first_attempts) nunca ve datos de canaries.
  IF EXISTS (SELECT 1 FROM public.user_profiles WHERE id = NEW.user_id AND is_synthetic) THEN
    RETURN NULL;  -- BEFORE INSERT + NULL = fila descartada; el AFTER trigger no dispara.
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_ciudad_to_public(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_ciudad_to_public() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
