  $$;


--
-- Name: sync_nickname_simple(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_nickname_simple() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
