  RETURN NEW;
END;
$$;


--
-- Name: sync_user_oposiciones_seguidas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_user_oposiciones_seguidas() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_new_oposicion_id uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.target_oposicion IS NOT DISTINCT FROM OLD.target_oposicion THEN
    RETURN NEW;
  END IF;

  IF NEW.target_oposicion IS NOT NULL AND NEW.target_oposicion <> '' THEN
    SELECT o.id INTO v_new_oposicion_id FROM public.oposiciones o
     WHERE o.slug = replace(NEW.target_oposicion, '_', '-') LIMIT 1;
  END IF;

  UPDATE public.user_oposiciones_seguidas
     SET rol = 'favorita', updated_at = now()
   WHERE user_id = NEW.id AND rol = 'target'
     AND (v_new_oposicion_id IS NULL OR oposicion_id <> v_new_oposicion_id);

  IF v_new_oposicion_id IS NOT NULL THEN
    INSERT INTO public.user_oposiciones_seguidas (user_id, oposicion_id, rol)
    VALUES (NEW.id, v_new_oposicion_id, 'target')
    ON CONFLICT (user_id, oposicion_id) DO UPDATE SET rol = 'target', updated_at = now();
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- FAIL-OPEN: el cambio de target NO se bloquea por un fallo de bookkeeping.
  BEGIN
    INSERT INTO public.observable_events (source, severity, event_type, user_id, error_message, metadata)
    VALUES ('postgres', 'error', 'seguidas_sync_failed', NEW.id, SQLERRM,
            jsonb_build_object('trigger', 'tg_sync_user_oposiciones_seguidas', 'target_oposicion', NEW.target_oposicion));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RAISE WARNING 'sync_user_oposiciones_seguidas falló user=%: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sync_user_oposiciones_seguidas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_user_oposiciones_seguidas() IS 'Fase 8: mantiene user_oposiciones_seguidas al cambiar user_profiles.target_oposicion (target saliente→favorita, nuevo→target). SECURITY DEFINER para bypasar RLS-lockdown desde el path REST cliente.';


--
-- Name: take_pg_stat_statements_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_pg_stat_statements_snapshot() RETURNS TABLE(snapshot_at timestamp with time zone, rows_inserted integer, duration_ms integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog'
    AS $$
-- Directiva clave: los OUT parameters del RETURNS TABLE(...) (snapshot_at,
-- rows_inserted, duration_ms) colisionarían con columnas homónimas en el
-- INSERT y el RETURN. `use_column` dice a plpgsql: ante ambigüedad prefiere
-- la columna, no la variable. Patrón idiomático cuando los OUT params
-- comparten nombre con columnas — alternativa sería renombrar OUT con
-- prefijo (rompería el contrato con el service TS que lee `snapshot_at`).
#variable_conflict use_column
DECLARE
  v_start timestamptz := clock_timestamp();
  v_snapshot_at timestamptz := date_trunc('minute', NOW());
  v_inserted integer;
BEGIN
  INSERT INTO public.pg_stat_statements_snapshots (
    snapshot_at, queryid, calls,
    total_exec_ms, mean_exec_ms, max_exec_ms, stddev_exec_ms,
    rows, query
  )
  SELECT
    v_snapshot_at,
    pgss.queryid,
    pgss.calls,
    pgss.total_exec_time,
    pgss.mean_exec_time,
    pgss.max_exec_time,
    pgss.stddev_exec_time,
    pgss.rows,
    LEFT(pgss.query, 1000)
  -- Schema explícito `extensions.` por defensa-en-profundidad: si en el
  -- futuro Supabase mueve la extensión a otro schema, este search_path
  -- compatibiliza ambos casos.
  FROM extensions.pg_stat_statements pgss
  WHERE pgss.calls > 10  -- filtrar queries casi-nuevas que no aportan al delta
    AND pgss.queryid IS NOT NULL
  ON CONFLICT (snapshot_at, queryid) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN QUERY SELECT
    v_snapshot_at,
    v_inserted,
    EXTRACT(MILLISECOND FROM (clock_timestamp() - v_start))::integer
      + (EXTRACT(SECOND FROM (clock_timestamp() - v_start))::integer * 1000);
END;
$$;


--
-- Name: FUNCTION take_pg_stat_statements_snapshot(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.take_pg_stat_statements_snapshot() IS 'Inserta snapshot del estado actual de pg_stat_statements (queries con >10 calls). Devuelve (snapshot_at, rows_inserted, duration_ms). Llamada por cron Fargate `pg-stat-snapshot` 1×/día.';


--
-- Name: take_pool_capacity_sample(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_pool_capacity_sample() RETURNS TABLE(sample_at timestamp with time zone, total_conns integer, active_conns integer, idle_in_tx_over_5s integer, hung_clientread_over_10s integer, frontend_active_conns integer, inserted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE
  v_sample_at timestamptz := date_trunc('minute', NOW());
  v_total int;
  v_active int;
  v_idle int;
  v_idle_tx int;
  v_idle_tx_5s int;
  v_long_active_5s int;
  v_hung_cr_10s int;
  v_by_app jsonb;
  v_frontend_active int;
  v_row_count integer;
  v_inserted boolean := false;
BEGIN
  WITH snap AS (
    SELECT
      application_name,
      state,
      wait_event,
      (backend_type = 'client backend') AS is_client_backend,
      EXTRACT(EPOCH FROM (NOW() - query_start))::float AS query_age_s,
      EXTRACT(EPOCH FROM (NOW() - state_change))::float AS state_age_s
    FROM pg_stat_activity
    WHERE datname IS NOT NULL
      AND pid != pg_backend_pid()
  ),
  counts AS (
    SELECT
      COUNT(*)::int AS total_conns,
      COUNT(*) FILTER (WHERE state = 'active')::int AS active_conns,
      COUNT(*) FILTER (WHERE state = 'idle')::int AS idle_conns,
      COUNT(*) FILTER (WHERE state = 'idle in transaction')::int AS idle_tx_conns,
      COUNT(*) FILTER (WHERE is_client_backend AND state = 'idle in transaction' AND state_age_s > 5)::int AS idle_tx_5s,
      COUNT(*) FILTER (WHERE is_client_backend AND state = 'active' AND query_age_s > 5)::int AS long_active_5s,
      COUNT(*) FILTER (WHERE is_client_backend AND wait_event = 'ClientRead' AND state IN ('active', 'idle in transaction') AND state_age_s > 10)::int AS hung_cr_10s,
      -- FIX 02/06/2026: 'postgres-js' → 'postgres.js' (nombre real del cliente).
      COUNT(*) FILTER (WHERE application_name = 'postgres.js' AND state = 'active')::int AS frontend_active
    FROM snap
  ),
  by_app_agg AS (
    SELECT jsonb_object_agg(
      coalesce(application_name, '?') || '/' || coalesce(state, '?'),
      cnt
    ) AS by_app
    FROM (
      SELECT application_name, state, COUNT(*)::int AS cnt
      FROM snap
      GROUP BY application_name, state
    ) s
  )
  SELECT
    c.total_conns, c.active_conns, c.idle_conns, c.idle_tx_conns,
    c.idle_tx_5s, c.long_active_5s, c.hung_cr_10s, c.frontend_active,
    a.by_app
  INTO
    v_total, v_active, v_idle, v_idle_tx,
    v_idle_tx_5s, v_long_active_5s, v_hung_cr_10s, v_frontend_active,
    v_by_app
  FROM counts c, by_app_agg a;

  INSERT INTO public.pool_capacity_samples (
    sample_at, total_conns, active_conns, idle_conns, idle_in_tx_conns,
    idle_in_tx_over_5s, long_active_over_5s, hung_clientread_over_10s,
    by_app, frontend_active_conns
  ) VALUES (
    v_sample_at, v_total, v_active, v_idle, v_idle_tx,
    v_idle_tx_5s, v_long_active_5s, v_hung_cr_10s,
    v_by_app, v_frontend_active
  )
  ON CONFLICT (sample_at) DO NOTHING;

  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  v_inserted := (v_row_count > 0);

  RETURN QUERY SELECT
    v_sample_at,
    v_total, v_active, v_idle_tx_5s, v_hung_cr_10s, v_frontend_active,
    v_inserted;
END;
$$;


--
-- Name: FUNCTION take_pool_capacity_sample(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.take_pool_capacity_sample() IS 'Inserta una muestra del estado actual del pool en pool_capacity_samples (truncado al minuto, idempotente). Devuelve los counts capturados + flag inserted. Llamada por cron Fargate `pool-capacity-sampler` 1×/min.';


