--
-- Name: test_complete_flow(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.test_complete_flow(p_user_id uuid, p_accuracy numeric) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_message_id UUID;
    v_message_variants JSONB;
    v_emoji TEXT;
    v_variants_count INTEGER;
    v_random_index INTEGER;
    v_message_variant TEXT;
    v_result TEXT := '';
  BEGIN
    SELECT mm.id, mm.message_variants, mm.emoji
    INTO v_message_id, v_message_variants, v_emoji
    FROM motivational_messages mm
    WHERE mm.is_active = true
      AND mm.category = 'exam_result'
      AND mm.gender_target = 'neutral'
      AND (mm.min_accuracy IS NULL OR p_accuracy >= mm.min_accuracy)
      AND (mm.max_accuracy IS NULL OR p_accuracy <= mm.max_accuracy)
    ORDER BY mm.priority DESC, RANDOM()
    LIMIT 1;

    v_result := 'Step 1: Message selected' || E'\n';
    v_result := v_result || '  ID: ' || v_message_id::text || E'\n';
    v_result := v_result || '  Variants NULL?: ' || (v_message_variants IS
  NULL)::text || E'\n';
    v_result := v_result || '  Variants: ' || v_message_variants::text ||
  E'\n';
    v_result := v_result || E'\n';

    v_result := v_result || 'Step 2: Calculating variant count' || E'\n';
    v_variants_count := jsonb_array_length(v_message_variants);
    v_result := v_result || '  Count: ' || v_variants_count::text || E'\n';
    v_result := v_result || E'\n';

    v_result := v_result || 'Step 3: Random index' || E'\n';
    v_random_index := floor(random() * v_variants_count)::int;
    v_result := v_result || '  Index: ' || v_random_index::text || E'\n';
    v_result := v_result || E'\n';

    v_result := v_result || 'Step 4: Extracting variant with ->> operator'
  || E'\n';
    v_message_variant := v_message_variants->>v_random_index;
    v_result := v_result || '  Variant NULL?: ' || (v_message_variant IS
  NULL)::text || E'\n';
    v_result := v_result || '  Variant: ' || COALESCE(v_message_variant,
  'NULL!!!') || E'\n';
    v_result := v_result || '  Type: ' || pg_typeof(v_message_variant)::text
   || E'\n';
    v_result := v_result || E'\n';

    v_result := v_result || 'Step 5: Replacing placeholders' || E'\n';
    v_message_variant := REPLACE(v_message_variant, '{nombre}', 'Manuel');
    v_result := v_result || '  Final: ' || COALESCE(v_message_variant,
  'NULL!!!') || E'\n';

    RETURN v_result;
  END;
  $$;


--
-- Name: test_full_select_with_joins(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.test_full_select_with_joins(p_user_id uuid, p_accuracy numeric) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_message_id UUID;
    v_message_variants JSONB;
    v_emoji TEXT;
    v_tone TEXT;
    v_color_scheme TEXT;
    v_total_likes INTEGER;
    v_like_rate NUMERIC;
    v_times_shown INTEGER;
    v_has_loved BOOLEAN;
    v_total_dislikes INTEGER;
    v_result TEXT := '';
  BEGIN
    SELECT
      mm.id,
      mm.message_variants,
      mm.emoji,
      mm.tone,
      mm.color_scheme,
      mm.total_likes,
      mm.like_rate,
      COALESCE(user_views.view_count, 0),
      COALESCE(user_reactions.has_love, false),
      COALESCE(total_dislikes.dislike_count, 0)
    INTO
      v_message_id,
      v_message_variants,
      v_emoji,
      v_tone,
      v_color_scheme,
      v_total_likes,
      v_like_rate,
      v_times_shown,
      v_has_loved,
      v_total_dislikes
    FROM motivational_messages mm

    LEFT JOIN (
      SELECT umi_view.message_id, COUNT(*) as view_count
      FROM user_message_interactions umi_view
      WHERE umi_view.user_id = p_user_id AND umi_view.action_type = 'view'
      GROUP BY umi_view.message_id
    ) user_views ON user_views.message_id = mm.id

    LEFT JOIN (
      SELECT umi_react.message_id, true as has_love
      FROM user_message_interactions umi_react
      WHERE umi_react.user_id = p_user_id AND umi_react.action_type IN
  ('love', 'like', 'funny')
    ) user_reactions ON user_reactions.message_id = mm.id

    LEFT JOIN (
      SELECT umi_dislike3.message_id, COUNT(*) as dislike_count
      FROM user_message_interactions umi_dislike3
      WHERE umi_dislike3.action_type = 'dislike'
      GROUP BY umi_dislike3.message_id
    ) total_dislikes ON total_dislikes.message_id = mm.id

    WHERE mm.is_active = true
      AND mm.category = 'exam_result'
      AND mm.gender_target = 'neutral'
      AND (mm.min_accuracy IS NULL OR p_accuracy >= mm.min_accuracy)
      AND (mm.max_accuracy IS NULL OR p_accuracy <= mm.max_accuracy)

    ORDER BY mm.priority DESC, RANDOM()
    LIMIT 1;

    v_result := 'Message ID: ' || COALESCE(v_message_id::text, 'NULL') ||
  E'\n';
    v_result := v_result || 'Variants is NULL: ' || (v_message_variants IS
  NULL)::text || E'\n';
    v_result := v_result || 'Variants type: ' ||
  pg_typeof(v_message_variants)::text || E'\n';
    v_result := v_result || 'Variants: ' ||
  COALESCE(v_message_variants::text, 'NULL') || E'\n';
    v_result := v_result || 'Emoji: ' || COALESCE(v_emoji, 'NULL') || E'\n';

    RETURN v_result;
  END;
  $$;


--
-- Name: test_into_variables(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.test_into_variables() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_id UUID;
    v_variants JSONB;
    v_result TEXT := '';
  BEGIN
    SELECT id, message_variants
    INTO v_id, v_variants
    FROM motivational_messages
    WHERE category = 'exam_result' AND subcategory = 'low'
    LIMIT 1;

    v_result := 'ID: ' || v_id::text || E'\n';
    v_result := v_result || 'Variants is NULL: ' || (v_variants IS
  NULL)::text || E'\n';
    v_result := v_result || 'Variants: ' || COALESCE(v_variants::text,
  'NULL') || E'\n';

    RETURN v_result;
  END;
  $$;


--
-- Name: test_variant_extraction(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.test_variant_extraction(p_user_id uuid, p_accuracy numeric) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_selected_message RECORD;
    v_message_variant TEXT;
    v_variants_count INTEGER;
    v_random_index INTEGER;
    v_result TEXT := '';
  BEGIN
    v_result := v_result || 'Step 1: Selecting message...' || E'\n';

    SELECT
      mm.id,
      mm.subcategory,
      mm.message_variants,
      mm.min_accuracy,
      mm.max_accuracy
    INTO v_selected_message
    FROM motivational_messages mm
    WHERE mm.is_active = true
      AND mm.category = 'exam_result'
      AND mm.gender_target = 'neutral'
      AND (mm.min_accuracy IS NULL OR p_accuracy >= mm.min_accuracy)
      AND (mm.max_accuracy IS NULL OR p_accuracy <= mm.max_accuracy)
    ORDER BY mm.priority DESC, RANDOM()
    LIMIT 1;

    IF v_selected_message IS NULL THEN
      v_result := v_result || 'ERROR: No message found!' || E'\n';
      RETURN v_result;
    END IF;

    v_result := v_result || 'Message ID: ' || v_selected_message.id::text ||
   E'\n';
    v_result := v_result || 'Subcategory: ' ||
  v_selected_message.subcategory || E'\n';
    v_result := v_result || 'Min/Max accuracy: ' ||
  COALESCE(v_selected_message.min_accuracy::text, 'null') || ' / ' ||
  COALESCE(v_selected_message.max_accuracy::text, 'null') || E'\n';
    v_result := v_result || 'Variants type: ' ||
  pg_typeof(v_selected_message.message_variants)::text || E'\n';
    v_result := v_result || 'Variants JSON: ' ||
  v_selected_message.message_variants::text || E'\n';

    v_variants_count :=
  jsonb_array_length(v_selected_message.message_variants);
    v_result := v_result || 'Variants count: ' || v_variants_count::text ||
  E'\n';

    v_random_index := floor(random() * v_variants_count)::int;
    v_result := v_result || 'Random index: ' || v_random_index::text ||
  E'\n';

    v_result := v_result || E'\nStep 2: Extracting variant with ->>...' ||
  E'\n';
    v_message_variant :=
  v_selected_message.message_variants->>v_random_index;

    v_result := v_result || 'Variant extracted: ' ||
  COALESCE(v_message_variant, 'NULL!!!') || E'\n';
    v_result := v_result || 'Variant type: ' ||
  pg_typeof(v_message_variant)::text || E'\n';
    v_result := v_result || 'Variant length: ' ||
  COALESCE(length(v_message_variant)::text, 'null') || E'\n';

    RETURN v_result;
  END;
  $$;


