--
-- Name: tg_test_autoadd_favorita(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_test_autoadd_favorita() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_oposicion_id uuid;
BEGIN
  IF NEW.user_id IS NULL OR NEW.position_type IS NULL OR NEW.position_type = '' THEN
    RETURN NEW;
  END IF;
  SELECT id INTO v_oposicion_id FROM public.oposiciones
   WHERE slug = replace(NEW.position_type, '_', '-') LIMIT 1;
  IF v_oposicion_id IS NOT NULL THEN
    INSERT INTO public.user_oposiciones_seguidas (user_id, oposicion_id, rol)
    VALUES (NEW.user_id, v_oposicion_id, 'favorita')
    ON CONFLICT (user_id, oposicion_id) DO NOTHING;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Observabilidad propia (anidada: ni esto puede romper el INSERT de test).
  BEGIN
    INSERT INTO public.observable_events (source, severity, event_type, user_id, error_message, metadata)
    VALUES ('postgres', 'warn', 'seguidas_autoadd_failed', NEW.user_id, SQLERRM,
            jsonb_build_object('trigger', 'tg_test_autoadd_favorita', 'position_type', NEW.position_type));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RAISE WARNING 'tg_test_autoadd_favorita falló user=% position_type=%: %', NEW.user_id, NEW.position_type, SQLERRM;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tg_test_autoadd_favorita(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_test_autoadd_favorita() IS 'Fase 8: al crear un test, añade su oposición (position_type→slug) como favorita. EXCEPTION-SAFE: nunca rompe el INSERT de tests.';


--
-- Name: tg_test_questions_emit_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_test_questions_emit_outbox() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- BORRADO RGPD EN CURSO: no se emite nada para las filas de ESE usuario. La marca la pone
  -- `delete_user_account()` y es local a su transacción; el evento que se dejaría de emitir lo
  -- borraría esa misma transacción unas líneas más abajo. Ver la cabecera de esta migración.
  IF TG_OP = 'DELETE'
     AND current_setting('app.deleting_user', true) IS NOT NULL
     AND current_setting('app.deleting_user', true) = OLD.user_id::text THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.test_questions_outbox
      (test_question_id, event_type, payload, user_id)
    VALUES
      (NEW.id, 'INSERT', to_jsonb(NEW), NEW.user_id);
    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.test_questions_outbox
      (test_question_id, event_type, payload, old_payload, user_id)
    VALUES
      (NEW.id, 'UPDATE', to_jsonb(NEW), to_jsonb(OLD), NEW.user_id);
    RETURN NEW;

  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.test_questions_outbox
      (test_question_id, event_type, payload, old_payload, user_id)
    VALUES
      (OLD.id, 'DELETE', to_jsonb(OLD), to_jsonb(OLD), OLD.user_id);
    RETURN OLD;

  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION tg_test_questions_emit_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_test_questions_emit_outbox() IS 'Emite el evento de outbox por fila. Se calla durante un borrado RGPD (marca de transacción app.deleting_user = user_id): esos eventos los borraba la propia transacción del borrado sin que nadie los leyera, y costaban 38 s de los 111 s que hacían imposible borrar la cuenta de un usuario activo (T-215).';


