--
-- Name: tg_topics_gate_incomplete_laws(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_topics_gate_incomplete_laws() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE bad text;
BEGIN
  IF NEW.disponible IS TRUE
     AND (TG_OP = 'INSERT' OR OLD.disponible IS DISTINCT FROM TRUE) THEN
    SELECT string_agg(DISTINCT e.short_name || ' (' || e.effective_state || ')', ', ')
      INTO bad
    FROM topic_scope ts
    JOIN law_verification_effective e ON e.law_id = ts.law_id
    WHERE ts.topic_id = NEW.id
      AND e.effective_state IN ('incomplete', 'false_green', 'no_source');
    IF bad IS NOT NULL THEN
      RAISE EXCEPTION
        'No se puede publicar el tema % (id %): ley(es) del scope sin verificar/sin fuente oficial: %',
        NEW.topic_number, NEW.id, bad
        USING HINT = 'verifica/registra la fuente (verify-law-source.cjs) o exime (no_consolidated_text) las leyes del scope antes de publicar el tema — docs/runbooks/completitud-leyes.md';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_verificacion_cosmetica_no_firma(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_verificacion_cosmetica_no_firma() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cosmetico boolean;
BEGIN
  v_cosmetico := COALESCE(NEW.explanation, '') ~* '(revisi[oó]n masiva|explicaci[oó]n reescrita|reescrita al formato|fase2 relink|v2\.1 relink|needs_review v2\.1|formato did[aá]ctico)';

  IF v_cosmetico AND (NEW.article_ok IS TRUE OR NEW.answer_ok IS TRUE) THEN
    BEGIN
      INSERT INTO observable_events (id, ts, source, severity, event_type, metadata, created_at)
      VALUES (gen_random_uuid(), NOW(), 'db:ai_verification_results', 'warn',
              'verificacion_cosmetica_firmaba_fondo',
              jsonb_build_object(
                'questionId', NEW.question_id,
                'aiModel', NEW.ai_model,
                'articleOk', NEW.article_ok,
                'answerOk', NEW.answer_ok,
                'proposito', left(COALESCE(NEW.explanation, ''), 120)),
              NOW());
    EXCEPTION WHEN OTHERS THEN
      -- La traza no puede tumbar la escritura: fail-open, igual que el resto de telemetría.
      NULL;
    END;

    NEW.article_ok := NULL;
    NEW.answer_ok  := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION tg_verificacion_cosmetica_no_firma(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_verificacion_cosmetica_no_firma() IS 'T-465: un pase con propósito cosmético (reescribir/reformatear/re-vincular) no puede afirmar article_ok/answer_ok. Se ponen a NULL («no lo he mirado») y se emite verificacion_cosmetica_firmaba_fondo.';


--
-- Name: topic_question_difficulty_bucket(numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.topic_question_difficulty_bucket(global_diff numeric, base_diff text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN global_diff IS NOT NULL AND global_diff < 25 THEN 'easy'
    WHEN global_diff IS NOT NULL AND global_diff < 50 THEN 'medium'
    WHEN global_diff IS NOT NULL AND global_diff < 75 THEN 'hard'
    WHEN global_diff IS NOT NULL THEN 'extreme'
    WHEN base_diff IN ('easy','medium','hard','extreme','auto') THEN base_diff
    ELSE 'auto'
  END
$$;


