--
-- Name: track_conversion_event(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_conversion_event(p_user_id uuid, p_event_type text, p_event_data jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_days_since INTEGER;
    v_registration_source TEXT;
    v_plan_type TEXT;
    v_user_created_at TIMESTAMP WITH TIME ZONE;
    v_event_id UUID;
    v_today DATE;
    v_existing_event UUID;
  BEGIN
    -- Para limit_reached, verificar si ya existe uno hoy
    IF p_event_type = 'limit_reached' THEN
      v_today := (NOW() AT TIME ZONE 'Europe/Madrid')::DATE;

      SELECT id INTO v_existing_event
      FROM conversion_events
      WHERE user_id = p_user_id
        AND event_type = 'limit_reached'
        AND (created_at AT TIME ZONE 'Europe/Madrid')::DATE = v_today
      LIMIT 1;

      IF v_existing_event IS NOT NULL THEN
        RETURN v_existing_event;
      END IF;
    END IF;

    -- Obtener info del usuario
    SELECT
      up.registration_source,
      up.plan_type,
      up.created_at
    INTO v_registration_source, v_plan_type, v_user_created_at
    FROM user_profiles up
    WHERE up.id = p_user_id;

    -- Calcular dias desde registro
    IF v_user_created_at IS NOT NULL THEN
      v_days_since := EXTRACT(DAY FROM (NOW() - v_user_created_at))::INTEGER;
    ELSE
      v_days_since := 0;
    END IF;

    -- Insertar evento
    INSERT INTO conversion_events (
      user_id,
      event_type,
      event_data,
      days_since_registration,
      registration_source,
      plan_type
    ) VALUES (
      p_user_id,
      p_event_type,
      p_event_data,
      v_days_since,
      v_registration_source,
      v_plan_type
    )
    RETURNING id INTO v_event_id;

    RETURN v_event_id;
  END;
  $$;


--
-- Name: track_question_first_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_question_first_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_is_first_attempt BOOLEAN;
BEGIN
  -- Skip si psychometric o question_id null
  IF NEW.psychometric_question_id IS NOT NULL THEN RETURN NEW; END IF;
  IF NEW.question_id IS NULL THEN RETURN NEW; END IF;

  -- Resolver user_id desde tests (si NEW.user_id no está set)
  SELECT user_id INTO v_user_id FROM public.tests WHERE id = NEW.test_id;
  IF v_user_id IS NULL THEN RETURN NEW; END IF;

  -- Verificar primer intento (PK lookup, rápido con índice)
  SELECT NOT EXISTS (
    SELECT 1 FROM public.question_first_attempts
    WHERE user_id = v_user_id AND question_id = NEW.question_id
  ) INTO v_is_first_attempt;

  IF v_is_first_attempt THEN
    -- INSERT atómico. Dispara apply_first_attempt_to_question_stats_trigger
    -- que recalcula global_difficulty inmediato. Ver
    -- supabase/migrations/20260517_global_difficulty_robust_trigger.sql.
    INSERT INTO public.question_first_attempts (
      user_id, question_id, is_correct, time_spent_seconds, confidence_level, created_at
    ) VALUES (
      v_user_id, NEW.question_id, NEW.is_correct, NEW.time_spent_seconds,
      NEW.confidence_level, NOW()
    )
    ON CONFLICT (user_id, question_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


