--
-- Name: update_global_psychometric_difficulty(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_global_psychometric_difficulty(question_uuid uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    new_difficulty NUMERIC;
    sample_size INTEGER;
  BEGIN
    -- Calcular nueva dificultad
    new_difficulty := calculate_global_psychometric_difficulty(question_uuid);

    -- Obtener tamaño de muestra
    SELECT COUNT(*) INTO sample_size
    FROM psychometric_first_attempts
    WHERE question_id = question_uuid;

    -- Actualizar pregunta
    UPDATE psychometric_questions
    SET
      global_difficulty = new_difficulty,
      difficulty_sample_size = sample_size,
      last_difficulty_update = NOW()
    WHERE id = question_uuid;

    -- Log para debugging
    RAISE NOTICE 'Updated question % difficulty to % (sample size: %)',
      question_uuid, new_difficulty, sample_size;
  END;
  $$;


--
-- Name: update_message_analytics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_message_analytics() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    IF NEW.action_type = 'view' THEN
      UPDATE motivational_messages
      SET
        total_views = total_views + 1,
        like_rate = CASE WHEN total_views + 1 > 0 THEN (total_likes::numeric
   / (total_views + 1)) * 100 ELSE 0 END,
        share_rate = CASE WHEN total_views + 1 > 0 THEN
  (total_shares::numeric / (total_views + 1)) * 100 ELSE 0 END
      WHERE id = NEW.message_id;

    ELSIF NEW.action_type = 'like' THEN
      UPDATE motivational_messages
      SET
        total_likes = total_likes + 1,
        like_rate = CASE WHEN total_views > 0 THEN ((total_likes +
  1)::numeric / total_views) * 100 ELSE 0 END
      WHERE id = NEW.message_id;

    ELSIF NEW.action_type = 'unlike' THEN
      UPDATE motivational_messages
      SET
        total_likes = GREATEST(0, total_likes - 1),
        like_rate = CASE WHEN total_views > 0 THEN (GREATEST(0, total_likes
  - 1)::numeric / total_views) * 100 ELSE 0 END
      WHERE id = NEW.message_id;

    ELSIF NEW.action_type = 'share' THEN
      UPDATE motivational_messages
      SET
        total_shares = total_shares + 1,
        share_rate = CASE WHEN total_views > 0 THEN ((total_shares +
  1)::numeric / total_views) * 100 ELSE 0 END
      WHERE id = NEW.message_id;
    END IF;

    RETURN NEW;
  END;
  $$;


