--
-- Name: update_public_user_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_public_user_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  BEGIN
    -- Actualizar avatar si cambió en user_metadata
    UPDATE public_user_profiles
    SET
      avatar_type = CASE
        WHEN NEW.raw_user_meta_data->>'avatar_type' = 'predefined' THEN
  'predefined'
        WHEN NEW.raw_user_meta_data->>'avatar_type' = 'uploaded' THEN 'uploaded'
        WHEN NEW.raw_user_meta_data->>'avatar_url' IS NOT NULL
          OR NEW.raw_user_meta_data->>'picture' IS NOT NULL THEN 'google'
        ELSE avatar_type
      END,
      avatar_emoji = COALESCE(NEW.raw_user_meta_data->>'avatar_emoji',
  avatar_emoji),
      avatar_color = COALESCE(NEW.raw_user_meta_data->>'avatar_color',
  avatar_color),
      avatar_url = COALESCE(
        NEW.raw_user_meta_data->>'avatar_url',
        NEW.raw_user_meta_data->>'picture',
        avatar_url
      ),
      updated_at = NOW()
    WHERE id = NEW.id;

    RETURN NEW;
  END;
  $$;


--
-- Name: update_question_difficulty_immediate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_question_difficulty_immediate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- NO-OP. Antes marcaba stats_dirty=true para que el cron
  -- recalc-question-difficulty recalculara `difficulty` desde
  -- test_questions agregando todas las respuestas (incluido retests,
  -- lo que sesgaba el valor). Ese cron fue apagado el 2026-05-17:
  -- el campo `difficulty` queda como categoría inicial de importación
  -- ('medium' por default), sirviendo de fallback estático cuando la
  -- pregunta no tiene primer intento todavía. Con primer intento,
  -- `global_difficulty_category` (mantenido por
  -- apply_first_attempt_to_question_stats_trigger) tiene prioridad.
  RETURN NEW;
END;
$$;


