--
-- Name: update_user_daily_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_daily_stats() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_day DATE;
  v_q_delta INT := 0;
  v_c_delta INT := 0;
  v_t_delta BIGINT := 0;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id; END IF;
    v_day := (NEW.created_at AT TIME ZONE 'Europe/Madrid')::DATE;
    v_q_delta := 1;
    v_c_delta := CASE WHEN NEW.is_correct THEN 1 ELSE 0 END;
    v_t_delta := COALESCE(NEW.time_spent_seconds, 0);
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.is_correct IS NOT DISTINCT FROM OLD.is_correct
       AND COALESCE(NEW.time_spent_seconds, 0) = COALESCE(OLD.time_spent_seconds, 0) THEN
      RETURN NEW;
    END IF;
    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id; END IF;
    v_day := (NEW.created_at AT TIME ZONE 'Europe/Madrid')::DATE;
    IF NEW.is_correct IS TRUE AND (OLD.is_correct IS NULL OR OLD.is_correct IS FALSE) THEN
      v_c_delta := 1;
    ELSIF OLD.is_correct IS TRUE AND (NEW.is_correct IS NULL OR NEW.is_correct IS FALSE) THEN
      v_c_delta := -1;
    END IF;
    v_t_delta := COALESCE(NEW.time_spent_seconds, 0) - COALESCE(OLD.time_spent_seconds, 0);
  ELSIF TG_OP = 'DELETE' THEN
    v_user_id := OLD.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = OLD.test_id; END IF;
    v_day := (OLD.created_at AT TIME ZONE 'Europe/Madrid')::DATE;
    v_q_delta := -1;
    v_c_delta := CASE WHEN OLD.is_correct THEN -1 ELSE 0 END;
    v_t_delta := -COALESCE(OLD.time_spent_seconds, 0);
  END IF;

  IF v_user_id IS NULL OR v_day IS NULL THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- Guard: ver explicación en TRIGGER 1.
  IF NOT EXISTS (SELECT 1 FROM user_profiles WHERE id = v_user_id) THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  INSERT INTO user_daily_stats (user_id, day, total_questions, correct_answers, total_time_seconds)
  VALUES (v_user_id, v_day, GREATEST(0, v_q_delta), GREATEST(0, v_c_delta), GREATEST(0, v_t_delta))
  ON CONFLICT (user_id, day) DO UPDATE SET
    total_questions = GREATEST(0, user_daily_stats.total_questions + v_q_delta),
    correct_answers = GREATEST(0, user_daily_stats.correct_answers + v_c_delta),
    total_time_seconds = GREATEST(0, user_daily_stats.total_time_seconds + v_t_delta),
    updated_at = NOW();

  RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: update_user_difficulty_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_difficulty_stats() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_difficulty TEXT;
  v_q_delta INT := 0;
  v_c_delta INT := 0;
  v_t_delta BIGINT := 0;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.difficulty IS NULL THEN RETURN NEW; END IF;
    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id; END IF;
    v_difficulty := NEW.difficulty;
    v_q_delta := 1;
    v_c_delta := CASE WHEN NEW.is_correct THEN 1 ELSE 0 END;
    v_t_delta := COALESCE(NEW.time_spent_seconds, 0);
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.difficulty IS NULL THEN RETURN NEW; END IF;
    IF NEW.is_correct IS NOT DISTINCT FROM OLD.is_correct THEN RETURN NEW; END IF;
    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id; END IF;
    v_difficulty := NEW.difficulty;
    IF NEW.is_correct IS TRUE AND (OLD.is_correct IS NULL OR OLD.is_correct IS FALSE) THEN
      v_c_delta := 1;
    ELSIF OLD.is_correct IS TRUE AND (NEW.is_correct IS NULL OR NEW.is_correct IS FALSE) THEN
      v_c_delta := -1;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.difficulty IS NULL THEN RETURN OLD; END IF;
    v_user_id := OLD.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = OLD.test_id; END IF;
    v_difficulty := OLD.difficulty;
    v_q_delta := -1;
    v_c_delta := CASE WHEN OLD.is_correct THEN -1 ELSE 0 END;
    v_t_delta := -COALESCE(OLD.time_spent_seconds, 0);
  END IF;

  IF v_user_id IS NULL THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF v_difficulty NOT IN ('easy', 'medium', 'hard', 'extreme') THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- Guard: ver explicación en TRIGGER 1.
  IF NOT EXISTS (SELECT 1 FROM user_profiles WHERE id = v_user_id) THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  INSERT INTO user_difficulty_stats (user_id, difficulty, total_questions, correct_answers, total_time_seconds)
  VALUES (v_user_id, v_difficulty, GREATEST(0, v_q_delta), GREATEST(0, v_c_delta), GREATEST(0, v_t_delta))
  ON CONFLICT (user_id, difficulty) DO UPDATE SET
    total_questions = GREATEST(0, user_difficulty_stats.total_questions + v_q_delta),
    correct_answers = GREATEST(0, user_difficulty_stats.correct_answers + v_c_delta),
    total_time_seconds = GREATEST(0, user_difficulty_stats.total_time_seconds + v_t_delta),
    updated_at = NOW();

  RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: update_user_hourly_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_hourly_stats() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_hour SMALLINT;
  v_q_delta INT := 0;
  v_c_delta INT := 0;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id; END IF;
    v_hour := EXTRACT(HOUR FROM NEW.created_at AT TIME ZONE 'Europe/Madrid')::SMALLINT;
    v_q_delta := 1;
    v_c_delta := CASE WHEN NEW.is_correct THEN 1 ELSE 0 END;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.is_correct IS NOT DISTINCT FROM OLD.is_correct THEN RETURN NEW; END IF;
    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id; END IF;
    v_hour := EXTRACT(HOUR FROM NEW.created_at AT TIME ZONE 'Europe/Madrid')::SMALLINT;
    IF NEW.is_correct IS TRUE AND (OLD.is_correct IS NULL OR OLD.is_correct IS FALSE) THEN
      v_c_delta := 1;
    ELSIF OLD.is_correct IS TRUE AND (NEW.is_correct IS NULL OR NEW.is_correct IS FALSE) THEN
      v_c_delta := -1;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_user_id := OLD.user_id;
    IF v_user_id IS NULL THEN SELECT user_id INTO v_user_id FROM tests WHERE id = OLD.test_id; END IF;
    v_hour := EXTRACT(HOUR FROM OLD.created_at AT TIME ZONE 'Europe/Madrid')::SMALLINT;
    v_q_delta := -1;
    v_c_delta := CASE WHEN OLD.is_correct THEN -1 ELSE 0 END;
  END IF;

  IF v_user_id IS NULL OR v_hour IS NULL THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- Guard: ver explicación en TRIGGER 1.
  IF NOT EXISTS (SELECT 1 FROM user_profiles WHERE id = v_user_id) THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  INSERT INTO user_hourly_stats (user_id, hour, total_questions, correct_answers)
  VALUES (v_user_id, v_hour, GREATEST(0, v_q_delta), GREATEST(0, v_c_delta))
  ON CONFLICT (user_id, hour) DO UPDATE SET
    total_questions = GREATEST(0, user_hourly_stats.total_questions + v_q_delta),
    correct_answers = GREATEST(0, user_hourly_stats.correct_answers + v_c_delta),
    updated_at = NOW();

  RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: update_user_learning_analytics(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_learning_analytics(user_uuid uuid, article_uuid uuid, tema_num integer, opos_type text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    total_attempts integer;
    correct_attempts integer;
    accuracy numeric;
    avg_time numeric;
    learning_style_detected text;
    mastery_level_calculated text;
    exam_readiness numeric;
  BEGIN
    -- Calcular métricas actuales
    SELECT
      COUNT(*) as total,
      COUNT(*) FILTER (WHERE is_correct = true) as correct,
      AVG(time_spent_seconds)
    INTO total_attempts, correct_attempts, avg_time
    FROM test_questions tq
    JOIN tests t ON tq.test_id = t.id
    WHERE t.user_id = user_uuid
      AND (article_uuid IS NULL OR tq.article_id = article_uuid);

    -- Calcular accuracy
    IF total_attempts > 0 THEN
      accuracy := (correct_attempts * 100.0 / total_attempts);
    ELSE
      accuracy := 0;
    END IF;

    -- Detectar estilo de aprendizaje
    learning_style_detected := detect_learning_style(user_uuid);

    -- Calcular nivel de maestría
    CASE
      WHEN accuracy >= 85 AND total_attempts >= 20 THEN mastery_level_calculated := 'expert';
      WHEN accuracy >= 75 AND total_attempts >= 15 THEN mastery_level_calculated := 'advanced';
      WHEN accuracy >= 60 AND total_attempts >= 10 THEN mastery_level_calculated := 'intermediate';
      ELSE mastery_level_calculated := 'beginner';
    END CASE;

    -- Calcular preparación para examen
    exam_readiness := LEAST(100, (accuracy * 0.7) + (LEAST(total_attempts, 50) * 0.6));

    -- Upsert del registro de analytics
    INSERT INTO user_learning_analytics (
      user_id, article_id, tema_number, oposicion_type,
      total_questions_answered, overall_accuracy,
      learning_style, mastery_level, predicted_exam_readiness,
      last_analysis_date, data_points_count
    ) VALUES (
      user_uuid, article_uuid, tema_num, opos_type,
      total_attempts, accuracy,
      learning_style_detected, mastery_level_calculated, exam_readiness,
      now(), total_attempts
    )
    ON CONFLICT (user_id, article_id, oposicion_type) DO UPDATE SET
      total_questions_answered = EXCLUDED.total_questions_answered,
      overall_accuracy = EXCLUDED.overall_accuracy,
      learning_style = EXCLUDED.learning_style,
      mastery_level = EXCLUDED.mastery_level,
      predicted_exam_readiness = EXCLUDED.predicted_exam_readiness,
      last_analysis_date = EXCLUDED.last_analysis_date,
      data_points_count = EXCLUDED.data_points_count;

  END;
  $$;


--
-- Name: update_user_notification_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_notification_metrics() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Actualizar métricas cuando se inserta un nuevo evento
    IF TG_TABLE_NAME = 'notification_events' THEN
        INSERT INTO user_notification_metrics (user_id) 
        VALUES (NEW.user_id)
        ON CONFLICT (user_id) DO UPDATE SET
            push_notifications_sent = CASE 
                WHEN NEW.event_type = 'notification_sent' THEN user_notification_metrics.push_notifications_sent + 1
                ELSE user_notification_metrics.push_notifications_sent
            END,
            push_notifications_clicked = CASE
                WHEN NEW.event_type = 'notification_clicked' THEN user_notification_metrics.push_notifications_clicked + 1
                ELSE user_notification_metrics.push_notifications_clicked
            END,
            push_notifications_dismissed = CASE
                WHEN NEW.event_type = 'notification_dismissed' THEN user_notification_metrics.push_notifications_dismissed + 1
                ELSE user_notification_metrics.push_notifications_dismissed
            END,
            last_push_interaction = CASE
                WHEN NEW.event_type IN ('notification_clicked', 'notification_dismissed') THEN NEW.created_at
                ELSE user_notification_metrics.last_push_interaction
            END,
            updated_at = NOW();
            
    ELSIF TG_TABLE_NAME = 'email_events' THEN
        INSERT INTO user_notification_metrics (user_id)
        VALUES (NEW.user_id)
        ON CONFLICT (user_id) DO UPDATE SET
            emails_sent = CASE
                WHEN NEW.event_type = 'sent' THEN user_notification_metrics.emails_sent + 1
                ELSE user_notification_metrics.emails_sent
            END,
            emails_delivered = CASE
                WHEN NEW.event_type = 'delivered' THEN user_notification_metrics.emails_delivered + 1
                ELSE user_notification_metrics.emails_delivered
            END,
            emails_opened = CASE
                WHEN NEW.event_type = 'opened' THEN user_notification_metrics.emails_opened + 1
                ELSE user_notification_metrics.emails_opened
            END,
            emails_clicked = CASE
                WHEN NEW.event_type = 'clicked' THEN user_notification_metrics.emails_clicked + 1
                ELSE user_notification_metrics.emails_clicked
            END,
            last_email_opened = CASE
                WHEN NEW.event_type = 'opened' THEN NEW.created_at
                ELSE user_notification_metrics.last_email_opened
            END,
            last_email_clicked = CASE
                WHEN NEW.event_type = 'clicked' THEN NEW.created_at
                ELSE user_notification_metrics.last_email_clicked
            END,
            updated_at = NOW();
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: update_user_question_history_v2_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_question_history_v2_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_correct_delta INT;
BEGIN
  IF NEW.is_correct IS NULL OR NEW.question_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_user_id := NEW.user_id;
  IF v_user_id IS NULL THEN
    SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
  END IF;
  IF v_user_id IS NULL THEN RETURN NEW; END IF;

  IF NOT EXISTS (SELECT 1 FROM questions WHERE id = NEW.question_id) THEN
    RETURN NEW;
  END IF;

  v_correct_delta := CASE WHEN NEW.is_correct THEN 1 ELSE 0 END;

  INSERT INTO user_question_history_v2 (
    user_id, question_id,
    total_attempts, correct_attempts,
    success_rate,
    first_attempt_at, last_attempt_at, trend
  )
  VALUES (
    v_user_id, NEW.question_id,
    1, v_correct_delta,
    ROUND(v_correct_delta::numeric, 2)::DECIMAL(3,2),
    NEW.created_at, NEW.created_at, 'stable'
  )
  ON CONFLICT (user_id, question_id) DO UPDATE SET
    total_attempts = user_question_history_v2.total_attempts + 1,
    correct_attempts = user_question_history_v2.correct_attempts + EXCLUDED.correct_attempts,
    success_rate = ROUND(
      (user_question_history_v2.correct_attempts + EXCLUDED.correct_attempts)::numeric
      / (user_question_history_v2.total_attempts + 1),
      2
    )::DECIMAL(3,2),
    last_attempt_at = EXCLUDED.last_attempt_at,
    updated_at = NOW();

  RETURN NEW;
END;
$$;


--
-- Name: update_user_question_history_v2_on_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_question_history_v2_on_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_correct_delta INT := 0;
BEGIN
  IF NEW.is_correct IS NOT DISTINCT FROM OLD.is_correct THEN
    RETURN NEW;
  END IF;
  IF NEW.question_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_user_id := NEW.user_id;
  IF v_user_id IS NULL THEN
    SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
  END IF;
  IF v_user_id IS NULL THEN RETURN NEW; END IF;

  -- Casuística:
  --  OLD=null  NEW=true  → +1 (la respuesta llegó después del INSERT, no estaba contada)
  --  OLD=null  NEW=false → 0 (ya no se cuenta porque INSERT con null ya saltó)
  --  OLD=false NEW=true  → +1 (cambio respuesta)
  --  OLD=true  NEW=false → -1
  --  OLD=true  NEW=null  → -1
  --  OLD=false NEW=null  → 0
  IF NEW.is_correct IS TRUE AND (OLD.is_correct IS NULL OR OLD.is_correct IS FALSE) THEN
    v_correct_delta := 1;
  ELSIF OLD.is_correct IS TRUE AND (NEW.is_correct IS NULL OR NEW.is_correct IS FALSE) THEN
    v_correct_delta := -1;
  END IF;

  -- IMPORTANTE: NO incrementa total_attempts. Solo ajusta correctos.
  UPDATE user_question_history_v2
  SET correct_attempts = GREATEST(0, correct_attempts + v_correct_delta),
      success_rate = ROUND(
        CASE WHEN total_attempts = 0 THEN 0
             ELSE GREATEST(0, correct_attempts + v_correct_delta)::numeric / total_attempts END,
        2
      )::DECIMAL(3,2),
      last_attempt_at = COALESCE(NEW.updated_at, NEW.created_at),
      updated_at = NOW()
  WHERE user_id = v_user_id AND question_id = NEW.question_id;

  RETURN NEW;
END;
$$;


--
-- Name: update_user_roles_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_roles_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: update_user_stats_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_stats_summary() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    DECLARE
      v_user_id UUID;
      v_current_week_start DATE := date_trunc('week', now())::date;
    BEGIN
      -- Obtener user_id del test (1 lookup por PK, instantáneo)
      SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
      IF v_user_id IS NULL THEN RETURN NEW; END IF;

      -- Upsert: si la fila existe, incrementar; si no, crear
      INSERT INTO user_stats_summary (user_id, total_questions, correct_answers, blank_answers, questions_this_week, week_start)
      VALUES (
        v_user_id,
        1,
        CASE WHEN NEW.is_correct THEN 1 ELSE 0 END,
        CASE WHEN NEW.was_blank THEN 1 ELSE 0 END,
        1,
        v_current_week_start
      )
      ON CONFLICT (user_id) DO UPDATE SET
        total_questions = user_stats_summary.total_questions + 1,
        correct_answers = user_stats_summary.correct_answers + CASE WHEN NEW.is_correct THEN 1 ELSE 0 END,
        blank_answers = user_stats_summary.blank_answers + CASE WHEN NEW.was_blank THEN 1 ELSE 0 END,
        questions_this_week = CASE
          WHEN user_stats_summary.week_start = v_current_week_start
          THEN user_stats_summary.questions_this_week + 1
          ELSE 1  -- nueva semana, resetear
        END,
        week_start = v_current_week_start,
        updated_at = now();

      RETURN NEW;
    END;
    $$;


--
-- Name: update_user_stats_summary_on_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_stats_summary_on_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_was_this_week BOOLEAN;
BEGIN
  SELECT user_id INTO v_user_id FROM tests WHERE id = OLD.test_id;
  IF v_user_id IS NULL THEN RETURN OLD; END IF;

  v_was_this_week := date_trunc('week', OLD.created_at)::date = date_trunc('week', now())::date;

  UPDATE user_stats_summary
  SET total_questions = GREATEST(0, total_questions - 1),
      correct_answers = GREATEST(0, correct_answers - CASE WHEN OLD.is_correct THEN 1 ELSE 0 END),
      blank_answers = GREATEST(0, blank_answers - CASE WHEN OLD.was_blank THEN 1 ELSE 0 END),
      questions_this_week = CASE
        WHEN v_was_this_week THEN GREATEST(0, questions_this_week - 1)
        ELSE questions_this_week
      END,
      updated_at = now()
  WHERE user_id = v_user_id;

  RETURN OLD;
END;
$$;


--
-- Name: update_user_stats_summary_on_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_stats_summary_on_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_correct_delta INT := 0;
  v_blank_delta INT := 0;
BEGIN
  -- Solo actuar si cambia algo relevante
  IF NEW.is_correct IS NOT DISTINCT FROM OLD.is_correct
     AND NEW.was_blank IS NOT DISTINCT FROM OLD.was_blank THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
  IF v_user_id IS NULL THEN RETURN NEW; END IF;

  -- Calcular delta para is_correct
  IF NEW.is_correct AND NOT OLD.is_correct THEN v_correct_delta := 1;
  ELSIF NOT NEW.is_correct AND OLD.is_correct THEN v_correct_delta := -1;
  END IF;

  -- Calcular delta para was_blank
  IF NEW.was_blank AND NOT OLD.was_blank THEN v_blank_delta := 1;
  ELSIF NOT NEW.was_blank AND OLD.was_blank THEN v_blank_delta := -1;
  END IF;

  UPDATE user_stats_summary
  SET correct_answers = GREATEST(0, correct_answers + v_correct_delta),
      blank_answers = GREATEST(0, blank_answers + v_blank_delta),
      updated_at = now()
  WHERE user_id = v_user_id;

  RETURN NEW;
END;
$$;


--
-- Name: update_user_stats_total_tests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_stats_total_tests() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_delta INT;
BEGIN
  IF NEW.is_completed IS TRUE AND (OLD.is_completed IS NULL OR OLD.is_completed IS FALSE) THEN
    v_delta := 1;
  ELSIF OLD.is_completed IS TRUE AND (NEW.is_completed IS NULL OR NEW.is_completed IS FALSE) THEN
    v_delta := -1;
  ELSE
    RETURN NEW;
  END IF;

  -- Guard: si user_profiles ya no existe (mid-cascade DELETE RGPD),
  -- no recrear filas — la cascada de user_stats_summary ya las borró.
  IF NOT EXISTS (SELECT 1 FROM user_profiles WHERE id = NEW.user_id) THEN
    RETURN NEW;
  END IF;

  UPDATE user_stats_summary
  SET total_tests = GREATEST(0, total_tests + v_delta),
      updated_at = NOW()
  WHERE user_id = NEW.user_id;

  RETURN NEW;
END;
$$;


--
-- Name: update_user_stats_total_time(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_stats_total_time() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_delta BIGINT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_delta := COALESCE(NEW.time_spent_seconds, 0);
    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN
      SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    v_delta := COALESCE(NEW.time_spent_seconds, 0) - COALESCE(OLD.time_spent_seconds, 0);
    IF v_delta = 0 THEN RETURN NEW; END IF;
    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN
      SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_delta := -COALESCE(OLD.time_spent_seconds, 0);
    v_user_id := OLD.user_id;
    IF v_user_id IS NULL THEN
      SELECT user_id INTO v_user_id FROM tests WHERE id = OLD.test_id;
    END IF;
  END IF;

  IF v_user_id IS NULL THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF v_delta = 0 THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- Guard: ver explicación en TRIGGER 1.
  IF NOT EXISTS (SELECT 1 FROM user_profiles WHERE id = v_user_id) THEN
    RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  UPDATE user_stats_summary
  SET total_time_seconds = GREATEST(0, total_time_seconds + v_delta),
      updated_at = NOW()
  WHERE user_id = v_user_id;

  RETURN CASE TG_OP WHEN 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: update_user_streak_function(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_streak_function() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    DECLARE
      v_user_id UUID;
      v_new_streak INTEGER;
      v_today DATE;
      v_last_activity DATE;
    BEGIN
      SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
      IF v_user_id IS NULL THEN RETURN NEW; END IF;

      v_today := (NOW() AT TIME ZONE 'Europe/Madrid')::DATE;

      -- GUARD: solo recalcular si no hay actividad hoy todavía
      -- Esto evita recalcular la racha en cada pregunta (50 preguntas = 50 recálculos)
      -- Solo recalcula en la PRIMERA pregunta del día
      SELECT last_activity_date INTO v_last_activity
      FROM user_streaks WHERE user_id = v_user_id;

      IF v_last_activity IS NOT NULL AND v_last_activity >= v_today THEN
        -- Ya se calculó hoy, solo actualizar timestamp
        RETURN NEW;
      END IF;

      v_new_streak := calculate_user_streak(v_user_id);

      INSERT INTO user_streaks (user_id, current_streak, longest_streak, last_activity_date, streak_updated_at)
      VALUES (v_user_id, v_new_streak, v_new_streak, v_today, NOW())
      ON CONFLICT (user_id) DO UPDATE SET
        current_streak = v_new_streak,
        longest_streak = GREATEST(user_streaks.longest_streak, v_new_streak),
        last_activity_date = v_today,
        streak_updated_at = NOW();

      RETURN NEW;
    END;
    $$;


--
-- Name: update_user_theme_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_theme_stats() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id        UUID;
  v_position_type  TEXT;
  v_old_user_id    UUID;
  v_old_position   TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.tema_number IS NULL THEN
      RETURN NEW;
    END IF;

    v_user_id := NEW.user_id;
    IF v_user_id IS NULL THEN
      SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
    END IF;
    SELECT position_type INTO v_position_type FROM tests WHERE id = NEW.test_id;

    IF v_user_id IS NULL OR v_position_type IS NULL THEN
      RETURN NEW;
    END IF;

    INSERT INTO user_theme_stats (
      user_id, position_type, tema_number, total, correct, last_study, updated_at
    ) VALUES (
      v_user_id, v_position_type, NEW.tema_number,
      1, CASE WHEN NEW.is_correct THEN 1 ELSE 0 END,
      NEW.created_at, NOW()
    )
    ON CONFLICT (user_id, position_type, tema_number) DO UPDATE SET
      total      = user_theme_stats.total + 1,
      correct    = user_theme_stats.correct + CASE WHEN NEW.is_correct THEN 1 ELSE 0 END,
      last_study = GREATEST(user_theme_stats.last_study, NEW.created_at),
      updated_at = NOW();

    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    -- Caso A: cambia tema_number → decrementar fila vieja, incrementar nueva.
    IF NEW.tema_number IS DISTINCT FROM OLD.tema_number THEN
      v_user_id := COALESCE(NEW.user_id, OLD.user_id);
      IF v_user_id IS NULL THEN
        SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
      END IF;
      SELECT position_type INTO v_position_type FROM tests WHERE id = NEW.test_id;

      IF v_user_id IS NULL OR v_position_type IS NULL THEN
        RETURN NEW;
      END IF;

      -- Decrementar fila vieja (si el viejo tema_number no era null)
      IF OLD.tema_number IS NOT NULL THEN
        UPDATE user_theme_stats SET
          total      = GREATEST(0, total - 1),
          correct    = GREATEST(0, correct - CASE WHEN OLD.is_correct THEN 1 ELSE 0 END),
          updated_at = NOW()
        WHERE user_id = v_user_id
          AND position_type = v_position_type
          AND tema_number = OLD.tema_number;
      END IF;

      -- Incrementar fila nueva (si el nuevo tema_number no es null)
      IF NEW.tema_number IS NOT NULL THEN
        INSERT INTO user_theme_stats (
          user_id, position_type, tema_number, total, correct, last_study, updated_at
        ) VALUES (
          v_user_id, v_position_type, NEW.tema_number,
          1, CASE WHEN NEW.is_correct THEN 1 ELSE 0 END,
          NEW.created_at, NOW()
        )
        ON CONFLICT (user_id, position_type, tema_number) DO UPDATE SET
          total      = user_theme_stats.total + 1,
          correct    = user_theme_stats.correct + CASE WHEN NEW.is_correct THEN 1 ELSE 0 END,
          last_study = GREATEST(user_theme_stats.last_study, NEW.created_at),
          updated_at = NOW();
      END IF;

      RETURN NEW;
    END IF;

    -- Caso B: solo cambia is_correct → ajustar correct delta.
    IF NEW.is_correct IS DISTINCT FROM OLD.is_correct AND NEW.tema_number IS NOT NULL THEN
      v_user_id := COALESCE(NEW.user_id, OLD.user_id);
      IF v_user_id IS NULL THEN
        SELECT user_id INTO v_user_id FROM tests WHERE id = NEW.test_id;
      END IF;
      SELECT position_type INTO v_position_type FROM tests WHERE id = NEW.test_id;

      IF v_user_id IS NULL OR v_position_type IS NULL THEN
        RETURN NEW;
      END IF;

      UPDATE user_theme_stats SET
        correct = GREATEST(0, correct
          + CASE WHEN NEW.is_correct THEN 1 ELSE 0 END
          - CASE WHEN OLD.is_correct THEN 1 ELSE 0 END),
        updated_at = NOW()
      WHERE user_id = v_user_id
        AND position_type = v_position_type
        AND tema_number = NEW.tema_number;
    END IF;

    RETURN NEW;

  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.tema_number IS NULL THEN
      RETURN OLD;
    END IF;

    v_user_id := OLD.user_id;
    IF v_user_id IS NULL THEN
      SELECT user_id INTO v_user_id FROM tests WHERE id = OLD.test_id;
    END IF;
    SELECT position_type INTO v_position_type FROM tests WHERE id = OLD.test_id;

    IF v_user_id IS NULL OR v_position_type IS NULL THEN
      RETURN OLD;
    END IF;

    -- Nota: last_study no se recalcula en DELETE (requeriría SELECT MAX
    -- sobre el resto de filas del mismo tema). Acepta drift mínimo —
    -- el cron diario de Fase 2 lo detecta y corrige si supera 5%.
    UPDATE user_theme_stats SET
      total      = GREATEST(0, total - 1),
      correct    = GREATEST(0, correct - CASE WHEN OLD.is_correct THEN 1 ELSE 0 END),
      updated_at = NOW()
    WHERE user_id = v_user_id
      AND position_type = v_position_type
      AND tema_number = OLD.tema_number;

    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: user_has_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_role(p_user_id uuid, p_role text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 
    FROM user_roles 
    WHERE user_id = p_user_id 
      AND role = p_role 
      AND is_active = true
      AND (expires_at IS NULL OR expires_at > now())
  );
END;
$$;


--
-- Name: user_needs_onboarding(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_needs_onboarding(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  DECLARE
    v_profile RECORD;
  BEGIN
    SELECT
      target_oposicion,
      onboarding_completed_at,
      age,
      gender,
      daily_study_hours,
      ciudad
    INTO v_profile
    FROM user_profiles
    WHERE user_id = p_user_id;

    -- Si no existe perfil, necesita onboarding
    IF NOT FOUND THEN
      RETURN TRUE;
    END IF;

    -- Necesita onboarding si falta algún campo obligatorio
    IF v_profile.target_oposicion IS NULL
       OR v_profile.onboarding_completed_at IS NULL
       OR v_profile.age IS NULL
       OR v_profile.gender IS NULL
       OR v_profile.daily_study_hours IS NULL
       OR v_profile.ciudad IS NULL THEN
      RETURN TRUE;
    END IF;

    RETURN FALSE;

  EXCEPTION
    WHEN OTHERS THEN
      -- En caso de error, asumir que no necesita para no molestar
      RETURN FALSE;
  END;
  $$;


--
-- Name: validate_unsubscribe_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_unsubscribe_token(token_param text) RETURNS TABLE(user_id uuid, email text, email_type text, full_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    eut.user_id,
    eut.email,
    eut.email_type,
    up.full_name
  FROM email_unsubscribe_tokens eut
  LEFT JOIN user_profiles up ON eut.user_id = up.id
  WHERE eut.token = token_param
    AND eut.used_at IS NULL
    AND eut.expires_at > NOW();
END;
$$;


--
-- Name: FUNCTION validate_unsubscribe_token(token_param text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.validate_unsubscribe_token(token_param text) IS 'Valida token y retorna información del usuario';


--
-- Name: verify_triggers_working(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_triggers_working() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  verification_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'timestamp', now(),
    'triggers_active', jsonb_build_object(
      'calculate_retention_score', (
        SELECT count(*) FROM pg_trigger 
        WHERE tgname = 'calculate_retention_score_trigger'
      ) > 0,
      'update_user_analytics', (
        SELECT count(*) FROM pg_trigger 
        WHERE tgname = 'update_user_analytics_on_test_completion'
      ) > 0,
      'update_article_stats', (
        SELECT count(*) FROM pg_trigger 
        WHERE tgname = 'update_article_stats_trigger'
      ) > 0,
      'update_timestamps', (
        SELECT count(*) FROM pg_trigger 
        WHERE tgname LIKE 'update_timestamp_trigger_%'
      ) >= 3,
      'cleanup_old_sessions', (
        SELECT count(*) FROM pg_trigger 
        WHERE tgname = 'cleanup_old_sessions_trigger'
      ) > 0
    ),
    'functions_available', jsonb_build_object(
      'calculate_knowledge_retention_score', (
        SELECT to_regproc('calculate_knowledge_retention_score(integer, boolean, text)') IS NOT NULL
      ),
      'detect_learning_style', (
        SELECT to_regproc('detect_learning_style(uuid)') IS NOT NULL
      ),
      'update_user_learning_analytics', (
        SELECT to_regproc('update_user_learning_analytics(uuid, uuid, integer, text)') IS NOT NULL
      ),
      'get_complete_test_analytics', (
        SELECT to_regproc('get_complete_test_analytics(uuid)') IS NOT NULL
      ),
      'predict_exam_readiness', (
        SELECT to_regproc('predict_exam_readiness(uuid, text)') IS NOT NULL
      )
    ),
    'status', 'success'
  ) INTO verification_result;
  
  RETURN verification_result;
END;
$$;


