CREATE TABLE public.articles (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    law_id uuid,
    article_number text NOT NULL,
    title text,
    content text,
    section text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    title_number text,
    chapter_number text,
    section_number text,
    is_active boolean DEFAULT true,
    content_hash text,
    last_modification_date date,
    verification_date date DEFAULT CURRENT_DATE,
    is_verified boolean DEFAULT false,
    embedding extensions.vector(1536),
    embedding_stale boolean DEFAULT false,
    content_tsv tsvector,
    teoria_content_tsv tsvector,
    vigencia_notes jsonb
)
WITH (autovacuum_vacuum_insert_scale_factor='0.01', autovacuum_vacuum_insert_threshold='1000');


