    first_attempts_correct_sum integer DEFAULT 0 NOT NULL,
    first_attempts_time_sum bigint DEFAULT 0 NOT NULL,
    first_attempts_confidence_sum numeric(12,2) DEFAULT 0 NOT NULL,
