    CONSTRAINT questions_question_type_check CHECK ((question_type = ANY (ARRAY['single'::text, 'multiple'::text, 'true_false'::text]))),
    CONSTRAINT questions_shuffle_mode_check CHECK ((shuffle_mode = ANY (ARRAY['full'::text, 'anchor_last'::text, 'no_shuffle'::text]))),
    CONSTRAINT questions_shuffle_safety_check CHECK ((shuffle_safety = ANY (ARRAY['unverified'::text, 'safe'::text, 'unsafe'::text, 'stale'::text])))
)
WITH (autovacuum_vacuum_threshold='100', autovacuum_analyze_scale_factor='0.05', autovacuum_analyze_threshold='100', autovacuum_vacuum_insert_scale_factor='0.01', autovacuum_vacuum_insert_threshold='1000', autovacuum_vacuum_scale_factor='0.02');


