--
-- Name: admin_disputes_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_disputes_dashboard WITH (security_invoker='on') AS
 SELECT qd.id,
    qd.dispute_type,
    qd.description,
    qd.status,
    qd.created_at,
    up.full_name AS reporter_name,
    q.question_text,
    a.article_number,
    l.short_name AS law_name,
    EXTRACT(days FROM (now() - qd.created_at)) AS days_since_created,
        CASE
            WHEN ((qd.status = 'pending'::text) AND (EXTRACT(days FROM (now() - qd.created_at)) > (7)::numeric)) THEN 'urgent'::text
            WHEN (qd.status = 'pending'::text) THEN 'pending'::text
            ELSE qd.status
        END AS priority_status
   FROM ((((public.question_disputes qd
     LEFT JOIN public.user_profiles up ON ((qd.user_id = up.id)))
     LEFT JOIN public.questions q ON ((qd.question_id = q.id)))
     LEFT JOIN public.articles a ON ((q.primary_article_id = a.id)))
     LEFT JOIN public.laws l ON ((a.law_id = l.id)));


