    CONSTRAINT email_events_event_type_check CHECK ((event_type = ANY (ARRAY['sent'::text, 'delivered'::text, 'bounced'::text, 'opened'::text, 'clicked'::text, 'complained
  '::text, 'unsubscribed'::text, 'failed'::text])))
