-- Name: TABLE email_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.email_events IS 'Tracking de todos los eventos relacionados con emails automáticos';


--
-- Name: admin_email_analytics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_email_analytics WITH (security_invoker='on') AS
 SELECT email_type,
    count(*) FILTER (WHERE (event_type = 'sent'::text)) AS emails_sent,
    count(*) FILTER (WHERE (event_type = 'delivered'::text)) AS emails_delivered,
    count(*) FILTER (WHERE (event_type = 'opened'::text)) AS emails_opened,
    count(*) FILTER (WHERE (event_type = 'clicked'::text)) AS emails_clicked,
    count(*) FILTER (WHERE (event_type = 'bounced'::text)) AS emails_bounced,
    count(*) FILTER (WHERE (event_type = 'unsubscribed'::text)) AS unsubscribed,
    round((((count(*) FILTER (WHERE (event_type = 'opened'::text)))::numeric / (NULLIF(count(*) FILTER (WHERE (event_type = 'delivered'::text)), 0))::numeric) * (100)::numeric), 2) AS open_rate,
    round((((count(*) FILTER (WHERE (event_type = 'clicked'::text)))::numeric / (NULLIF(count(*) FILTER (WHERE (event_type = 'delivered'::text)), 0))::numeric) * (100)::numeric), 2) AS click_rate,
    date_trunc('day'::text, created_at) AS date
   FROM public.email_events
  WHERE (created_at >= (now() - '30 days'::interval))
  GROUP BY email_type, (date_trunc('day'::text, created_at));


--
-- Name: notification_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notification_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid,
    event_type text NOT NULL,
    notification_type text,
    device_info jsonb DEFAULT '{}'::jsonb,
    browser_info jsonb DEFAULT '{}'::jsonb,
    push_subscription jsonb,
    notification_data jsonb DEFAULT '{}'::jsonb,
    response_time_ms integer,
    error_details text,
    ip_address inet,
    user_agent text,
    referrer text,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT notification_events_event_type_check CHECK ((event_type = ANY (ARRAY['permission_requested'::text, 'permission_granted'::text, 'permission_denied'::text, 'subscription_created'::text, 'subscription_updated'::text, 'subscription_deleted'::text, 'notification_sent'::text, 'notification_delivered'::text, 'notification_clicked'::text, 'notification_dismissed'::text, 'notification_failed'::text, 'settings_updated'::text, 'banner_viewed'::text, 'banner_dismissed'::text, 'banner_clicked'::text]))),
    CONSTRAINT notification_events_notification_type_check CHECK ((notification_type = ANY (ARRAY['motivation'::text, 'streak_reminder'::text, 'achievement'::text, 'study_reminder'::text, 'reactivation'::text, 'urgent'::text, 'welcome'::text, 'test'::text])))
)
WITH (autovacuum_vacuum_insert_scale_factor='0.01', autovacuum_vacuum_insert_threshold='1000');


--
-- Name: TABLE notification_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notification_events IS 'Tracking de todos los eventos relacionados con notificaciones push';


--
-- Name: admin_notification_analytics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_notification_analytics WITH (security_invoker='on') AS
 SELECT count(DISTINCT user_id) AS total_users_with_notifications,
    count(*) AS total_notification_events,
    count(*) FILTER (WHERE (event_type = 'permission_granted'::text)) AS push_permissions_granted,
    count(*) FILTER (WHERE (event_type = 'permission_denied'::text)) AS push_permissions_denied,
    count(*) FILTER (WHERE (event_type = 'notification_sent'::text)) AS push_notifications_sent,
    count(*) FILTER (WHERE (event_type = 'notification_clicked'::text)) AS push_notifications_clicked,
    count(*) FILTER (WHERE (event_type = 'notification_dismissed'::text)) AS push_notifications_dismissed,
    round((((count(*) FILTER (WHERE (event_type = 'notification_clicked'::text)))::numeric / (NULLIF(count(*) FILTER (WHERE (event_type = 'notification_sent'::text)), 0))::numeric) * (100)::numeric), 2) AS push_click_rate,
    (device_info ->> 'platform'::text) AS platform,
    (browser_info ->> 'name'::text) AS browser_name,
    date_trunc('day'::text, created_at) AS date
   FROM public.notification_events
  WHERE (created_at >= (now() - '30 days'::interval))
  GROUP BY (date_trunc('day'::text, created_at)), (device_info ->> 'platform'::text), (browser_info ->> 'name'::text);


