--
-- Name: admin_pwa_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_pwa_stats WITH (security_invoker='on') AS
 SELECT count(DISTINCT pe.user_id) FILTER (WHERE (pe.event_type = 'pwa_installed'::text)) AS total_installations,
    count(DISTINCT ps.user_id) FILTER (WHERE (ps.is_standalone = true)) AS active_pwa_users,
    count(DISTINCT pe.user_id) FILTER (WHERE (pe.event_type = 'install_prompt_shown'::text)) AS prompt_shows,
    count(*) FILTER (WHERE (pe.event_type = 'pwa_installed'::text)) AS total_installs,
    count(*) FILTER (WHERE (pe.event_type = 'install_prompt_shown'::text)) AS total_prompts,
    round((((count(*) FILTER (WHERE (pe.event_type = 'pwa_installed'::text)))::numeric / (NULLIF(count(*) FILTER (WHERE (pe.event_type = 'install_prompt_shown'::text)), 0))::numeric) * (100)::numeric), 2) AS conversion_rate_percentage
   FROM (public.pwa_events pe
     LEFT JOIN public.pwa_sessions ps ON ((pe.user_id = ps.user_id)))
  WHERE (pe.created_at >= (now() - '30 days'::interval));


