    deploy_version text,
    position_type text,
    CONSTRAINT tests_test_type_check CHECK ((test_type = ANY (ARRAY['practice'::text, 'exam'::text])))
)
WITH (autovacuum_vacuum_scale_factor='0.02', autovacuum_vacuum_threshold='200', autovacuum_analyze_scale_factor='0.02', autovacuum_analyze_threshold='200', autovacuum_vacuum_insert_scale_factor='0.01', autovacuum_vacuum_insert_threshold='1000');


