--
-- Name: COLUMN tests.position_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tests.position_type IS 'Oposición del test (formato position_type, underscore — p.ej. "auxiliar_administrativo_estado"). Capturado en createDetailedTestSession a partir de window.location.pathname. NULL para tests globales (/test/rapido, /leyes/...) y para tests legacy previos al backfill 2026-05-24-tests-position-type.sql. Las queries que necesiten filtrar por oposición DEBEN preferir esta columna sobre derivar de tests.tema_number (que es int sin contexto y colisiona entre B2 de oposiciones distintas).';


--
-- Name: admin_users_with_roles; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_users_with_roles WITH (security_invoker='on') AS
 SELECT up.id AS user_id,
    up.email,
    up.full_name,
    up.plan_type,
    up.registration_source,
    up.requires_payment,
    up.stripe_customer_id,
    up.created_at AS user_created_at,
    up.updated_at AS user_updated_at,
        CASE
            WHEN (up.plan_type = ANY (ARRAY['legacy_free'::text, 'free'::text, 'trial'::text, 'premium'::text])) THEN true
            ELSE false
        END AS is_active_student,
    count(t.id) AS total_tests_30d,
    count(
        CASE
            WHEN (t.is_completed = true) THEN 1
            ELSE NULL::integer
        END) AS completed_tests_30d,
    count(
        CASE
            WHEN (t.is_completed = false) THEN 1
            ELSE NULL::integer
        END) AS abandoned_tests_30d,
    max(t.created_at) AS last_test_date,
    round(avg(
        CASE
            WHEN ((t.is_completed = true) AND (t.score IS NOT NULL)) THEN t.score
            ELSE NULL::numeric
        END), 1) AS avg_score_30d
   FROM (public.user_profiles up
     LEFT JOIN public.tests t ON (((up.id = t.user_id) AND (t.created_at >= (now() - '30 days'::interval)))))
  GROUP BY up.id, up.email, up.full_name, up.plan_type, up.registration_source, up.requires_payment, up.stripe_customer_id, up.created_at, up.updated_at
  ORDER BY up.created_at DESC;


