    CONSTRAINT ai_chat_traces_type_check CHECK ((trace_type = ANY (ARRAY['routing'::text, 'domain'::text, 'llm_call'::text, 'db_query'::text, 'post_process'::text, 'error'::text])))
)
WITH (autovacuum_vacuum_insert_scale_factor='0.01', autovacuum_vacuum_insert_threshold='1000');


