-- Name: COLUMN ai_chat_traces.parent_trace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ai_chat_traces.parent_trace_id IS 'Para traces anidados (ej: llm_call dentro de domain)';


--
-- Name: ai_chat_traces_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ai_chat_traces_summary WITH (security_invoker='on') AS
 SELECT l.id AS log_id,
    l.message,
    l.created_at,
    l.feedback,
    l.had_error,
    l.had_discrepancy,
    count(t.id) AS trace_count,
    sum(t.duration_ms) AS total_duration_ms,
    array_agg(DISTINCT t.trace_type ORDER BY t.trace_type) AS trace_types,
    count(*) FILTER (WHERE (t.success = false)) AS error_count,
    max((t.metadata ->> 'model'::text)) AS model_used,
    sum(((t.metadata ->> 'tokens_in'::text))::integer) AS total_tokens_in,
    sum(((t.metadata ->> 'tokens_out'::text))::integer) AS total_tokens_out
   FROM (public.ai_chat_logs l
     LEFT JOIN public.ai_chat_traces t ON ((t.log_id = l.id)))
  GROUP BY l.id, l.message, l.created_at, l.feedback, l.had_error, l.had_discrepancy
  ORDER BY l.created_at DESC;


--
-- Name: VIEW ai_chat_traces_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.ai_chat_traces_summary IS 'Vista resumen de logs con métricas de traces';


