    correct_article_suggestion text,
    explanation_fix text,
    psychometric_question_id uuid,
    spelling_question_id uuid,
    review_method_version text,
    options_ok boolean,
    enunciado_ok boolean
)
WITH (autovacuum_vacuum_insert_scale_factor='0.01', autovacuum_vacuum_insert_threshold='1000');


--
-- Name: COLUMN ai_verification_results.review_method_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ai_verification_results.review_method_version IS 'Versión del método de revisión aplicado (changelog en revisar-preguntas-con-agente.md §17). p.ej. v2.0';


--
-- Name: COLUMN ai_verification_results.options_ok; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ai_verification_results.options_ok IS '4º check (§3.2): literalidad de las opciones presentadas como correctas';


--
-- Name: COLUMN ai_verification_results.enunciado_ok; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ai_verification_results.enunciado_ok IS 'El enunciado cita la norma/órgano correctos (no se inventa un organismo ausente del artículo), corresponde al artículo vinculado y no filtra la respuesta. NULL = no evaluado. Dimensión añadida 19/07/2026 (cubo 1, caso Sandra).';


