--
-- Name: backlog_tasks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.backlog_tasks (
    id text NOT NULL,
    title text NOT NULL,
    priority text DEFAULT 'media'::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    lease_until timestamp with time zone,
    blocked_by text[] DEFAULT '{}'::text[] NOT NULL,
    outcome text,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    snooze_until timestamp with time zone,
    snooze_reason text,
    snoozed_by text,
    snooze_count integer DEFAULT 0 NOT NULL,
    progress_note text,
    resume_check text,
    force_claim_reason text,
    force_claimed_at timestamp with time zone,
    wake_on_deploy_sha text,
    wake_on_deploy_surface text,
    due_at timestamp with time zone,
    due_reason text,
    first_claimed_at timestamp with time zone,
    worked_seconds integer DEFAULT 0 NOT NULL,
    effort text,
    last_claimed_by text,
    review_requested_at timestamp with time zone,
    review_note text,
    review_requested_by text,
    archived_at timestamp with time zone,
    archive_evidence text,
    archived_by text,
    requiere_archivo boolean,
    reviewed_at timestamp with time zone,
    reviewed_by text,
    review_verdict text,
    review_findings text,
    CONSTRAINT backlog_cierre_coherente CHECK (((status = ANY (ARRAY['done'::text, 'dropped'::text])) = (closed_at IS NOT NULL))),
    CONSTRAINT backlog_claim_coherente CHECK ((((claimed_by IS NULL) AND (claimed_at IS NULL) AND (lease_until IS NULL)) OR ((claimed_by IS NOT NULL) AND (claimed_at IS NOT NULL) AND (lease_until IS NOT NULL)))),
    CONSTRAINT backlog_effort_valido CHECK (((effort IS NULL) OR (effort = ANY (ARRAY['minutos'::text, 'rato'::text, 'larga'::text, 'sesion_propia'::text])))),
    CONSTRAINT backlog_no_autorevision_check CHECK (((reviewed_by IS NULL) OR (review_requested_by IS NULL) OR (reviewed_by <> review_requested_by))),
    CONSTRAINT backlog_review_findings_check CHECK (((review_verdict IS NULL) OR ((review_verdict = 'ok'::text) AND (length(COALESCE(review_findings, ''::text)) >= 30)) OR ((review_verdict = 'problemas'::text) AND (length(COALESCE(review_findings, ''::text)) >= 60)))),
    CONSTRAINT backlog_review_verdict_check CHECK (((review_verdict IS NULL) OR (review_verdict = ANY (ARRAY['ok'::text, 'problemas'::text])))),
    CONSTRAINT backlog_tasks_archivo_coherente CHECK ((((archived_at IS NULL) AND (archive_evidence IS NULL)) OR ((archived_at IS NOT NULL) AND (archive_evidence IS NOT NULL) AND (length(btrim(archive_evidence)) >= 20)))),
    CONSTRAINT backlog_tasks_due_con_motivo CHECK ((((due_at IS NULL) AND (due_reason IS NULL)) OR ((due_at IS NOT NULL) AND (btrim(COALESCE(due_reason, ''::text)) <> ''::text)))),
    CONSTRAINT backlog_tasks_priority_check CHECK ((priority = ANY (ARRAY['critica'::text, 'alta'::text, 'media'::text, 'baja'::text, 'ninguna'::text]))),
    CONSTRAINT backlog_tasks_review_completo_check CHECK ((((review_requested_at IS NULL) AND (review_note IS NULL)) OR ((review_requested_at IS NOT NULL) AND (review_note IS NOT NULL) AND (length(btrim(review_note)) >= 20)))),
    CONSTRAINT backlog_tasks_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'blocked'::text, 'done'::text, 'dropped'::text])))
);


--
-- Name: TABLE backlog_tasks; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.backlog_tasks IS 'Estado de claim del backlog general. El CONTENIDO vive en docs/roadmap/tareas-pendientes.md; aquí solo el estado volátil. Join por id (T-xxx). Guardarraíl anti-divergencia en __tests__/backlog/backlogRegistry.test.ts.';


--
-- Name: COLUMN backlog_tasks.lease_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.lease_until IS 'Lease renovable por heartbeat. Si caduca, la tarea vuelve al pool aunque claimed_by siga puesto (sesión muerta).';


--
-- Name: COLUMN backlog_tasks.snooze_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.snooze_until IS 'Hasta cuándo no tiene sentido cogerla (espera a un reloj externo: cron, cosecha, fecha). NULL = despierta. Vence sola.';


--
-- Name: COLUMN backlog_tasks.snooze_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.snooze_reason IS 'Por qué espera y qué se mira al despertar. Obligatorio en el CLI: un aplazamiento sin motivo es indistinguible de un olvido.';


--
-- Name: COLUMN backlog_tasks.snooze_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.snooze_count IS 'Cuántas veces se ha aplazado. Una tarea aplazada 5 veces no está programada: es una decisión que nadie toma. A partir del umbral, `list` la saca a triaje.';


--
-- Name: COLUMN backlog_tasks.progress_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.progress_note IS 'Al pausar: qué se dejó HECHO. Sin esto, quien la coja al despertar empieza de cero aunque no lo esté.';


--
-- Name: COLUMN backlog_tasks.resume_check; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.resume_check IS 'Al pausar: qué hay que VERIFICAR al despertar. Es el motivo de que la tarea siga viva.';


--
-- Name: COLUMN backlog_tasks.force_claim_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.force_claim_reason IS 'Motivo de haber cogido una tarea aplazada o bloqueada saltándose la condición. Registrado a propósito: el escape existe, pero deja rastro.';


--
-- Name: COLUMN backlog_tasks.wake_on_deploy_sha; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.wake_on_deploy_sha IS 'Commit que tiene que estar DESPLEGADO para poder verificar la tarea. NULL = nada que esperar. Lo limpia `backlog.cjs deployed <sha>` (lo llama el propio script de deploy).';


--
-- Name: COLUMN backlog_tasks.wake_on_deploy_surface; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.wake_on_deploy_surface IS 'frontend | backend | both — qué superficie hay que mirar. El backend y el frontend se despliegan por separado y una tarea puede necesitar solo una.';


--
-- Name: COLUMN backlog_tasks.due_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.due_at IS 'Fecha límite: la tarea tiene que estar ANTES de aquí. NO confundir con snooze_until, que es lo contrario (no cogerla ANTES de). Pasado el plazo la tarea no se pospone: se decide.';


--
-- Name: COLUMN backlog_tasks.due_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.due_reason IS 'Motivo EXTERNO del plazo: quién lo espera o qué fecha de un tercero lo fija. Obligatorio junto a due_at — un plazo sin motivo es una preferencia disfrazada.';


--
-- Name: COLUMN backlog_tasks.first_claimed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.first_claimed_at IS 'Primera vez que alguien la cogió: separa «costó mucho» de «esperó mucho».';


--
-- Name: COLUMN backlog_tasks.worked_seconds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.worked_seconds IS 'Segundos acumulados con la tarea reclamada (T-414). NO es closed_at-created_at: eso mide espera, no esfuerzo.';


--
-- Name: COLUMN backlog_tasks.effort; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.effort IS 'Esfuerzo declarado en cajones: minutos | rato | larga | sesion_propia. Contrastable contra worked_seconds.';


--
-- Name: COLUMN backlog_tasks.last_claimed_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.last_claimed_by IS 'Última sesión que la tuvo, aunque ya la soltara (T-430). Permite recuperar su trabajo sin pushear al retomarla.';


--
-- Name: COLUMN backlog_tasks.review_requested_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.review_requested_at IS 'T-539 — quinta espera: hecho y esperando que una PERSONA lo revise. No la despierta el reloj ni el deploy.';


--
-- Name: COLUMN backlog_tasks.review_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.review_note IS 'T-539 — QUÉ hay que revisar y dónde está el entregable. Obligatorio: sin esto, quien revise no sabe qué mirar.';


--
-- Name: COLUMN backlog_tasks.review_requested_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.review_requested_by IS 'T-539 — qué sesión lo dejó a revisión, para poder preguntarle.';


--
-- Name: COLUMN backlog_tasks.archived_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.archived_at IS 'T-392 — cuándo se confirmó, con evidencia, que el trabajo funciona en producción. NULL = sin archivar.';


--
-- Name: COLUMN backlog_tasks.archive_evidence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.archive_evidence IS 'T-392 — QUÉ se comprobó y con qué evidencia (no "ok"/"listo"). Obligatoria si archived_at está puesto.';


--
-- Name: COLUMN backlog_tasks.archived_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.archived_by IS 'T-392 — sid que archivó, o "migracion-t392"/"auto" para las que no pasaron por una persona.';


--
-- Name: COLUMN backlog_tasks.requiere_archivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.backlog_tasks.requiere_archivo IS 'T-392 — ¿esta tarea, al cerrarse, tocaba superficie servida? true=hace falta `archive --evidencia` tras verla en producción; false=se archivó sola (docs/tooling, nada que ver funcionar); NULL=no se pudo determinar (fail-open) o es de antes de esta migración.';


