    event_data jsonb DEFAULT '{}'::jsonb,
    days_since_registration integer DEFAULT 0,
    registration_source text,
    plan_type text,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: conversion_funnel_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conversion_funnel_stats WITH (security_invoker='on') AS
 SELECT registration_source,
    count(DISTINCT
        CASE
            WHEN (event_type = 'registration'::text) THEN user_id
            ELSE NULL::uuid
        END) AS registrations,
    count(DISTINCT
        CASE
            WHEN (event_type = 'first_test_completed'::text) THEN user_id
            ELSE NULL::uuid
        END) AS completed_first_test,
    count(DISTINCT
        CASE
            WHEN (event_type = 'limit_reached'::text) THEN user_id
            ELSE NULL::uuid
        END) AS hit_limit,
    count(DISTINCT
        CASE
            WHEN (event_type = 'upgrade_modal_viewed'::text) THEN user_id
            ELSE NULL::uuid
        END) AS saw_modal,
    count(DISTINCT
        CASE
            WHEN (event_type = 'upgrade_button_clicked'::text) THEN user_id
            ELSE NULL::uuid
        END) AS clicked_upgrade,
    count(DISTINCT
        CASE
            WHEN (event_type = 'premium_page_viewed'::text) THEN user_id
            ELSE NULL::uuid
        END) AS visited_premium,
    count(DISTINCT
        CASE
            WHEN (event_type = 'checkout_started'::text) THEN user_id
            ELSE NULL::uuid
        END) AS started_checkout,
    count(DISTINCT
        CASE
            WHEN (event_type = 'payment_completed'::text) THEN user_id
            ELSE NULL::uuid
        END) AS paid,
    round(((100.0 * (count(DISTINCT
        CASE
            WHEN (event_type = 'payment_completed'::text) THEN user_id
            ELSE NULL::uuid
        END))::numeric) / (NULLIF(count(DISTINCT
        CASE
            WHEN (event_type = 'registration'::text) THEN user_id
            ELSE NULL::uuid
        END), 0))::numeric), 2) AS conversion_rate
   FROM public.conversion_events
  GROUP BY registration_source;


--
-- Name: conversion_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conversion_outbox (
    id text NOT NULL,
    event_type text NOT NULL,
    destination text NOT NULL,
    user_id uuid,
    value_cents integer DEFAULT 0 NOT NULL,
    currency text DEFAULT 'eur'::text NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    delivered_at timestamp with time zone,
    next_attempt_at timestamp with time zone,
    CONSTRAINT conversion_outbox_event_type_check CHECK ((event_type = ANY (ARRAY['purchase'::text, 'refund'::text, 'registration'::text, 'checkout_started'::text]))),
    CONSTRAINT conversion_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'delivered'::text, 'failed'::text, 'skipped'::text])))
);


--
-- Name: TABLE conversion_outbox; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.conversion_outbox IS 'Outbox de conversiones de marketing. 1 fila por (evento × destino). Escrito por lib/conversions/recordConversion (no trigger). Worker: app/api/cron/conversion-outbox. Ver docs/roadmap/trackeo-conversiones-ventas.md (F1).';


--
-- Name: COLUMN conversion_outbox.id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_outbox.id IS 'dedupId determinista = idempotencia. Reintentar un evento ya encolado no duplica (ON CONFLICT DO NOTHING en el insert).';


--
-- Name: COLUMN conversion_outbox.retry_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversion_outbox.retry_count IS 'Incrementa en cada fallo de entrega. A partir de 5 → DLQ (status=failed). Inspección manual.';


--
-- Name: conversion_time_analysis; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.conversion_time_analysis WITH (security_invoker='on') AS
 SELECT registration_source,
    avg(days_since_registration) AS avg_days_to_convert,
    min(days_since_registration) AS min_days,
    max(days_since_registration) AS max_days,
    count(*) AS total_conversions
   FROM public.conversion_events
  WHERE (event_type = 'payment_completed'::text)
  GROUP BY registration_source;


--
-- Name: convocatoria_documentos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.convocatoria_documentos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    convocatoria_id uuid NOT NULL,
    tipo text NOT NULL,
    url text NOT NULL,
    titulo text,
    boletin text,
    referencia text,
    fecha_publicacion date,
    content_hash text,
    extracted_text text,
    llm_extraction jsonb,
    confianza integer,
    fuente text DEFAULT 'manual'::text NOT NULL,
    fetched_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tsv tsvector GENERATED ALWAYS AS (to_tsvector('spanish'::regconfig, ((COALESCE(titulo, ''::text) || ' '::text) || COALESCE(extracted_text, ''::text)))) STORED,
    curado boolean DEFAULT false NOT NULL,
    curado_por text,
    curado_at timestamp with time zone,
    doc_key text,
    oep_id uuid,
    CONSTRAINT convocatoria_documentos_confianza_check CHECK (((confianza IS NULL) OR ((confianza >= 0) AND (confianza <= 100)))),
    CONSTRAINT convocatoria_documentos_fuente_check CHECK ((fuente = ANY (ARRAY['detect-notas'::text, 'radar'::text, 'seguimiento'::text, 'manual'::text, 'backfill-titulo'::text, 'epigrafe-verify'::text, 'oep-backfill'::text, 'oep-radar'::text]))),
    CONSTRAINT convocatoria_documentos_tipo_check CHECK ((tipo = ANY (ARRAY['oep_decreto'::text, 'bases'::text, 'convocatoria'::text, 'temario'::text, 'correccion_errores'::text, 'lista_admitidos'::text, 'resolucion_tribunal'::text, 'anuncio_fecha'::text, 'nota'::text, 'otro'::text])))
);


--
-- Name: TABLE convocatoria_documentos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.convocatoria_documentos IS 'Corpus del proceso: 1 fila por documento oficial. extracted_text = entero (evidencia); llm_extraction = partes esenciales. ON DELETE RESTRICT: la evidencia no se borra en cascada.';


--
-- Name: COLUMN convocatoria_documentos.curado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_documentos.curado IS 'false=lo que el crawler pescó (evidencia bruta, NO alimenta extracción). true=discriminado y validado por Claude: solo estos se leen para extraer hechos del proceso.';


--
-- Name: COLUMN convocatoria_documentos.doc_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_documentos.doc_key IS 'Identidad canónica del documento (id de boletín o URL normalizada). La calcula lib/convocatoria/canonicalizeBoletinUrl.cjs. Dedup por (convocatoria_id, doc_key).';


--
-- Name: COLUMN convocatoria_documentos.oep_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_documentos.oep_id IS 'Enlace inverso al decreto de OEP clonado (tipo=oep_decreto). NULL para documentos de convocatoria/bases/temario.';


--
-- Name: convocatoria_hitos; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.convocatoria_hitos (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    oposicion_id uuid NOT NULL,
    fecha date NOT NULL,
    titulo text NOT NULL,
    descripcion text,
    url text,
    status text DEFAULT 'upcoming'::text NOT NULL,
    order_index integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    convocatoria_id uuid,
    severity text DEFAULT 'important'::text NOT NULL,
    notify_status text DEFAULT 'pending'::text NOT NULL,
    tipo text,
    origen text DEFAULT 'registro'::text NOT NULL,
    source_documento_id uuid,
    cita_literal text,
    confianza integer,
    fecha_aproximada boolean DEFAULT false NOT NULL,
    CONSTRAINT convocatoria_hitos_confianza_check CHECK (((confianza IS NULL) OR ((confianza >= 0) AND (confianza <= 100)))),
    CONSTRAINT convocatoria_hitos_notify_status_check CHECK ((notify_status = ANY (ARRAY['pending'::text, 'verified'::text, 'sent'::text]))),
    CONSTRAINT convocatoria_hitos_origen_chk CHECK ((origen = ANY (ARRAY['registro'::text, 'inferencia'::text, 'estimacion'::text]))),
    CONSTRAINT convocatoria_hitos_severity_check CHECK ((severity = ANY (ARRAY['critical'::text, 'important'::text, 'cosmetic'::text]))),
    CONSTRAINT convocatoria_hitos_status_check CHECK ((status = ANY (ARRAY['completed'::text, 'current'::text, 'upcoming'::text]))),
    CONSTRAINT convocatoria_hitos_tipo_chk CHECK (((tipo IS NULL) OR (tipo = ANY (ARRAY['oep_aprobada'::text, 'convocatoria_publicada'::text, 'bases_publicadas'::text, 'programa_publicado'::text, 'plazo_inicio'::text, 'plazo_fin'::text, 'lista_provisional'::text, 'lista_definitiva'::text, 'tribunal_constituido'::text, 'ejercicio_1'::text, 'ejercicio_2'::text, 'plantilla_respuestas'::text, 'resultados'::text, 'reconocimiento_medico'::text, 'modificacion_plazas'::text, 'nombramientos'::text, 'otro'::text]))))
);


--
-- Name: COLUMN convocatoria_hitos.convocatoria_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_hitos.convocatoria_id IS 'Sprint G: hito atado a su convocatoria específica. Backfill en G.2. oposicion_id queda como legacy hasta G.7.';


--
-- Name: COLUMN convocatoria_hitos.severity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_hitos.severity IS 'Fase 8: canal de notificación. critical=campana+email, important=solo campana, cosmetic=nada.';


--
-- Name: COLUMN convocatoria_hitos.notify_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_hitos.notify_status IS 'Fase 8 GUARDARRAÍL: pending=propuesto/histórico (no notifica), verified=confirmado vs fuente oficial (elegible fan-out), sent=fan-out hecho. Solo verified dispara.';


--
-- Name: COLUMN convocatoria_hitos.origen; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_hitos.origen IS 'registro=el documento lo dice literal | inferencia=derivado de una REGLA del documento | estimacion=criterio propio sin documento. Ortogonal a fecha_aproximada (precisión) y a la verificación.';


--
-- Name: COLUMN convocatoria_hitos.fecha_aproximada; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_hitos.fecha_aproximada IS 'Precisión de la fecha ("mayo de 2027" sin día). NO confundir con origen: una fecha puede ser aproximada Y oficial (caso Marta: la base 9 dice literalmente "mayo de 2027").';


--
-- Name: convocatorias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.convocatorias (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    oposicion_id uuid NOT NULL,
    "año" integer NOT NULL,
    convocatoria_numero text,
    convocatoria_fecha date,
    convocatoria_dogv text,
    is_current boolean DEFAULT false NOT NULL,
    archived_at timestamp with time zone,
    estado_proceso text,
    oep_decreto text,
    oep_fecha date,
    plazas_libres integer,
    plazas_promocion_interna integer,
    plazas_discapacidad integer,
    boe_publication_date date,
    boe_reference text,
    inscription_start date,
    inscription_deadline date,
    exam_date date,
    exam_date_approximate boolean DEFAULT false,
    programa_url text,
    examen_config jsonb,
    landing_faqs jsonb,
    landing_estadisticas jsonb,
    landing_description text,
    requisitos_especiales jsonb,
    seguimiento_last_checked timestamp with time zone,
    seguimiento_last_hash text,
    seguimiento_change_status text,
    seguimiento_change_detected_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sistema_selectivo text,
    programa_last_hash text,
    programa_last_checked timestamp with time zone,
    plazas_otros_turnos jsonb,
    plazas_discapacidad_incluidas boolean,
    plazas_prevision boolean DEFAULT false NOT NULL,
    plazas_prevision_motivo text,
    temario_version_id uuid,
    inscritos integer,
    presentados integer,
    CONSTRAINT chk_plazas_otros_turnos_bien_formado CHECK (public.plazas_otros_turnos_bien_formado(plazas_otros_turnos)),
    CONSTRAINT chk_plazas_prevision_motivo CHECK (((NOT plazas_prevision) OR (COALESCE(plazas_prevision_motivo, ''::text) <> ''::text))),
    CONSTRAINT "convocatorias_año_check1" CHECK ((("año" >= 1970) AND ("año" <= 2100))),
    CONSTRAINT convocatorias_sistema_chk CHECK (((sistema_selectivo IS NULL) OR (sistema_selectivo = ANY (ARRAY['oposicion'::text, 'concurso-oposicion'::text, 'concurso'::text]))))
);


--
-- Name: TABLE convocatorias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.convocatorias IS 'Sprint G del roadmap sprint-g-oposiciones-vs-convocatorias.md. Un proceso selectivo concreto de una oposición. Una oposición tiene N convocatorias (histórico) + 0/1 con is_current=true.';


--
-- Name: COLUMN convocatorias.is_current; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.is_current IS 'Convocatoria vigente del cuerpo. Trigger ensure_single_current_convocatoria garantiza máximo 1 por oposicion_id.';


--
-- Name: COLUMN convocatorias.archived_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.archived_at IS 'NULL = convocatoria vigente o en curso. Timestamp = convocatoria histórica archivada (proceso terminado).';


--
-- Name: COLUMN convocatorias.plazas_otros_turnos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.plazas_otros_turnos IS 'Turnos de reserva fuera de los tres comunes (libre/promoción/discapacidad). Array: [{"turno":"violencia_genero","plazas":6,"cita":"<literal del boletín>"}]. Cola abierta a propósito: una columna por cupo sería una migración cada trimestre.';


--
-- Name: COLUMN convocatorias.plazas_discapacidad_incluidas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.plazas_discapacidad_incluidas IS 'true = el cupo de discapacidad se reserva DENTRO de plazas_libres/promoción (no suma al total: Orden 1634/2026 Madrid «se reservan 7 del total de las convocadas por el turno libre»). false/NULL = es un turno APARTE y suma (BON 101/2025 Navarra, DOCM 240/2025 CLM). NULL = no consta; se asume aparte, que es lo verificado en los documentos leídos. Marcar true SOLO con cita literal.';


--
-- Name: COLUMN convocatorias.plazas_prevision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.plazas_prevision IS 'true = las plazas de esta fila son una PREVISIÓN nuestra (ni OEP ni convocatoria publicadas todavía), no un hecho. La landing debe decirlo («plazas previstas»), nunca venderlas como confirmadas. false = son un hecho publicado y DEBEN tener su documento en convocatoria_documentos + su cita. Espejo de exam_date_approximate, que hace lo mismo con la fecha.';


--
-- Name: COLUMN convocatorias.plazas_prevision_motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.plazas_prevision_motivo IS 'De dónde sale la previsión (base de la estimación). Obligatorio si plazas_prevision=true: una previsión sin razonamiento es una invención.';


--
-- Name: COLUMN convocatorias.temario_version_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.temario_version_id IS 'Versión de temario que usa esta convocatoria. Varias convocatorias pueden compartir versión (temario estable). NULL → resuelve por fallback (vista temario_efectivo).';


--
-- Name: COLUMN convocatorias.inscritos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.inscritos IS 'Nº de solicitudes/admitidos de esa convocatoria. SOLO fuente oficial (acta del tribunal / INAP / BOE de listas). NULL si no hay dato oficial verificado — NUNCA estimar.';


--
-- Name: COLUMN convocatorias.presentados; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatorias.presentados IS 'Nº de opositores presentados al primer ejercicio. SOLO fuente oficial. NULL si no hay dato oficial verificado — NUNCA estimar.';


