    CONSTRAINT chk_fetcher_headless_consistency CHECK ((((fetcher_type = 'headless'::text) AND (headless_required = true)) OR (fetcher_type <> 'headless'::text))),
    CONSTRAINT oposiciones_coverage_level_check CHECK ((coverage_level = ANY (ARRAY['catalogada'::text, 'monitorizada'::text, 'con_temario'::text, 'con_tests'::text, 'con_landing'::text, 'full'::text]))),
    CONSTRAINT oposiciones_estado_proceso_check CHECK ((estado_proceso = ANY (ARRAY['sin_oep'::text, 'oep_aprobada'::text, 'convocada'::text, 'inscripcion_abierta'::text, 'inscripcion_cerrada'::text, 'lista_admitidos'::text, 'pendiente_examen'::text, 'examen_realizado'::text, 'resultados'::text, 'nombramientos'::text]))),
    CONSTRAINT oposiciones_familia_check CHECK (((familia IS NULL) OR (familia = ANY (ARRAY['administracion_general'::text, 'sanidad'::text, 'educacion'::text, 'justicia'::text, 'seguridad'::text, 'tecnica'::text, 'social'::text, 'oficios'::text, 'otros'::text])))),
    CONSTRAINT oposiciones_fetcher_type_check CHECK ((fetcher_type = ANY (ARRAY['http'::text, 'headless'::text, 'pdf'::text, 'rss'::text, 'boe_api'::text]))),
    CONSTRAINT oposiciones_sistema_chk CHECK (((sistema_selectivo IS NULL) OR (sistema_selectivo = ANY (ARRAY['oposicion'::text, 'concurso-oposicion'::text, 'concurso'::text])))),
    CONSTRAINT oposiciones_tipo_acceso_check CHECK ((tipo_acceso = ANY (ARRAY['libre'::text, 'promocion_interna'::text, 'discapacidad'::text])))
);


