-- Name: COLUMN oposiciones.grupo_convocatoria; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.oposiciones.grupo_convocatoria IS 'Oposiciones que son la MISMA con convocatorias vivas y temario distinto comparten este valor. NULL = sin hermanas. Se usa para avisar al usuario de que compruebe cuál tiene seleccionada (caso Madrid 2026/2027).';


--
-- Name: convocatoria_docs_coverage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.convocatoria_docs_coverage AS
 WITH doc_counts AS (
         SELECT convocatoria_documentos.convocatoria_id,
            (count(*))::integer AS docs_clonados
           FROM public.convocatoria_documentos
          WHERE (convocatoria_documentos.convocatoria_id IS NOT NULL)
          GROUP BY convocatoria_documentos.convocatoria_id
        ), hito_stats AS (
         SELECT h.convocatoria_id,
            (count(*) FILTER (WHERE (h.url IS NOT NULL)))::integer AS hitos_con_url,
            (count(*) FILTER (WHERE (h.source_documento_id IS NOT NULL)))::integer AS hitos_enlazados,
            (count(*) FILTER (WHERE ((h.url IS NOT NULL) AND (h.source_documento_id IS NULL) AND (md.id IS NOT NULL))))::integer AS hitos_enlazables,
            (count(*) FILTER (WHERE ((h.url IS NOT NULL) AND (h.source_documento_id IS NULL) AND (md.id IS NULL))))::integer AS docs_por_clonar,
            (count(*) FILTER (WHERE ((h.cita_literal IS NOT NULL) AND (length(btrim(h.cita_literal)) > 0) AND (h.source_documento_id IS NULL) AND (h.origen IS DISTINCT FROM 'estimacion'::text))))::integer AS citas_sin_fuente
           FROM (public.convocatoria_hitos h
             LEFT JOIN LATERAL ( SELECT d.id
                   FROM public.convocatoria_documentos d
                  WHERE ((d.convocatoria_id = h.convocatoria_id) AND (d.url = h.url))
                 LIMIT 1) md ON ((h.url IS NOT NULL)))
          WHERE (h.convocatoria_id IS NOT NULL)
          GROUP BY h.convocatoria_id
        )
 SELECT c.id AS convocatoria_id,
    c.oposicion_id,
    o.slug,
    o.is_active,
    c.is_current,
    c."año",
    COALESCE(dc.docs_clonados, 0) AS docs_clonados,
    COALESCE(hs.hitos_con_url, 0) AS hitos_con_url,
    COALESCE(hs.hitos_enlazados, 0) AS hitos_enlazados,
    COALESCE(hs.hitos_enlazables, 0) AS hitos_enlazables,
    COALESCE(hs.docs_por_clonar, 0) AS docs_por_clonar,
    COALESCE(hs.citas_sin_fuente, 0) AS citas_sin_fuente,
    ((COALESCE(hs.docs_por_clonar, 0) > 0) OR (COALESCE(hs.hitos_enlazables, 0) > 0) OR (COALESCE(hs.citas_sin_fuente, 0) > 0)) AS incompleto
   FROM (((public.convocatorias c
     JOIN public.oposiciones o ON ((o.id = c.oposicion_id)))
     LEFT JOIN doc_counts dc ON ((dc.convocatoria_id = c.id)))
     LEFT JOIN hito_stats hs ON ((hs.convocatoria_id = c.id)));


--
-- Name: VIEW convocatoria_docs_coverage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.convocatoria_docs_coverage IS 'Cobertura de provenance de documentos por convocatoria: clonados vs referenciados (hitos con url) vs enlazados, con desglose de huecos (enlazables por URL sin fetch, por clonar, citas sin fuente). Fuente única del kind convocatoria_docs_incompletos del sweep. Diseño: docs/roadmap/verificacion-convocatorias-documentos-proceso.md';


--
-- Name: convocatoria_hito_incidencias; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.convocatoria_hito_incidencias AS
 SELECT h1.convocatoria_id,
    h1.id AS hito_id,
    'I1_orden'::text AS invariante,
    format('%s (%s) es posterior a %s (%s)'::text, h1.tipo, h1.fecha, h2.tipo, h2.fecha) AS detalle
   FROM (public.convocatoria_hitos h1
     JOIN public.convocatoria_hitos h2 ON (((h2.convocatoria_id = h1.convocatoria_id) AND (h1.fecha > h2.fecha))))
  WHERE (((h1.tipo = 'plazo_inicio'::text) AND (h2.tipo = 'plazo_fin'::text)) OR ((h1.tipo = 'plazo_fin'::text) AND (h2.tipo = 'ejercicio_1'::text)) OR ((h1.tipo = 'ejercicio_1'::text) AND (h2.tipo = 'resultados'::text)))
UNION ALL
 SELECT h.convocatoria_id,
    (array_agg(h.id ORDER BY h.fecha))[1] AS hito_id,
    'I2_duplicado'::text AS invariante,
    format('%s "%s" aparece %s veces con fechas distintas'::text, h.tipo, min(h.titulo), count(*)) AS detalle
   FROM public.convocatoria_hitos h
  WHERE (h.tipo = ANY (ARRAY['ejercicio_1'::text, 'plazo_inicio'::text, 'plazo_fin'::text]))
  GROUP BY h.convocatoria_id, h.tipo, (lower(regexp_replace(COALESCE(h.titulo, ''::text), '\s+'::text, ' '::text, 'g'::text)))
 HAVING (count(DISTINCT h.fecha) > 1)
UNION ALL
 SELECT h.convocatoria_id,
    h.id AS hito_id,
    'I9_tipo_incoherente'::text AS invariante,
    format('tipo=%s contradice el título "%s"'::text, h.tipo, h.titulo) AS detalle
   FROM public.convocatoria_hitos h
  WHERE (((h.tipo = 'plazo_inicio'::text) AND (h.titulo ~* 'cierre|clausura|fin del plazo'::text)) OR ((h.tipo = 'plazo_fin'::text) AND (h.titulo ~* 'apertura|inicio del plazo'::text)) OR ((h.tipo = 'ejercicio_1'::text) AND (h.titulo ~* 'convocatoria a examen'::text)))
UNION ALL
 SELECT h.convocatoria_id,
    h.id AS hito_id,
    'I5_registro_sin_fuente'::text AS invariante,
    format('%s se presenta como oficial pero no cita documento'::text, COALESCE(h.tipo, '(sin tipo)'::text)) AS detalle
   FROM public.convocatoria_hitos h
  WHERE ((h.origen = 'registro'::text) AND (h.source_documento_id IS NULL))
UNION ALL
 SELECT h.convocatoria_id,
    h.id AS hito_id,
    'I6_sin_tipo'::text AS invariante,
    format('título sin tipo: %s'::text, h.titulo) AS detalle
   FROM public.convocatoria_hitos h
  WHERE ((h.tipo IS NULL) OR (h.tipo = 'otro'::text))
UNION ALL
 SELECT h.convocatoria_id,
    h.id AS hito_id,
    'I7_prevision_caducada'::text AS invariante,
    format('previsión de %s ya pasada y sigue en pie'::text, h.fecha) AS detalle
   FROM public.convocatoria_hitos h
  WHERE ((h.origen = 'estimacion'::text) AND (h.fecha < CURRENT_DATE))
UNION ALL
 SELECT h.convocatoria_id,
    h.id AS hito_id,
    'I8_status_contradice_fecha'::text AS invariante,
    format('status=%s con fecha %s'::text, h.status, h.fecha) AS detalle
   FROM public.convocatoria_hitos h
  WHERE (((h.status = 'completed'::text) AND (h.fecha > CURRENT_DATE)) OR ((h.status = 'upcoming'::text) AND (h.fecha < CURRENT_DATE)))
UNION ALL
 SELECT cv.id AS convocatoria_id,
    NULL::uuid AS hito_id,
    'I10_inscripcion_sin_convocatoria'::text AS invariante,
    format('plazo de inscripción cerrado el %s pero la convocatoria aún no está publicada (estado=%s, plazas_prevision=%s) → la landing dirá "plazo cerrado" en un proceso no convocado'::text, cv.inscription_deadline, cv.estado_proceso, cv.plazas_prevision) AS detalle
   FROM public.convocatorias cv
  WHERE ((cv.inscription_deadline IS NOT NULL) AND (cv.inscription_deadline < CURRENT_DATE) AND ((cv.plazas_prevision = true) OR (EXISTS ( SELECT 1
           FROM public.convocatoria_hitos h
          WHERE ((h.convocatoria_id = cv.id) AND (h.tipo = 'convocatoria_publicada'::text) AND (h.status = 'upcoming'::text))))))
UNION ALL
 SELECT cv.id AS convocatoria_id,
    h.id AS hito_id,
    'I11_fechas_inscripcion_vs_hitos'::text AS invariante,
    format('la convocatoria dice %s=%s y su hito %s marca %s → la landing muestra dos fechas distintas del mismo plazo'::text,
        CASE
            WHEN (h.tipo = 'plazo_inicio'::text) THEN 'inscription_start'::text
            ELSE 'inscription_deadline'::text
        END,
        CASE
            WHEN (h.tipo = 'plazo_inicio'::text) THEN cv.inscription_start
            ELSE cv.inscription_deadline
        END, h.tipo, h.fecha) AS detalle
   FROM (public.convocatorias cv
     JOIN public.convocatoria_hitos h ON ((h.convocatoria_id = cv.id)))
  WHERE ((cv.archived_at IS NULL) AND (((h.tipo = 'plazo_inicio'::text) AND (cv.inscription_start IS NOT NULL) AND (h.fecha <> cv.inscription_start)) OR ((h.tipo = 'plazo_fin'::text) AND (cv.inscription_deadline IS NOT NULL) AND (h.fecha <> cv.inscription_deadline))));


--
-- Name: VIEW convocatoria_hito_incidencias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.convocatoria_hito_incidencias IS 'Invariantes deterministas del timeline (sin IA). I2 título-aware (repeticiones legítimas del mismo tipo no saltan; duplicado real con mismo título sí). I9: mistype (título contradice el tipo), la clase que I2 título-aware no cubre. I1/I2/I9 = graves.';


