--
-- Name: COLUMN convocatoria_seguimiento_checks.checked_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_seguimiento_checks.checked_url IS 'URL realmente comprobada en esta pasada. NULL en filas anteriores al 26/07/2026. El detector de fuentes ciegas solo usa evidencia cuya checked_url coincide con oposiciones.seguimiento_url; si no coincide (repunte posterior) o es NULL, la ignora.';


--
-- Name: temario_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.temario_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    oposicion_id uuid NOT NULL,
    label text,
    estado text DEFAULT 'active'::text NOT NULL,
    es_default boolean DEFAULT false NOT NULL,
    source_convocatoria_id uuid,
    source_documento_id uuid,
    parent_version_id uuid,
    verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT temario_versions_estado_check CHECK ((estado = ANY (ARRAY['draft'::text, 'verified'::text, 'active'::text, 'superseded'::text])))
);


--
-- Name: TABLE temario_versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.temario_versions IS 'Versión del temario de una oposición (Fase 1 de temario-versionado-por-convocatoria). Las convocatorias la referencian; varias comparten versión si el temario es igual. es_default = la servible por la vía legacy (is_active).';


--
-- Name: convocatoria_temario_efectivo; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.convocatoria_temario_efectivo AS
 SELECT id AS convocatoria_id,
    oposicion_id,
    COALESCE(( SELECT tv.id
           FROM public.temario_versions tv
          WHERE ((tv.id = cv.temario_version_id) AND (tv.estado = ANY (ARRAY['active'::text, 'verified'::text])))), ( SELECT tv.id
           FROM public.temario_versions tv
          WHERE ((tv.oposicion_id = cv.oposicion_id) AND tv.es_default AND (tv.estado = ANY (ARRAY['active'::text, 'verified'::text])))
          ORDER BY tv.verified_at DESC NULLS LAST, tv.created_at DESC
         LIMIT 1)) AS temario_version_id,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM public.temario_versions tv
              WHERE ((tv.id = cv.temario_version_id) AND (tv.estado = ANY (ARRAY['active'::text, 'verified'::text]))))) THEN 'propia'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.temario_versions tv
              WHERE ((tv.oposicion_id = cv.oposicion_id) AND tv.es_default AND (tv.estado = ANY (ARRAY['active'::text, 'verified'::text]))))) THEN 'fallback_anterior'::text
            ELSE 'sin_temario'::text
        END AS origen
   FROM public.convocatorias cv;


--
-- Name: VIEW convocatoria_temario_efectivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.convocatoria_temario_efectivo IS 'Temario efectivo por convocatoria (Fase 3): versión propia servible, o fallback a la default anterior, o sin_temario. Espejo de lib/temario/resolveTemarioEfectivo.js. Aún no consumido por serving (Fase 4).';


--
-- Name: convocatoria_verification; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.convocatoria_verification (
    convocatoria_id uuid NOT NULL,
    state text DEFAULT 'never_verified'::text NOT NULL,
    verified_data_hash text,
    verified_source_hash text,
    source_url text,
    source_snippet text,
    verdict text,
    findings jsonb,
    agent_run_id text,
    verified_by text,
    verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT convocatoria_verification_state_check CHECK ((state = ANY (ARRAY['never_verified'::text, 'verifying'::text, 'verified_correct'::text, 'verified_issues'::text, 'needs_human'::text, 'stale'::text]))),
    CONSTRAINT convocatoria_verification_verdict_check CHECK ((verdict = ANY (ARRAY['correct'::text, 'issues'::text, 'needs_human'::text])))
);


--
-- Name: convocatoria_verification_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.convocatoria_verification_effective AS
 SELECT c.id AS convocatoria_id,
    c.oposicion_id,
    COALESCE(v.state, 'never_verified'::text) AS effective_state,
    v.verdict,
    v.source_url,
    v.source_snippet,
    v.findings,
    v.verified_at
   FROM (public.convocatorias c
     LEFT JOIN public.convocatoria_verification v ON ((v.convocatoria_id = c.id)))
  WHERE (c.is_current = true);


--
-- Name: convocatoria_verification_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.convocatoria_verification_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    convocatoria_id uuid NOT NULL,
    state text,
    data_hash text,
    source_hash text,
    source_url text,
    verdict text,
    findings jsonb,
    agent_run_id text,
    verified_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: COLUMN convocatoria_verification_history.convocatoria_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.convocatoria_verification_history.convocatoria_id IS 'SIN FK a propósito: el historial debe sobrevivir al borrado de la convocatoria (un audit trail que cascadea no es un audit trail).';


--
-- Name: convocatorias_boe; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.convocatorias_boe (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    boe_id text NOT NULL,
    boe_fecha date NOT NULL,
    boe_url_pdf text,
    boe_url_html text,
    boe_url_xml text,
    titulo text NOT NULL,
    titulo_limpio text,
    departamento_codigo text,
    departamento_nombre text,
    epigrafe text,
    tipo text,
    categoria text,
    cuerpo text,
    acceso text,
    num_plazas integer,
    num_plazas_libre integer,
    num_plazas_pi integer,
    num_plazas_discapacidad integer,
    fecha_disposicion date,
    fecha_limite_inscripcion date,
    fecha_examen date,
    oposicion_relacionada text,
    convocatoria_origen_id uuid,
    resumen text,
    contenido_texto text,
    rango text,
    pagina_inicial integer,
    pagina_final integer,
    plazo_inscripcion_dias integer,
    titulacion_requerida text,
    tiene_temario boolean DEFAULT false,
    url_bases text,
    relevancia_score integer DEFAULT 0,
    destacada boolean DEFAULT false,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    ambito text,
    comunidad_autonoma text,
    provincia text,
    municipio text,
    slug text,
    CONSTRAINT convocatorias_boe_acceso_check CHECK (((acceso IS NULL) OR (acceso = ANY (ARRAY['libre'::text, 'promocion_interna'::text, 'mixto'::text, 'discapacidad'::text])))),
    CONSTRAINT convocatorias_boe_ambito_check CHECK (((ambito IS NULL) OR (ambito = ANY (ARRAY['estatal'::text, 'autonomico'::text, 'local'::text])))),
    CONSTRAINT convocatorias_boe_categoria_check CHECK (((categoria IS NULL) OR (categoria = ANY (ARRAY['A1'::text, 'A2'::text, 'B'::text, 'C1'::text, 'C2'::text])))),
    CONSTRAINT convocatorias_boe_tipo_check CHECK (((tipo IS NULL) OR (tipo = ANY (ARRAY['convocatoria'::text, 'admitidos'::text, 'tribunal'::text, 'resultado'::text, 'correccion'::text, 'otro'::text]))))
);


--
-- Name: convocatorias_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.convocatorias_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    convocatoria_id uuid NOT NULL,
    oposicion_id uuid,
    "año" integer,
    operation text NOT NULL,
    changed_fields text[],
    old_data jsonb,
    new_data jsonb,
    changed_by text,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
