-- Name: flota_dispute_contexto; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.flota_dispute_contexto WITH (security_invoker=off) AS
 SELECT qd.id AS dispute_id,
    up.target_oposicion AS reporter_oposicion,
    up.plan_type AS reporter_plan
   FROM (public.question_disputes qd
     LEFT JOIN public.user_profiles up ON ((up.id = qd.user_id)));


--
-- Name: VIEW flota_dispute_contexto; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.flota_dispute_contexto IS 'T-578: contexto NO identificativo de quien impugna (oposición y plan), para que la flota no tenga que deducirlo de los tags. Nunca añadir aquí nombre, email ni teléfono: para hablar con la persona está scripts/impugnaciones/cerrar.ts, que exige credenciales de persona.';


