    entregas_en_cola integer DEFAULT 0 NOT NULL,
    espera_mediana_h numeric,
    entregas_por_hora numeric,
    cerradas_por_hora numeric,
    manda text,
    horas_estimadas integer,
    veredicto text NOT NULL,
    razon text,
    CONSTRAINT flota_productividad_historico_manda_check CHECK ((manda = ANY (ARRAY['produccion'::text, 'revision'::text]))),
    CONSTRAINT flota_productividad_historico_veredicto_check CHECK ((veredicto = ANY (ARRAY['verde'::text, 'ambar'::text, 'rojo'::text])))
);


