);


--
-- Name: hot_articles_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.hot_articles_dashboard WITH (security_invoker='on') AS
 SELECT (((article_number || ' ('::text) || law_name) || ')'::text) AS articulo_completo,
    target_oposicion AS oposicion,
    hotness_score,
    priority_level,
    total_official_appearances AS apariciones,
    unique_exams_count AS examenes_distintos,
        CASE
            WHEN (hotness_score >= (85)::numeric) THEN '🔥 CRÍTICO'::text
            WHEN (hotness_score >= (65)::numeric) THEN '⚡ ALTO'::text
            WHEN (hotness_score >= (40)::numeric) THEN '📌 MEDIO'::text
            ELSE '💡 BAJO'::text
        END AS nivel_visual,
    last_calculation_date AS ultima_actualizacion
   FROM public.hot_articles ha
  ORDER BY target_oposicion, hotness_score DESC;


