--
-- Name: law_question_counts; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.law_question_counts AS
 SELECT l.id AS law_id,
    (count(q.id))::integer AS question_count,
    (count(q.id) FILTER (WHERE (q.is_official_exam = true)))::integer AS official_count
   FROM ((public.laws l
     LEFT JOIN public.articles a ON ((a.law_id = l.id)))
     LEFT JOIN public.questions q ON (((q.primary_article_id = a.id) AND (q.is_active = true))))
  GROUP BY l.id
  WITH NO DATA;


