--
-- Name: law_verification_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.law_verification_effective AS
 SELECT id AS law_id,
    short_name,
    scope,
    is_virtual,
    ((boe_url IS NOT NULL) AND (btrim(boe_url) <> ''::text)) AS has_source,
    (EXISTS ( SELECT 1
           FROM (public.topic_scope ts
             JOIN public.topics t ON ((t.id = ts.topic_id)))
          WHERE ((ts.law_id = l.id) AND t.disponible))) AS serving_live,
        CASE
            WHEN COALESCE(is_virtual, false) THEN 'verified'::text
            WHEN (last_verification_summary IS NULL) THEN
            CASE
                WHEN (lower(COALESCE(verification_status, ''::text)) = ANY (ARRAY['actualizada'::text, 'verificada'::text])) THEN 'false_green'::text
                WHEN ((boe_url IS NULL) OR (btrim(boe_url) = ''::text)) THEN 'no_source'::text
                ELSE 'never_verified'::text
            END
            WHEN ((((last_verification_summary ->> 'no_consolidated_text'::text))::boolean IS TRUE) OR (((last_verification_summary ->> 'historical'::text))::boolean IS TRUE) OR (((last_verification_summary ->> 'deliberate_subset'::text))::boolean IS TRUE)) THEN 'verified'::text
            WHEN (COALESCE(((last_verification_summary ->> 'missing_in_db'::text))::integer,
            CASE
                WHEN (((last_verification_summary ->> 'boe_count'::text) IS NOT NULL) AND ((last_verification_summary ->> 'db_count'::text) IS NOT NULL)) THEN GREATEST(0, (((last_verification_summary ->> 'boe_count'::text))::integer - ((last_verification_summary ->> 'db_count'::text))::integer))
                ELSE NULL::integer
            END) > 0) THEN 'incomplete'::text
            WHEN ((COALESCE(((last_verification_summary ->> 'content_mismatch'::text))::integer, 0) > 0) OR (COALESCE(((last_verification_summary ->> 'title_mismatch'::text))::integer, 0) > 0)) THEN 'issues'::text
            WHEN (((last_verification_summary ->> 'is_ok'::text))::boolean IS FALSE) THEN 'never_verified'::text
            ELSE 'verified'::text
        END AS effective_state
   FROM public.laws l;


--
-- Name: VIEW law_verification_effective; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.law_verification_effective IS 'Estado de verificación de cada ley contra su fuente. ESPEJO de lib/laws/completeness.ts (fuente única del criterio): si se toca uno, se toca el otro — lo vigila __tests__/integration/lawCompletenessConsistency.integration.test.ts, ley a ley.';


