-- Name: mv_oposiciones_activas; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_oposiciones_activas AS
 SELECT o.id,
    o.slug,
    o.nombre,
    o.short_name,
    o.categoria,
    o.administracion,
    o.grupo,
    o.subgrupo,
    o.tipo_acceso,
    o.titulo_requerido,
    o.salario_min,
    o.salario_max,
    o.color_primario,
    o.seo_title,
    o.seo_description,
    o.coverage_level,
    o.fetcher_type,
    o.headless_required,
    o.demand_score,
    o.seguimiento_url AS organismo_url,
    o.temas_count,
    o.bloques_count,
    c.id AS convocatoria_id,
    c."año" AS "convocatoria_año",
    c.convocatoria_numero,
    c.convocatoria_fecha,
    c.convocatoria_dogv,
    c.estado_proceso,
    c.oep_decreto,
    c.oep_fecha,
    c.plazas_libres,
    c.plazas_promocion_interna,
    c.plazas_discapacidad,
    c.boe_publication_date,
    c.boe_reference,
    c.inscription_start,
    c.inscription_deadline,
    c.exam_date,
    c.exam_date_approximate,
    c.programa_url,
    c.examen_config,
    c.landing_faqs,
    c.landing_estadisticas,
    c.landing_description,
    c.requisitos_especiales,
    c.seguimiento_last_checked,
    c.seguimiento_last_hash,
    c.seguimiento_change_status,
    c.seguimiento_change_detected_at
   FROM (public.oposiciones o
     LEFT JOIN public.convocatorias c ON (((c.oposicion_id = o.id) AND (c.is_current = true))))
  WHERE (o.is_active = true)
  WITH NO DATA;


--
-- Name: mv_teoria_law_catalog; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.mv_teoria_law_catalog AS
 WITH base AS (
         SELECT l.id AS law_id,
            l.short_name,
            l.name,
            l.description,
            l.slug,
            (count(*) FILTER (WHERE ((a.article_number ~* '^[0-9]+( *(bis|ter|qu[aá]ter|quinquies|sexies|septies|octies|nonies|novies|decies|undecies|duodecies))?( +[0-9]+)?$'::text) OR (a.article_number ~* '^(DA|DT|DD|DF)'::text))))::integer AS article_count
           FROM (public.laws l
             JOIN public.articles a ON (((a.law_id = l.id) AND (a.is_active = true) AND (a.content IS NOT NULL))))
          WHERE (l.is_active = true)
          GROUP BY l.id, l.short_name, l.name, l.description, l.slug
        )
 SELECT law_id,
    short_name,
    name,
    description,
    slug,
    article_count,
    public.immutable_unaccent(lower(((((COALESCE(short_name, ''::text) || ' '::text) || COALESCE(name, ''::text)) || ' '::text) || COALESCE(description, ''::text)))) AS search_text
   FROM base
  WHERE ((article_count > 0) AND ((slug IS NULL) OR ((slug !~~ '%-solo-escritorio'::text) AND (slug !~~ '%-solo-web'::text))))
  WITH NO DATA;


