--

CREATE TABLE public.prediction_tracking (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prediction_date date DEFAULT CURRENT_DATE NOT NULL,
    method_name text NOT NULL,
    predicted_sales_per_month numeric(10,2) NOT NULL,
    predicted_revenue_per_month numeric(10,2) NOT NULL,
    prediction_inputs jsonb DEFAULT '{}'::jsonb,
    actual_sales integer,
    actual_revenue numeric(10,2),
    error_percent numeric(6,2),
    absolute_error numeric(6,2),
    verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT prediction_tracking_method_name_check CHECK ((method_name = ANY (ARRAY['by_registrations'::text, 'by_active_users'::text, 'by_historic'::text, 'combined'::text])))
);


--
-- Name: prediction_accuracy_by_method; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.prediction_accuracy_by_method WITH (security_invoker='on') AS
 SELECT method_name,
    count(*) AS total_predictions,
    count(*) FILTER (WHERE (verified_at IS NOT NULL)) AS verified_predictions,
    round(avg(error_percent) FILTER (WHERE (verified_at IS NOT NULL)), 2) AS avg_error_percent,
    round(avg(absolute_error) FILTER (WHERE (verified_at IS NOT NULL)), 2) AS avg_absolute_error,
    round(stddev(error_percent) FILTER (WHERE (verified_at IS NOT NULL)), 2) AS error_stddev,
    min(absolute_error) FILTER (WHERE (verified_at IS NOT NULL)) AS best_prediction_error,
    max(absolute_error) FILTER (WHERE (verified_at IS NOT NULL)) AS worst_prediction_error,
    count(*) FILTER (WHERE ((verified_at IS NOT NULL) AND (absolute_error <= (20)::numeric))) AS predictions_within_20pct,
    max(prediction_date) FILTER (WHERE (verified_at IS NOT NULL)) AS last_verified_date
   FROM public.prediction_tracking
  GROUP BY method_name
  ORDER BY (round(avg(absolute_error) FILTER (WHERE (verified_at IS NOT NULL)), 2));


--
-- Name: prediction_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.prediction_history WITH (security_invoker='on') AS
 SELECT prediction_date,
    method_name,
    predicted_sales_per_month,
    predicted_revenue_per_month,
    actual_sales,
    actual_revenue,
    error_percent,
    absolute_error,
        CASE
            WHEN (absolute_error <= (10)::numeric) THEN 'excelente'::text
            WHEN (absolute_error <= (20)::numeric) THEN 'buena'::text
            WHEN (absolute_error <= (50)::numeric) THEN 'regular'::text
            ELSE 'mala'::text
        END AS prediction_quality,
    verified_at,
    prediction_inputs
   FROM public.prediction_tracking
  WHERE (verified_at IS NOT NULL)
  ORDER BY prediction_date DESC, method_name;


