--

COMMENT ON COLUMN public.reward_submissions.dispute_id IS 'Impugnación que originó la recompensa (type=''impugnacion''). Motivo trazable + clave anti-duplicado. Sin FK: puede ser legislativa o psicotécnica.';


--
-- Name: reward_earnings; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.reward_earnings AS
 SELECT r.referrer_user_id AS user_id,
    'referido'::text AS source,
    r.bounty_amount AS amount,
    r.status,
    r.qualified_at AS earned_at
   FROM public.referrals r
  WHERE (r.status = ANY (ARRAY['qualified'::text, 'payable'::text, 'paid'::text]))
UNION ALL
 SELECT r.referrer_user_id AS user_id,
    'registro_activo'::text AS source,
    (r.active_reward_amount)::numeric(10,2) AS amount,
    'granted'::text AS status,
    r.active_reward_at AS earned_at
   FROM public.referrals r
  WHERE (r.active_reward_at IS NOT NULL)
UNION ALL
 SELECT s.user_id,
    s.type AS source,
    s.amount,
    s.status,
    s.created_at AS earned_at
   FROM public.reward_submissions s
  WHERE (s.status = ANY (ARRAY['approved'::text, 'paid'::text]));


--
-- Name: VIEW reward_earnings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.reward_earnings IS 'Ingresos del embajador unificados por fuente (referido/bug/ugc/…). Capa escalable: añadir una fuente futura = añadir una rama UNION ALL. Lo consumen las stats del panel del embajador.';


