    status text DEFAULT 'open'::text NOT NULL,
    withdrawn_reason text,
    kind text DEFAULT 'pregunta'::text NOT NULL,
    draft_target text,
    CONSTRAINT session_questions_borrador_check CHECK (((kind <> 'borrador'::text) OR ((context IS NOT NULL) AND (length(btrim(context)) >= 40) AND (draft_target IS NOT NULL) AND (length(btrim(draft_target)) >= 3)))),
    CONSTRAINT session_questions_kind_check CHECK ((kind = ANY (ARRAY['pregunta'::text, 'borrador'::text]))),
    CONSTRAINT session_questions_question_check CHECK ((length(btrim(question)) >= 15)),
    CONSTRAINT session_questions_status_check CHECK ((status = ANY (ARRAY['open'::text, 'answered'::text, 'withdrawn'::text])))
);


