-- Name: settlement_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.settlement_summary WITH (security_invoker='on') AS
 SELECT count(*) AS total_payments,
    count(*) FILTER (WHERE (manuel_confirmed_received = false)) AS pending_payments,
    COALESCE(sum(amount_net), (0)::bigint) AS total_net,
    COALESCE(sum(manuel_amount), (0)::bigint) AS total_manuel,
    COALESCE(sum(armando_amount), (0)::bigint) AS total_armando,
    COALESCE(sum(manuel_amount) FILTER (WHERE (manuel_confirmed_received = false)), (0)::bigint) AS pending_manuel,
    COALESCE(sum(armando_amount) FILTER (WHERE (manuel_confirmed_received = false)), (0)::bigint) AS pending_armando
   FROM public.payment_settlements;


