--
-- Name: stats_drift_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stats_drift_log (
    id bigint NOT NULL,
    checked_at timestamp with time zone DEFAULT now() NOT NULL,
    target_table text NOT NULL,
    user_id uuid NOT NULL,
    field_name text NOT NULL,
    stored_value numeric,
    fresh_value numeric,
    drift_abs numeric GENERATED ALWAYS AS (abs((COALESCE(stored_value, (0)::numeric) - COALESCE(fresh_value, (0)::numeric)))) STORED,
    drift_pct numeric GENERATED ALWAYS AS (
CASE
    WHEN ((fresh_value IS NULL) OR (fresh_value = (0)::numeric)) THEN NULL::numeric
    ELSE round(((abs((COALESCE(stored_value, (0)::numeric) - fresh_value)) / abs(fresh_value)) * (100)::numeric), 2)
END) STORED,
    notes text
);


