--
-- Name: topic_epigrafe_verification; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.topic_epigrafe_verification (
    topic_id uuid NOT NULL,
    state text DEFAULT 'never_sourced'::text NOT NULL,
    source_convocatoria_id uuid,
    verified_epigrafe_hash text,
    verified_programa_hash text,
    findings jsonb,
    verified_by text,
    verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_url text,
    source_notes text,
    source_documento_id uuid,
    CONSTRAINT topic_epigrafe_verification_state_check CHECK ((state = ANY (ARRAY['never_sourced'::text, 'verified_literal'::text, 'drift_detected'::text, 'provisional_anterior'::text, 'needs_human'::text, 'stale'::text])))
);


--
-- Name: COLUMN topic_epigrafe_verification.source_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.topic_epigrafe_verification.source_url IS 'URL exacta de la fuente oficial donde se localizó/confirmó este epígrafe (DOGV/BOE PDF, anexo del temario). Para re-verificación directa.';


--
-- Name: COLUMN topic_epigrafe_verification.source_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.topic_epigrafe_verification.source_notes IS 'Comentario libre sobre el sourcing del epígrafe (p.ej. boletín no parseable, confirmado verbatim, PDF primario pendiente).';


--
-- Name: COLUMN topic_epigrafe_verification.source_documento_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.topic_epigrafe_verification.source_documento_id IS 'FK al documento oficial clonado (hub convocatoria_documentos) del que se clonó el epígrafe. Verdad de provenance; source_url es espejo. Invariante: verified_literal ⇒ NOT NULL (tras backfill).';


--
-- Name: topic_epigrafe_verification_effective; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.topic_epigrafe_verification_effective AS
 SELECT t.id AS topic_id,
    t.position_type,
    cv.id AS current_convocatoria_id,
    cv.programa_last_hash AS current_programa_hash,
    ev.state AS stored_state,
    ev.source_convocatoria_id,
    ev.verified_programa_hash,
        CASE
            WHEN (ev.topic_id IS NULL) THEN 'never_sourced'::text
            WHEN (ev.state = ANY (ARRAY['never_sourced'::text, 'stale'::text, 'drift_detected'::text])) THEN ev.state
            WHEN (cv.id IS DISTINCT FROM ev.source_convocatoria_id) THEN 'outdated_convocatoria'::text
            WHEN ((cv.programa_last_hash IS NOT NULL) AND (ev.verified_programa_hash IS NOT NULL) AND (cv.programa_last_hash <> ev.verified_programa_hash)) THEN 'outdated_convocatoria'::text
            ELSE ev.state
        END AS effective_state
   FROM (((public.topics t
     LEFT JOIN public.oposiciones o ON ((o.slug = replace(t.position_type, '_'::text, '-'::text))))
     LEFT JOIN public.convocatorias cv ON (((cv.oposicion_id = o.id) AND (cv.is_current = true))))
     LEFT JOIN public.topic_epigrafe_verification ev ON ((ev.topic_id = t.id)))
  WHERE t.is_active;


