CREATE TABLE public.topic_epigrafe_verification_history (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    topic_id uuid NOT NULL,
    state text NOT NULL,
    source_convocatoria_id uuid,
    epigrafe_hash text,
