    findings jsonb,
    verified_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: topic_law_question_summary; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.topic_law_question_summary AS
 SELECT ts.topic_id,
    ts.law_id,
    l.short_name AS law_short_name,
    l.name AS law_name,
    (count(q.id))::integer AS total_questions,
    (count(DISTINCT a.id) FILTER (WHERE (q.id IS NOT NULL)))::integer AS articles_with_questions,
    (count(q.id) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'easy'::text)))::integer AS count_easy,
    (count(q.id) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'medium'::text)))::integer AS count_medium,
    (count(q.id) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'hard'::text)))::integer AS count_hard,
    (count(q.id) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'extreme'::text)))::integer AS count_extreme,
    (count(q.id) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'auto'::text)))::integer AS count_auto,
    now() AS computed_at
   FROM (((public.topic_scope ts
     JOIN public.laws l ON ((ts.law_id = l.id)))
     LEFT JOIN public.articles a ON (((a.law_id = l.id) AND ((ts.article_numbers IS NULL) OR (a.article_number = ANY (ts.article_numbers))))))
     LEFT JOIN public.questions q ON (((q.primary_article_id = a.id) AND (q.is_active = true) AND (q.exam_case_id IS NULL))))
  GROUP BY ts.topic_id, ts.law_id, l.short_name, l.name
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW topic_law_question_summary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON MATERIALIZED VIEW public.topic_law_question_summary IS 'Fase D-bis Iter 1.5 — agregados pre-calculados por (topic_id, law_id) para getTopicFullData. Refresh nightly + on-demand admin. Fix #1 31/05/2026: COUNT(q.id) en vez de COUNT(*) para no contar las filas con q.id=NULL del LEFT JOIN questions en el bucket auto.';


--
-- Name: topic_official_by_position; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.topic_official_by_position AS
 SELECT ts.topic_id,
    COALESCE(lower(q.exam_position), ''::text) AS exam_position,
    (count(*))::integer AS official_questions,
    (count(*) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'easy'::text)))::integer AS count_easy,
    (count(*) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'medium'::text)))::integer AS count_medium,
    (count(*) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'hard'::text)))::integer AS count_hard,
    (count(*) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'extreme'::text)))::integer AS count_extreme,
    (count(*) FILTER (WHERE (public.topic_question_difficulty_bucket(q.global_difficulty, q.difficulty) = 'auto'::text)))::integer AS count_auto,
    now() AS computed_at
   FROM ((public.topic_scope ts
     JOIN public.articles a ON (((a.law_id = ts.law_id) AND ((ts.article_numbers IS NULL) OR (a.article_number = ANY (ts.article_numbers))))))
     JOIN public.questions q ON ((q.primary_article_id = a.id)))
  WHERE ((q.is_active = true) AND (q.exam_case_id IS NULL) AND (q.is_official_exam = true))
  GROUP BY ts.topic_id, COALESCE(lower(q.exam_position), ''::text)
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW topic_official_by_position; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON MATERIALIZED VIEW public.topic_official_by_position IS 'Preguntas de examen oficial por (tema, exam_position), con desglose por cubo de dificultad. Doble uso: contar las oficiales PROPIAS de la oposición (rótulo "🏛️ N de exámenes oficiales") y DESCONTAR las AJENAS del total anunciado, porque buildOfficialExamFilter nunca las sirve [T-507].';


