--
-- Name: v_attribution_coverage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_attribution_coverage AS
 SELECT (up.created_at)::date AS dia,
    count(*) AS altas,
    count(ua.user_id) AS con_canal,
    round(((100.0 * (count(ua.user_id))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS pct_cobertura,
    count(*) FILTER (WHERE (ua.channel = 'google_ads'::text)) AS google_ads,
    count(*) FILTER (WHERE (ua.channel = 'meta_ads'::text)) AS meta_ads,
    count(*) FILTER (WHERE (ua.channel = 'organic'::text)) AS organic,
    count(*) FILTER (WHERE (ua.channel = 'direct'::text)) AS direct,
    count(*) FILTER (WHERE (ua.user_id IS NULL)) AS sin_atribucion
   FROM (public.user_profiles up
     LEFT JOIN public.user_acquisition ua ON ((ua.user_id = up.id)))
  GROUP BY ((up.created_at)::date);


--
-- Name: VIEW v_attribution_coverage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_attribution_coverage IS 'Fase atribución: cobertura de canal por día (% de altas con user_acquisition) + desglose. Observabilidad del fix de cobertura. Consultar por getAdminDb.';


--
-- Name: v_campaign_revenue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_campaign_revenue AS
 SELECT COALESCE(ua.last_utm_campaign, ua.utm_campaign) AS campaign_id,
    count(*) AS ventas,
    sum(((ce.event_data ->> 'amount'::text))::numeric) AS ingreso,
    (min(ce.created_at))::date AS primera_venta,
    (max(ce.created_at))::date AS ultima_venta
   FROM (public.conversion_events ce
     JOIN public.user_acquisition ua ON ((ua.user_id = ce.user_id)))
  WHERE ((ce.event_type = 'payment_completed'::text) AND (COALESCE(ua.last_utm_campaign, ua.utm_campaign) IS NOT NULL))
  GROUP BY COALESCE(ua.last_utm_campaign, ua.utm_campaign);


--
-- Name: VIEW v_campaign_revenue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_campaign_revenue IS 'Fase atribución (F2): ingreso real por campaña (utm_campaign = id numérico de Google Ads). Lado revenue del ROAS; el coste viene de la API de Ads. Se poblará según compren usuarios ya atribuidos.';


--
-- Name: v_config_feature_usage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_config_feature_usage AS
 SELECT feat.feature,
    (ev.event_data ->> 'plan'::text) AS plan,
    (count(*))::integer AS uses,
    (count(DISTINCT ev.user_id))::integer AS users,
    max(ev.created_at) AS last_used
   FROM (public.conversion_events ev
     CROSS JOIN LATERAL jsonb_array_elements_text((ev.event_data -> 'features'::text)) feat(feature))
  WHERE (ev.event_type = 'config_features_used'::text)
  GROUP BY feat.feature, (ev.event_data ->> 'plan'::text)
  ORDER BY ((count(*))::integer) DESC;


--
-- Name: VIEW v_config_feature_usage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_config_feature_usage IS 'Uso de features del configurador por feature x plan (free/premium). Fuente: conversion_events config_features_used. Decide que gatear: free que usan mucho = candidata. Ver docs/runbooks/premium-gating.md';


--
-- Name: v_insert_test_questions_latency; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_insert_test_questions_latency AS
 SELECT "left"(query, 120) AS query_snippet,
    calls,
    round((total_exec_time)::numeric, 1) AS total_ms,
    round((mean_exec_time)::numeric, 3) AS mean_ms,
    round((stddev_exec_time)::numeric, 3) AS stddev_ms,
    round((min_exec_time)::numeric, 3) AS min_ms,
    round((max_exec_time)::numeric, 3) AS max_ms,
    round(((mean_exec_time + ((2)::double precision * stddev_exec_time)))::numeric, 3) AS proxy_p95_ms,
    rows AS total_rows_affected
   FROM extensions.pg_stat_statements
  WHERE ((query ~~* 'INSERT INTO%test_questions%'::text) OR (query ~~* 'insert into "test_questions"%'::text))
  ORDER BY total_exec_time DESC;


--
-- Name: VIEW v_insert_test_questions_latency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_insert_test_questions_latency IS 'Lectura directa de pg_stat_statements para INSERT a test_questions. Usada por /admin/infraestructura tab Salud Sistema. Reset implícito en failovers. Runbook: docs/runbooks/health-check.md.';


--
-- Name: v_materialization_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_materialization_health AS
 SELECT table_name,
    last_updated,
    (round((EXTRACT(epoch FROM (now() - last_updated)) / (60)::numeric)))::integer AS lag_min,
    (last_updated > (now() - '00:20:00'::interval)) AS fresh
   FROM ( SELECT 'user_question_history_v2'::text AS table_name,
            max(user_question_history_v2.updated_at) AS last_updated
           FROM public.user_question_history_v2
        UNION ALL
         SELECT 'user_article_stats'::text,
            max(user_article_stats.updated_at) AS max
           FROM public.user_article_stats
        UNION ALL
         SELECT 'user_difficulty_stats'::text,
            max(user_difficulty_stats.updated_at) AS max
           FROM public.user_difficulty_stats
        UNION ALL
         SELECT 'user_daily_stats'::text,
            max(user_daily_stats.updated_at) AS max
           FROM public.user_daily_stats
        UNION ALL
         SELECT 'user_hourly_stats'::text,
            max(user_hourly_stats.updated_at) AS max
           FROM public.user_hourly_stats
        UNION ALL
         SELECT 'user_stats_summary'::text,
            max(user_stats_summary.updated_at) AS max
           FROM public.user_stats_summary) m
  ORDER BY ((round((EXTRACT(epoch FROM (now() - last_updated)) / (60)::numeric)))::integer) DESC;


--
-- Name: VIEW v_materialization_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_materialization_health IS 'Frescura de las tablas materializadas (pipeline outbox->handlers). updated_at = señal canonica de frescura (NO last_attempt_at, que solo se pone en INSERT). Ver docs/runbooks/materialization-health.md';


--
-- Name: v_pg_stat_statements_delta; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pg_stat_statements_delta AS
 WITH snapshots_ordered AS (
         SELECT DISTINCT pg_stat_statements_snapshots.snapshot_at
           FROM public.pg_stat_statements_snapshots
          ORDER BY pg_stat_statements_snapshots.snapshot_at DESC
         LIMIT 2
        ), ranked AS (
         SELECT snapshots_ordered.snapshot_at,
            row_number() OVER (ORDER BY snapshots_ordered.snapshot_at DESC) AS rn
           FROM snapshots_ordered
        ), today AS (
         SELECT s.snapshot_at,
            s.queryid,
            s.calls,
            s.total_exec_ms,
            s.mean_exec_ms,
            s.max_exec_ms,
            s.stddev_exec_ms,
            s.rows,
            s.query
           FROM (public.pg_stat_statements_snapshots s
             JOIN ranked r ON (((r.snapshot_at = s.snapshot_at) AND (r.rn = 1))))
        ), yesterday AS (
         SELECT s.snapshot_at,
            s.queryid,
            s.calls,
            s.total_exec_ms,
            s.mean_exec_ms,
            s.max_exec_ms,
            s.stddev_exec_ms,
            s.rows,
            s.query
           FROM (public.pg_stat_statements_snapshots s
             JOIN ranked r ON (((r.snapshot_at = s.snapshot_at) AND (r.rn = 2))))
        )
 SELECT t.snapshot_at AS today_snapshot_at,
    y.snapshot_at AS yesterday_snapshot_at,
    t.queryid,
    (t.calls - COALESCE(y.calls, (0)::bigint)) AS calls_delta_24h,
    (t.total_exec_ms - COALESCE(y.total_exec_ms, (0)::numeric)) AS total_ms_delta_24h,
        CASE
            WHEN ((t.calls - COALESCE(y.calls, (0)::bigint)) > 0) THEN (((t.total_exec_ms - COALESCE(y.total_exec_ms, (0)::numeric)) / (NULLIF((t.calls - COALESCE(y.calls, (0)::bigint)), 0))::numeric))::numeric(12,2)
            ELSE NULL::numeric
        END AS mean_ms_last_24h,
    t.mean_exec_ms AS mean_ms_all_time,
    t.max_exec_ms AS max_ms_all_time,
    t.calls AS calls_all_time,
    "left"(t.query, 200) AS query_preview,
    t.query AS query_full
   FROM (today t
     LEFT JOIN yesterday y ON ((y.queryid = t.queryid)))
  WHERE ((t.calls - COALESCE(y.calls, (0)::bigint)) > 5)
  ORDER BY (t.total_exec_ms - COALESCE(y.total_exec_ms, (0)::numeric)) DESC;


--
-- Name: VIEW v_pg_stat_statements_delta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_pg_stat_statements_delta IS 'Top queries por tiempo total consumido en las últimas 24h (delta real entre los 2 snapshots más recientes). Usar para diagnóstico de incidentes: si mean_ms_last_24h >> mean_ms_all_time hay degradación reciente. Roadmap: docs/roadmap/observability-capacity.md Acción 3.';


--
-- Name: v_pgbouncer_instances_last_15min; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pgbouncer_instances_last_15min AS
 SELECT instance,
    az,
    count(*) AS samples,
    count(*) FILTER (WHERE (NOT reachable)) AS unreachable_samples,
    max(select1_ms) AS max_select1_ms,
    max(cl_waiting) AS max_cl_waiting,
    max(maxwait_us) AS max_maxwait_us,
    max(sample_at) AS last_sample_at
   FROM public.pgbouncer_instance_samples
  WHERE (sample_at > (now() - '00:15:00'::interval))
  GROUP BY instance, az
  ORDER BY instance;


--
-- Name: v_pool_capacity_last_15min; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_pool_capacity_last_15min AS
 SELECT sample_at,
    total_conns,
    active_conns,
    idle_in_tx_over_5s,
    long_active_over_5s,
    hung_clientread_over_10s,
    frontend_active_conns,
        CASE
            WHEN ((idle_in_tx_over_5s > 0) OR (hung_clientread_over_10s > 0)) THEN 'RED'::text
            WHEN ((long_active_over_5s > 0) OR (active_conns > 20)) THEN 'AMBER'::text
            ELSE 'GREEN'::text
        END AS status,
    by_app
   FROM public.pool_capacity_samples
  WHERE (sample_at > (now() - '00:15:00'::interval))
  ORDER BY sample_at DESC;


--
-- Name: VIEW v_pool_capacity_last_15min; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_pool_capacity_last_15min IS 'Top muestras del pool en los últimos 15 minutos con status calculado (GREEN/AMBER/RED). Usar para diagnóstico operacional rápido.';


--
-- Name: v_premium_gate_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_premium_gate_funnel AS
 WITH ev AS (
         SELECT (conversion_events.event_data ->> 'feature'::text) AS feature,
            (conversion_events.event_data ->> 'kind'::text) AS kind,
            conversion_events.event_type,
            conversion_events.user_id,
            conversion_events.created_at
           FROM public.conversion_events
          WHERE ((conversion_events.event_type = ANY (ARRAY['premium_gate_shown'::text, 'premium_gate_cta_click'::text, 'premium_gate_dismiss'::text])) AND ((conversion_events.event_data ->> 'feature'::text) IS NOT NULL))
        )
 SELECT feature,
    max(kind) AS kind,
    (count(*) FILTER (WHERE (event_type = 'premium_gate_shown'::text)))::integer AS shown,
    (count(*) FILTER (WHERE (event_type = 'premium_gate_cta_click'::text)))::integer AS cta_click,
    (count(*) FILTER (WHERE (event_type = 'premium_gate_dismiss'::text)))::integer AS dismiss,
    (count(DISTINCT user_id) FILTER (WHERE (event_type = 'premium_gate_shown'::text)))::integer AS users_shown,
    round(((100.0 * (count(*) FILTER (WHERE (event_type = 'premium_gate_cta_click'::text)))::numeric) / (NULLIF(count(*) FILTER (WHERE (event_type = 'premium_gate_shown'::text)), 0))::numeric), 1) AS cta_rate_pct,
    max(created_at) FILTER (WHERE (event_type = 'premium_gate_shown'::text)) AS last_shown
   FROM ev
  GROUP BY feature
  ORDER BY ((count(*) FILTER (WHERE (event_type = 'premium_gate_shown'::text)))::integer) DESC;


--
-- Name: VIEW v_premium_gate_funnel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_premium_gate_funnel IS 'Embudo del gating premium por-feature (premium_gate_shown -> cta_click). Fuente: conversion_events. Ver docs/runbooks/premium-gating.md';


