--
-- Name: admin_upgrade_message_stats _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.admin_upgrade_message_stats WITH (security_invoker='on') AS
 SELECT um.id,
    um.message_key,
    um.title,
    um.is_active,
    um.weight,
    count(umi.id) AS total_impressions,
    count(umi.id) FILTER (WHERE umi.clicked_upgrade) AS total_clicks,
    count(umi.id) FILTER (WHERE umi.dismissed) AS total_dismisses,
    count(umi.id) FILTER (WHERE umi.converted_to_premium) AS total_conversions,
    round((((count(umi.id) FILTER (WHERE umi.clicked_upgrade))::numeric / (NULLIF(count(umi.id), 0))::numeric) * (100)::numeric), 2) AS click_rate,
    round((((count(umi.id) FILTER (WHERE umi.converted_to_premium))::numeric / (NULLIF(count(umi.id), 0))::numeric) * (100)::numeric), 2) AS conversion_rate
   FROM (public.upgrade_messages um
     LEFT JOIN public.upgrade_message_impressions umi ON ((umi.message_id = um.id)))
  GROUP BY um.id
  ORDER BY (count(umi.id)) DESC;


